export default [{"id":180,"question":"هذا سائلٌ يقول: إنه قد جاءني رجلٌ وقال: إنَّ في زوجتك سحرًا، فلا بأس أن تذهب للكاهن، ولكن بدون تصديقه، فما الحكم، أثابكم الله؟","title":"هل يجوز الذهاب للكاهن دون تصديقه؟","answer":"الجواب: لا، لا تُصدقه، لا تُصدق السَّحرة، ولا تذهب إلى السَّحرة، اقرأ عليها وانفث عليها بآية الكرسي والفاتحة: الْحَمْدُ لِلَّهِ [الفاتحة:2] وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، وتبرأ إن شاء الله، وهي كذلك تنفث على نفسها وتتعوَّذ بكلمات الله التامَّات من شرِّ ما خلق، وتبرأ إن شاء الله، وتقرأ الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، أنت تقرأ عليها، أو هي تقرأ على نفسها ويزول: قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، تُكرر عليها ثلاث مرات في القراءة، وهي من أسباب الشِّفاء والعافية من كل بلاءٍ، ولا تذهبوا إلى السَّحرة، لا يجوز الذّهاب إلى السحرة، ولا سؤالهم، ولا تصديقهم.","link":"https://binbaz.org.sa/fatwas/3751/هل-يجوز-الذهاب-للكاهن-دون-تصديقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0181.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":329,"question":"السلام عليكم ورحمة الله وبركاته، لقد طالعتنا بعضُ الجرائد بأن جنيًّا قد أسلم على يدي سماحتكم، فأرجو توضيح هذا الخبر، وهل يسكن أو يمسّ الجنُّ الإنسان؟","title":"ما قصة إسلام الجني عند الشيخ ابن باز؟","answer":"الجواب: نعم هذا الخبر صحيحٌ، وقد حكى أبو العباس ابنُ تيمية إجماعَ العلماء على إمكان دخول الجني بالإنسي وصرعه إياه، وهذا واقعٌ من عهد النبي إلى يومنا هذا، وقبله كذلك، ومَن استنكر هذا أو شكَّ في هذا؛ فهو من عدم البصيرة، ومن عدم قراءة كتب العلماء، وعدم الاطلاع على ما ذكره العلماء في هذا السَّبيل.\nوقد حضرت عندي امرأةٌ وأولياؤها، وجماعةٌ من أهل العلم حضروا ذلك، وكان قد عالج المرأة الأخُ في الله عبدالله بن يوسف العمري إمام مسجد العُلياء، ووجّه هذا الجني إلى الإسلام، ونصحه، ودعاه إليه، ورغَّبه في الخير، وحذَّره من الظلم، وأوصاه بالخروج من هذه المرأة، والبعد عنها، والكفّ عن أذاها، فتقبّل منه.\nوطلب أولياء المرأة من الراقي أن يحضر عندي هو والمرأة لإعلان إسلامه، فحضروا جميعًا عندي: حضر جمعٌ من المسلمين، وحضر أخواها، وخالها، وأختها، وجماعةٌ من طلبة العلم، وتحدَّث هو على لسان المرأة بصوت رجلٍ لا شكَّ فيه، وتكلم عن أسباب دخوله فيها وتلبُّسه فيها، وذكر أسباب ذلك، وذكر أنه بوذيٌّ، جني من الجن، وأنه اقتنع بوصية المرشد عبدالله بن يوسف العمري، وقَبِلَ منه دعوته، وهداه الله لقبول الإسلام، وأعلن عندي إسلامه، ووصيتُه بما يلزم من الدَّعوة إلى الله في قومه، وأن يكون من شكر الله على نعمة الإسلام أن يدعو قومه، وأن يُوصيهم بالخير كما هداه الله، وكان آخر كلامه بعد المُحادثة أن قال: \"السلام عليكم\"، ثم انفصل عنها.\nوهي بحمد الله بخيرٍ وعافيةٍ، وقد دعوتها منذ أيام قلائل أيضًا وسألتُها عن حالها فقالت: إنها بصحةٍ وعافيةٍ، وأنه لم يعد إليها بعد ذلك من حين غادرها، فذكرت أنها بعدما أصابها هذا من نحو سنتين وهو يُصيبها منه أذى كثير، ومشقَّة كبيرة، وأنه وسوس إليها بأفكار هدّامة، ودعوة إلى البوذية، وأنها تحسّ بنفسها بميول إلى الأفكار الرديئة والديانة البوذية، فلما سلَّمها الله منه؛ زالت عنها تلك الأفكار، وعادت إلى حالها الأولى وطبيعتها الأولى بإسلامها ودينها.\nالمقصود أنَّ هذا واقعٌ، وهذا قد وقع لغيرنا من العلماء القدامى والإمام أحمد بن حنبل، وشيخ الإسلام ابن تيمية، ولغيرهم، وقد وضح ذلك أهلُ العلم، وليس فيه إشكال، والرسول عليه الصلاة والسلام قال: إنَّ الشيطان يجري من ابن آدم مجرى الدم، والجن أقسام، ليسوا على قسمٍ واحدٍ، أقسام، ففي \"الصحيحين\" عن النبي ﷺ قال: إنَّ الشيطان يجري من ابن آدم مجرى الدم.","link":"https://binbaz.org.sa/fatwas/4417/ما-قصة-اسلام-الجني-عند-الشيخ-ابن-باز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0382.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":917,"question":"ما حكم الإسلام في الذَّهاب إلى السَّحرة بخصوص عمل حجابٍ لاستجلاب المحبَّة بين زوجين معهما أطفال كادا أن يتفرقا؟","title":"حكم الذَّهاب للسَّحرة لجلب المحبَّة بين زوجين","answer":"الجواب: الذهاب إلى السَّحرة منكر، والكهنة والعرَّافون لا يجوز الذَّهاب إليهم، ولا سؤالهم، ولا تصديقهم، يقول النبي ﷺ: مَن أتى عرَّافًا فسأله عن شيءٍ لم تُقبل له صلاة أربعين ليلة.\nالعرَّاف الذي يدَّعي ماهية الأمور، بدعوى علم الغيب، وبخدمة الشياطين والجن، أو بالكف، أو ما أشبه ذلك من الخرافات، أو باستحضار الأرواح، كل هؤلاء يُقال لهم: عرَّافون، ويُقال لهم: كهنة، وهكذا مَن يتعاطى السحر بالنظر في النجوم، وبغير ذلك، أو باستخدام الشياطين، وكل هؤلاء لا يُؤتَون، ولا يُسألون.\nومَن كانت كهانته وسحره بعبادة غير الله وسؤال الشياطين والاستغاثة بهم صار كفرًا أكبر -نعوذ بالله- والسحرة معلومٌ أنهم إنما يتعاطون من طريق عبادة الجنّ وخدمتهم، ولهذا قال : وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ يعني: الملكين حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102]، فدلَّ على أنَّ السحر كفرٌ.\nولكن للمُصاب بالأمراض -الحمد لله- دواء بالقراءة من القُرَّاء المعروفين بالتقوى والإيمان، بتعاطي الطب المعروف المادي، ليقرأ على نفسه هو، أو يقرأ عليه أخوه، أو أبوه، أو نحو ذلك، فالله جعل في القرآن شفاءً أيضًا من أمراضٍ كثيرةٍ، كما أنه شفاءٌ للقلوب من أمراضها وشركها ونفاقها وكبرها وحسدها، فهو شفاءٌ لكثيرٍ من أمراض الأبدان أيضًا بإذنه سبحانه وتعالى، فإذا قرأ على نفسه الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، أو قرأ عليه أخوه، أو أبوه، أو أمه، أو نحو ذلك، أو بعض الأخيار من أهل الإيمان والتقوى؛ يُرجى له الخير والعافية.","link":"https://binbaz.org.sa/fatwas/20967/حكم-الذهاب-للسحرة-لجلب-المحبة-بين-زوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0763ما حكم الإسلام في الذهاب إلى السحرة لعمل حجاب لاستجلاب المحابة بين الزوجين؟ابن باز.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":1023,"question":"كيف يمكن العلاج من السحر؟","title":"ما كيفية العلاج من السحر؟","answer":"الجواب: العلاج من السحر يكون بالرقية من كلام الله، وبالدعوات الطيبة، يُرقى المريضُ بالآيات: آية الكرسي، بالفاتحة، وقُلْ هُوَ اللَّهُ أَحَدٌ، والمعوذتين، وغيرها من الآيات، وإذا قرأ في ماءٍ أيضًا وشرب منه وتروش به فهو من العلاج، وهو أيضًا مما ينفع من حبس الرجل عن زوجته وعن امرأته، كونه ينفث على نفسه بالفاتحة، وآية الكرسي، وبـقُلْ هُوَ اللَّهُ أَحَدٌ، والمعوذتين، أو ينفث عليه غيره، أو يقرأ ذلك في ماءٍ ثم يشرب منه ويصبُّه على بدنه، كل ذلك من العلاج.\nوإن جعل في البيت سبع ورقات من السدر: دقَّها وجعلها في ماءٍ، فهذا أيضًا مما ينفع من حبس الرجل عن امرأته، ومما ينفع من السحر.\nولا يجوز الذهاب إلى السحرة، ولا الكهنة، لا، ولكن يُعالج نفسه بآيات الله، إما بأن يقرأ هو بنفسه على نفسه، يقرأ في يديه، يمسح بهما على رأسه ووجهه وصدره، وهكذا عند النوم، كان النبيُّ يفعل هذا، إذا اشتكى قرأ في يديه: قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، عند النوم، ومسح بهما ما أقبل من جسده: رأسه ووجهه وصدره ثلاث مراتٍ عليه الصلاة والسلام، كل هذا من أسباب الشِّفاء.\nوقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ وقُلْ أَعُوذُ بِرَبِّ النَّاسِ سورتان عظيمتان، علاجٌ لكل داءٍ، لكل مرضٍ، ما تعوَّذ مُتعوِّذٌ بمثلهما كما جاء في الحديث، فإذا قرأ على نفسه: قُلْ هُوَ اللَّهُ أَحَدٌ... وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ... وقُلْ أَعُوذُ بِرَبِّ النَّاسِ... وكرر ذلك، أو قرأ في ماءٍ وشربه وتروّش به، أو قرأ له غيرُه من إخوانه، أو فعل ذلك عند النوم ومسح على ما أقبل من جسده: رأسه وصدره ووجهه، كل هذا من العلاج،. والعلاج يفعله الإنسانُ بنفسه، أو يفعله غيرُه من طلبة العلم... يقرأ عليه أحدُ طلبة العلم، أو أخوه، أو أبوه، أو هو على زوجته، أو زوجته عليه إذا كانت تُحسن ذلك، الأمر واسع بحمد الله، تقرأ بنفسك، تنفث بنفسك، ينفث عليك أخوك، إخوانك المعروفون بالخير، أو ينفث عليك أخوك، أو أبوك، أو زوجتك، أو أختك، أو أمك، تقرأ الفاتحة، وآية الكرسي، وما تيسر من القرآن، وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، كل هذا من العلاج للسحر ولأمراضٍ أخرى، ولحبس الرجل عن زوجته.","link":"https://binbaz.org.sa/fatwas/21074/ما-كيفية-العلاج-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0870كيف العلاج من السحر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":1154,"question":"ما رأي سماحتكم أن يفكَّ المسلمُ السحرَ عن نفسه بالسحر؟","title":"ما حكم فك السحر بسحر آخر؟","answer":"الجواب:\nنصَّ العلماء على تحريم حلِّ السحر بالسحر، واحتجُّوا على هذا بقوله ﷺ لما سُئل عن النّشرة قال: هي من عمل الشيطان، والنشرة هي: حلّ السحر بالسحر، كما كان عليه الجاهلية.  أما حلُّه بالقرآن والتَّعوذات والأدوية الشرعية فلا بأس بذلك، وليس من عمل الشيطان، فلا يجوز حله بالسحر؛ لأنَّ السحر لا يُتوصل إليه إلا بالشرك وعبادة الجن، ولكن يُحلُّ بالقراءة والدَّعوات والأدوية المباحة التي أرشد إليها القرآنُ، وجاءت بها السنة.","link":"https://binbaz.org.sa/fatwas/21209/ما-حكم-فك-السحر-بسحر-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1005ما حكم فك السحرعن نفسه بسحر آخر؟ ابن باز.mp3","categories":["السحر والكهانة"]},{"id":1257,"question":"هل كل ساحرٍ كافر؟","title":"هل كل ساحرٍ كافر؟","answer":"الجواب:\nالمعروف في الساحر أنه يتعاطى عبادة الجنّ، فالسحر الذي يكون عن عبادة غير الله يكون كافرًا، كما قال جلَّ وعلا: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102]، فالسحرة كفَّار؛ لأنهم يتعبَّدون بدعاء الجن، والاستغاثة بالجن.\nأما إذا كان شيئًا آخر وتعاطاه الناس: أدوية أو أشياء أخرى ما لها تعلّق بالجن، ولا بدعاء غير الله؛ هذا ما يُسمَّى: سحرًا، يُسمَّى: إيذاء، ويُسمَّى: ظلمًا، وأشباه ذلك، لا يُسمَّى: سحرًا.","link":"https://binbaz.org.sa/fatwas/21317/هل-كل-ساحر-كافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1060هل كل ساحر كافر؟ ابن باز فتاوى.mp3","categories":["السحر والكهانة"]},{"id":2022,"question":"سحر  التخييل، الآن يُستعمل..؟","title":"ما أنواع السحر ووصف كل منها؟","answer":"الجواب:\nالسحر سحران: سحر بالعمل، وسحر بالتخييل، سحر أصحاب فرعون بالتخييل يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] جابوا عصيًّا وجابوا حبالًا وفعلوا أشياء..... على الناس أن العصي تمشي، وأن الحبال تمشي، وأنها حيات، صار تخييلًا، وهذا يقع كثيرًا من الناس، يدخل على الناس في دكاكينهم وغيرهم ويُغَيِّرون عليهم ويأخذون أموالهم، وهذا سحر خبيث.\nوالسحر الثاني: بأعمال الشياطين من أدوية ونفث في العُقُد وغير ذلك مما يفعلون مع الشياطين؛ حتى يؤثروا في الإنسان بإذن الله وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] إذن الله الكوني القدري، فيكون من نفث العُقُد، ويكون بأدوية يسقونها الرجل أو يُنَشِّقونها إياها حتى تؤثر في رأسه، أو تخييل يعملونه مع أشياء يتخيل حتى يرى زوجته في غير الصورة التي كانت عليها حتى يبغضها، أو يخيلون للمرأة في زوجها حتى ترى زوجها في غير الصورة التي تعرفه كأنه يعني دابة أو كأنه حنش أو كأنه يعني..؛ حتى تبغضه، أو بصورة دميمة حتى يحصل البغضاء بينهما، وهذه هي التِّوَلة، وهي الصَّرْف، هي عمل النساء، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22138/ما-انواع-السحر-ووصف-كل-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أنواع السحر.mp3","categories":["السحر والكهانة"]},{"id":2024,"question":"هناك أناس يسمون بالسحرة ولهم ألعاب بهلوانية ويمارسون شرك التخييل..؟","title":"حكم الألعاب البهلوانية وهل هي من السحر؟","answer":"الجواب:\nإذا عَرَفَهم يُرفع بأمرهم إلى ولي الأمر، إذا كانوا في هذه المملكة يرفع بأمرهم إلى ولي الأمر حتى يُقتلوا.\nس: كيف يميز بين الألعاب البهلوانية وبين السحر؟\nالشيخ: تُعرف، تُعرف، الفئات بعض الناس يُشَبِّه على الناس، يخرج من فمه بيضًا أو طيورًا أو كذا، هذا سحر التخييل، أخبرنا كثير من الناس أنه عند اللعب يشوفونه يخرج من فمه طيرًا وإلا بيضة وهو ما له شيء، ويشوفونه يمشي على الحبل وهو ما مشى على الحبل أحد، كل هذا تخييل مثل شغل سحرة فرعون؛ حطوا الحبال والعصي في الأرض ويحسبونه الحَيَّات.","link":"https://binbaz.org.sa/fatwas/22140/حكم-الالعاب-البهلوانية-وهل-هي-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الألعاب البهلوانية والفرق بينها والسحر.mp3","categories":["السحر والكهانة"]},{"id":2365,"question":"بالنسبة لبعض البيوت تؤذيهم فيها الشياطين، إما بحريق، أو بأذية داخل البيت، ما هو سبب (النجاة من هذا)؟","title":"ما أسباب سلامة البيوت من أذى الشياطين؟","answer":"الجواب:\nلا شك أن من الأسباب: التوبة إلى الله والضراعة إليه وسؤاله العافية من شرهم.... يتعوَّذ بالله من شرهم، ويقول لهم: كُفُّوا شركم عنا، نعوذ بالله منكم، بقوة ونشاط وهمة عالية، مع التوبة الصادقة والعمل الصالح والضراعة إلى الله بأن يكفيهم شرهم، لابد... شياطين الجن مثل شياطين الإنس؛ إن رأوا قوة ورأوا نشاطًا وهمة عالية؛ كَفُّوا، وإن رأوا ضعفًا وخوفًا؛ نَشَطوا، نسأل الله العافية.\nفينبغي لأهل الإيمان النشاط والقوة الضراعة إلى الله والتوبة إليه وقوة الثقة بالله ، والتَّعَوَّذ بالله من شر هؤلاء، بالصراحة، خاصموهم وتكلموا معهم وحذِّروهم.\nس: وضع مُسَجِّل لقراءة آية الكرسي يحصل في هذا الأجر؟\nج: يقرأ هو ويتكلم، يتعوَّذ بالله من شرهم، ويسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22490/ما-اسباب-سلامة-البيوت-من-اذى-الشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أذية الشياطين لبعض البيوت.mp3","categories":["السحر والكهانة"]},{"id":2606,"question":"هل يُعالج السحر بسحرٍ مِثْلِه؟","title":"ما حكم معالجة السحر بسحر مثله؟","answer":"الجواب: لا، لا يجوز، يُعالج بالقرآن والأدوية المباحة والدعاء، وأما السحر فلا، مثل ما قال ﷺ لما سئل عن النُّشرَةِ قال: هي من عمل الشيطان.","link":"https://binbaz.org.sa/fatwas/22741/ما-حكم-معالجة-السحر-بسحر-مثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معالجة السحر بسحر مثله.mp3","categories":["السحر والكهانة"]},{"id":3734,"question":"الذهاب للمنجمين وتصديقهم؟","title":"حكم الذهاب للمنجمين وتصديقهم","answer":"الجواب: هذا يتعلق بالكُهان، تقدّم، إتيان الكهان لا يجوز، من أكبر الكبائر، وإذا صدَّقهم كفر، نسأل الله العافية، ولا يجوز سؤالهم ولو ما صدقهم، يقول ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا حتى ولو ما صدقه، نسأل الله العافية؛ لأنه وسيلة إلى القول بعلم الغيب.","link":"https://binbaz.org.sa/fatwas/23926/حكم-الذهاب-للمنجمين-وتصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذهاب للمنجمين وتصديقهم.mp3","categories":["السحر والكهانة"]},{"id":3857,"question":"بعض السحر إذا حاول الإنسان حله قد يضره بمرض، فهل الأوْلى دفنه، أم لا بد من دفنه؟","title":"ما كيفية إبطال السحر بعد العثور عليه؟","answer":"الجواب: الذي يظهر أنه لا بدّ من إتلافه؛ حتى يبطل، إتلافه، إذا كان هناك معقود يُبطل، إذا كان شيء ملصوق بعضه ببعض يُبطل، ثم يُتلف، أو يُحرق؛ لئلا يبقى له أثر.","link":"https://binbaz.org.sa/fatwas/24068/ما-كيفية-ابطال-السحر-بعد-العثور-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في السحر وحله.mp3","categories":["السحر والكهانة"]},{"id":3970,"question":"كُهان أهل الكتاب وسحرتهم لا يُقتلون؟","title":"هل يُقتل كُهان أهل الكتاب وسَحَرَتهم؟","answer":"الجواب: المشهور عند أهل العلم أنهم لا يقتلون؛ لأنه متعاهد معهم على حالهم وعلى ما هم عليه ببذل الجزية، ويبقى كاهنهم وساحرهم فيهم.\nس: ما يقاس عليه ابن صياد؟\nالشيخ: ابن صياد منهم، من الكهنة.\nس: ابن صياد أسلم؟\nالشيخ: أظهر الإسلام، ولكن الناس ما أمِنوه ولا صدقوه، وحج مع الناس وأتى مكة وأظهر الإسلام، وكان يقول للناس: يا عجبًا لكم، أنا أسلمت وأنا حججت وتتهموني، ولا يزال يتهمونه ولو أسلم يتهمونه بالنفاق، والله المستعان.","link":"https://binbaz.org.sa/fatwas/24198/هل-يقتل-كهان-اهل-الكتاب-وسحرتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقتل كهان أهل الكتاب وسحرتهم.mp3","categories":["السحر والكهانة"]},{"id":4277,"question":"في الاستعانة بالجن يقول بعضهم: جائز إذا كان مما يقدر عليه الجن؟","title":"حكم الاستعانة بالجن فيما يقدر عليه الجن","answer":"الجواب: لا ما يصلح التأول به..؛ لأنه فتح باب شر، فالجن ولو كلموك ممن يصرعون تقول: هذا لا يجوز لكم، هذا حرام عليكم، اخرجوا منه، لا يجوز لكم هذا الفعل.","link":"https://binbaz.org.sa/fatwas/24547/حكم-الاستعانة-بالجن-فيما-يقدر-عليه-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستعانة بالجن إذا كان مما يقدر عليه الجن.mp3","categories":["السحر والكهانة"]},{"id":4283,"question":"هل الساحر إذا تاب؟","title":"هل يُقتل الساحر وإنْ تاب؟","answer":"الجواب: فيما بينه وبين الله يصح توبته، ولكن يُقتل.","link":"https://binbaz.org.sa/fatwas/24554/هل-يقتل-الساحر-وان-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحد على الساحر إذا تاب.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":4285,"question":"من أتى كاهنا أو عرافا نفس الذي يسأل؟","title":"حكم من أتى أو سأل كاهنًا أو عرافًا","answer":"الجواب: فقد كفر بما أنزل على محمد إذا صدقه في علم الغيب، أما إن كان عامي أتاه ما يدري؛ هذا يُعَلّم أن هذا لا يجوز، ولا يلحقه الكفر، أما إذا صدقه بعلم الغيب أنه يعلم الغيب.\nس: الذي يعلم الحكم ويذهب ليسأل عن الضائع؟\nج: ما يجوز، لا يجوز إتيانه؛ لأن الرسول قال لا تأتوهم ولا تسألوهم، نهى عن إتيانهم وعن سؤالهم.\nس: يعني يدخل تحت؟\nج: تحت الوعيد.","link":"https://binbaz.org.sa/fatwas/24556/حكم-من-اتى-او-سال-كاهنا-او-عرافا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من المقصود بحديث من أتى كاهنا أو عرافا.mp3","categories":["شروح الحديث","السحر والكهانة"]},{"id":4327,"question":"السحر هل يصاب به الصالحون الذين يحافظون على الأذكار اليومية والأوراد؟","title":"هل يصاب الصالحون بالسحر؟","answer":"الجواب: السحر قد يصاب به الإنسان، ولكن من اعتصم بحبل الله وتعوّذ بكلمات الله التامات من شر ما خلق وأتى بالتعوذات الشرعية يكفيه الله جل وعلا.\nس: كيف نجمع أنه ﷺ سحر، وهو خير الناس؟\nالشيخ: .. قد يكون سبب صادف شيئًا منه ولم يكن هناك وقاية، قد يكون صادف يومًا أو ساعة لم يتعاطَ فيها النبي أسباب الوقاية عليه الصلاة والسلام.\nس: هذا قبل المعوذات أحسن الله إليك؟\nالشيخ: نعم؟\nالطالب: قبل ما تنزل المعوذات؟\nالشيخ: محتمل، الله أعلم محتمل، الواجب على المؤمن أن يحرص على الوقاية الشرعية ويحرص على ما شرعه الله من التعوذات لعل الله جل وعلا يكفيه الشر.","link":"https://binbaz.org.sa/fatwas/24602/هل-يصاب-الصالحون-بالسحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصاب الصالحون بالسحر.mp3","categories":["السحر والكهانة"]},{"id":4328,"question":"فتوى انتشرت عن بعض أهل العلم رحمة الله عليهم أحياء وأمواتاً عن جواز تلك النشرة عن طريق السحر للضرورة، وقول النبي ﷺ : \"حد الساحر..\" ألا يكفي، وألا يقطع أن يمنع البتة، ولا يذكر القول الثاني لأهل العلم؟","title":"الرد على من أباح النشرة بالسحر للضرورة","answer":"الجواب: على كل حال القول الثاني خطأ، قوله: \"حد الساحر ضربة بالسيف\" مثل ما تقدم موقوف ولكنه في حكم المرفوع، ونص القرآن كفر الساحر وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102].\nس: ترد الفتوى من أصلها؟\nالشيخ: نعم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24603/الرد-على-من-اباح-النشرة-بالسحر-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرد على فتوى جواز النشرة عن طريق السحر للضرورة.mp3","categories":["السحر والكهانة"]},{"id":4330,"question":"حديث: لا يحل السحر إلا الساحر؟","title":"ما صحة مقولة: \"لا يحل السحر إلا الساحر\"؟","answer":"الجواب: هذا قول بعض السلف قول الحسن رحمه الله، لا يحل السحر إلا ساحر قول بعض السلف، والمعنى صحيح أي: لا يحله بغير الرقية الشرعية والتعوذات الشرعية والأدوية الشرعية إلا ساحر بعبادة الشياطين.  أما حله بالرقية الشرعية بالتعوذات بالأدوية المباحة هذا لا بأس به، ومن خير العلاج التعوذات الشرعية \"نعوذ بكلمات الله التامات من شر ما خلق\" صباح ومساء ثلاث مرات، وقل هو الله أحد والمعوذتين ثلاث مرات صباح ومساء وعند النوم، كل هذه من أسباب الوقاية.","link":"https://binbaz.org.sa/fatwas/24605/ما-صحة-مقولة-لا-يحل-السحر-الا-الساحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا يحل السحر إلا الساحر.mp3","categories":["السحر والكهانة"]},{"id":4331,"question":"والذي يستعمل الساحر؟","title":"هل من يستعمل الساحر يكون مثله؟","answer":"الجواب: يكون مثله، يكون كافرًا مثله، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/24606/هل-من-يستعمل-الساحر-يكون-مثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الذي يستعمل الساحر.mp3","categories":["السحر والكهانة"]},{"id":4332,"question":"قول الشافعي رحمه الله: إذا تعلم السحر قلنا له: صف لنا سحرك؛ فإن وصف ما يوجب الكفر مثل اعتقاد أهل بابل من التقرب إلى الكواكب السبعة وأنها تفعل ما يلتمس منها فهو كافر، وإن كان لا يوجب الكفر فإن اعتقد إباحته كفر؟","title":"ما وصف السحر الذي يوصف بالكفر فاعله؟","answer":"الجواب: المقصود: بعض الناس ما يفهم السحر، إذا عرف السحر أنه تعلق على الشياطين ودعاؤهم من دون الله أو دعاء الأصنام أو الأوثان هذا شرك أكبر، بلاء عظيم.  أما إذا كان أدوية يفعلها أو شيء يضر الناس ما يسمى سحرًا، الذي ما يتعلق بعبادة غير الله ما يسمى سحرًا، ولا يؤثر في الناس، وإنما هو أشياء تضر الناس مثل الأمراض ومثل الجراحات. هذا مراده رحمه الله؛ الشيء الذي ما فيه عبادة لغير الله إنما قد يستعمل أشياء قد تضر الناس ولكن ليست سحرًا، تضره في رجله تضره في يده تضره في رأسه، أشياء يستعملها إما كحولًا أو دخونًا أو أشياء تضره ليست من عبادة غير الله، هذا من باب الظلم، من باب العدوان.","link":"https://binbaz.org.sa/fatwas/24607/ما-وصف-السحر-الذي-يوصف-بالكفر-فاعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق على قول الشافعي إذا تعلم السحر قلنا له صف لنا سحرك...mp3","categories":["السحر والكهانة"]},{"id":4334,"question":"قول النبي ﷺ: من أتى عرافا وقوله: من أتى كاهنا يشمل هذا الساحر؟","title":"هل وعيد من أتى كاهنًا يشمل من أتى ساحرًا؟","answer":"الجواب: الساحر قد يدخل في هذا بمعنى أنه يدعي معرفة الأمور الغيبية يدخل في العرافين، أما الكاهن في الغالب المراد بالكاهن اللي يدعي علم المغيبات من طريق مسترق السمع، أما السحرة فشأنهم إما إدخال ضرر على الناس أو جمع بين الرجل والمرأة أو تفريق بينهما من طريق الشياطين، هذا عمل السحرة، أما الكهانة يدعون علم الغيب يخبرون أنه سوف يكون كذا، سوف يسافر فلان، سوف يموت فلان، سوف يهزم آل فلان، سوف يقع مصائب كذا، هذه غالب أخبار الكهنة، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/24609/هل-وعيد-من-اتى-كاهنا-يشمل-من-اتى-ساحرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أتى كاهنا هل يشمل هذا الساحر.mp3","categories":["شروح الحديث","السحر والكهانة"]},{"id":4335,"question":"هل عقوبة الذهاب إلى الساحر هي نفس عقوبة من أتى كاهنًا أو عرافًا؟","title":"ما عقوبة الذهاب إلى الساحر؟","answer":"الجواب: كلهم يجب منعهم من جهة ولاة الأمور، ولا يذهبون إليهم، ولا يصدقونهم، ولو بالتأديب، الجاهل يعلم، والمتعلم يؤدب.\nس: العقاب المترتب في الذهاب إلى الساحر هو نفس العقاب المترتب في الذهاب إلى الكاهن؟\nالجواب: أشد وأشد.","link":"https://binbaz.org.sa/fatwas/24610/ما-عقوبة-الذهاب-الى-الساحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل عقوبة الذهاب إلى الساحر هي عقوبة من أتى كاهنًا أو عرافًا.mp3","categories":["السحر والكهانة"]},{"id":4336,"question":"السحرة يصنعون شيئًا يحبِّب المرأة إلى الرجل، ويحبِّب الرجل إلى المرأة، هل هذا جائز؟","title":"حكم عمل ما يحِّبب المرأة للرجل والعكس","answer":"الجواب: هذا السحر، فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102] وضده ما يحبب الرجل إلى زوجته.  وهذا يسمى التولة: إن الرقى والتمائم والتولة شرك التولة هي السحر.","link":"https://binbaz.org.sa/fatwas/24611/حكم-عمل-ما-يحبب-المراة-للرجل-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عمل شيئ يحبب المرأة إلى الرجل، والعكس.mp3","categories":["السحر والكهانة"]},{"id":4337,"question":"حكم مشاهدة أعمال السحرة؟","title":"ما حكم مشاهدة أعمال السحرة؟","answer":"الجواب: لا يجوز هذا، ينكرها ويبين لهم حكمها، بعضهم يري الناس... مثل دجاج وطيور وحمام وعصافير، يقول  هذه من فمي، من بطني، كله تلبيس على الناس.\nس: حكم حضورها؟\nج: حضورها للإنكار.\nس: للتمتع؟\nج: لا يجوز هذا، لأن هذا منكر إلا على سبيل معرفة الحقيقة حتى يخبر عنها.","link":"https://binbaz.org.sa/fatwas/24612/ما-حكم-مشاهدة-اعمال-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مشاهدة أعمال السحرة.mp3","categories":["السحر والكهانة"]},{"id":4338,"question":"إذا كان الشخص يذهب إلى الساحر وتاب هل عليه..؟","title":"حكم من كان يذهب إلى الساحر وتاب","answer":"الجواب: إذا تاب الحمد لله.\nس: هل عليه أن يخبر ولاة الأمور؟\nج: إذا تاب الحمد لله، عليه أن يخبر عن السحرة.","link":"https://binbaz.org.sa/fatwas/24613/حكم-من-كان-يذهب-الى-الساحر-وتاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كان يذهب إلى الساحر وتاب.mp3","categories":["السحر والكهانة"]},{"id":5205,"question":"هذا سائلٌ يقول: إنه قد جاءني رجلٌ وقال: إنَّ في زوجتك سحرًا، فلا بأس أن تذهب للكاهن، ولكن بدون تصديقه، فما الحكم أثابكم الله؟","title":"حكم الذهاب للكُهّان لفك السحر دون تصديقهم","answer":"الجواب: لا، لا تُصدقه، لا تُصدق السَّحرة، ولا تذهب إلى السَّحرة، اقرأ عليها وانفث عليها بآية الكرسي والفاتحة: الْحَمْدُ لِلَّهِ [الفاتحة:2] وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، وتبرأ إن شاء الله، وهي كذلك تنفث على نفسها وتتعوَّذ بكلمات الله التامَّات من شرِّ ما خلق، وتبرأ إن شاء الله، وتقرأ الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، أنت تقرأ عليها، أو هي تقرأ على نفسها ويزول: قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، تُكرر عليها ثلاث مرات في القراءة، وهي من أسباب الشِّفاء والعافية من كل بلاءٍ، ولا تذهبوا إلى السَّحرة، لا يجوز الذّهاب إلى السحرة، ولا سؤالهم، ولا تصديقهم.","link":"https://binbaz.org.sa/fatwas/30149/حكم-الذهاب-للكهان-لفك-السحر-دون-تصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 181.mp3","categories":["السحر والكهانة"]},{"id":5983,"question":"فيما يتعالق بموضوع السحر يا شيخ والله، يروج عند بعض العوام أن فلانًا ركبه مسيحي، ركبه قيسي، ركبه كذا وكذا ( جني) حتى أن بعضهم يروج هذا، في ريف مصر، ويذهبوا إلى الكنائس، وهذه وسيلة من وسائل تبشير، أو تنصير المسلمين، فما وجه مثل هذا، بخصوص الجن، وما إلى ذلك، يُرَوَّج لدى العوام أن الجن ركبهم، بعضهم يقولون: إن هذا جن مسلم، وبعضهم يقول: جني كافر، ويأخذه إلى الكنيسة، ويقول: تعال يا قسيس عندي كذا وكذا؟","title":"حكم إخراج الكافر الجني من الإنسان المسلم","answer":"الجواب: لا، هذا غلط، إذا دعي أن الجني دخل في الإنسي، سواء كان الجن كافرًا، أو مسلمًا؛ فالقراءة تكون للمسلم، لا للكفرة، المسلم يقرأ عليه، المسلم، يقرأ عليه آيات من القرآن، ويتوعده ويذكره بالله، وأنه حرم عليه ظلم هذا الرجل، أو هذه المرأة، ويتوعده بذلك، ويأخذ بالسلاح، ويقول: إن ما خرجت منه قتلتك، وما هو قاتله، لكن للتخويف؛ لأن بعض الجن خواف، جبان، إذا رأى الجد من القارئ؛ خاف. وكذلك يخوفه بالسكين، يقول: ترى إن ما خرجت؛ قطعت رقبتك، أو يأخذ عصًا، أو حجرًا يتوعده، ويجتهد بكلام قوي، ليس بكلام ضعيف، ويقرأ، وينفث، ويمسح، ويعاهد ألا يعود إليه.","link":"https://binbaz.org.sa/fatwas/1368/حكم-اخراج-الكافر-الجني-من-الانسان-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_326.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":5998,"question":"ما حكم نقل الدم من شخص إلى شخص آخر؟ وإذا قيل بجواز ذلك، فهل يأثم المسحوب منه الدم لو تضرر، أو مات بسبب ذلك؟ وهل يدخل تحت الوعيد فيمن قتل نفسه؟","title":"حكم نقل الدم من شخص إلى آخر","answer":"الجواب:  نقل الدم من شخص إلى آخر محل تفصيل، فإذا دعت إليه الضرورة، ونقله لا يضر في ذلك؛ فلا حرج على الصحيح، لأجل الضرورة، إذا كان المنقول لا يضره بقول الأطباء العارفين إذا قالوا: إن هذا لا يضره لحاجة المضطر لهذا الدم الذي يجانس دمه؛ فلا حرج في هذا -إن شاء الله- على القول المختار. أما إذا كان يضره  فلا، لا يضر نفسه بمصلحة غيره، ولكن إذا قرر الطبيب، والمختص بأن هذا المقدار لا يضر الشخص، وهو يحتاجه؛ فلا حرج في هذا، من باب الإيثار، ومن باب الإحسان.","link":"https://binbaz.org.sa/fatwas/1414/حكم-نقل-الدم-من-شخص-الى-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_359.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6121,"question":"ما هو السحر؟ وهل سحر رسول الله ﷺ؟","title":"حقيقة السحر وحقيقة وقوعه للنبي صلى الله عليه وسلم","answer":"الجواب: السحر أنواع كثيرة، منها: ما يكون بالعقد، والنفث، كما قال -جل وعلا-: وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ [الفلق:4]. ومنها: ما يكون بالأدوية مخصوصة، وأعمال مخصوصة يعقدها، ويفعلها الساحر حتى يتم ما أراد -بإذن الله-  كما قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102].  فطرق السحرة فيما يفعلون من العقد، والشر الذي يريدون إيقاعه للمسحور لهم طرق كثيرة، قد يقع بسحرهم -بإذن الله وقدره- وقد لا يقع، فهو تحت إذن الله، ومشيئته -جل وعلا-. وقد وقع السحر للنبي ﷺ سحره لبيد بن الأعصم من اليهود، سحر النبي ﷺ حتى يخيل إليه أنه فعل الشيء في بيته، وهو لم يفعله، لكنه لم يؤثر على عقله، ولا على بلاغه، ورسالته -عليه الصلاة والسلام- إنما أثر شيئًا يسيرًا فيما يتعلق في بيته، وأهله، ونحو ذلك، هذا هو الصواب، وقد ثبت هذا عن النبي ﷺ في أحاديث صحيحة، وأقره أهل العلم، ومن أنكره من بعض الكتاب؛ فقد غلط، وقع، ولكن الله -جل وعلا- رفعه عنه، وأزاله عنه، وأطلعه على أسبابه حتى قضى عليه.","link":"https://binbaz.org.sa/fatwas/1542/حقيقة-السحر-وحقيقة-وقوعه-للنبي-صلى-الله-عليه-وسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_472.mp3","categories":["السحر والكهانة"]},{"id":6126,"question":"طريقة العلاج على المسحور؟","title":"طريقة العلاج من السحر وحكم الساحر","answer":"الجواب: العلاج له طرق منها: القراءة على المسحور، والنفث عليه، ومنها: قراءة في الماء، يقرأ في الماء آيات السحر الثلاث التي في سورة الأعراف، ويونس، وطه مع آية الكرسي، وقل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، يقرأ فيها، ثم يشربه، ويتوضأ به، ويغتسل بالباقي. ومنها: أن يضع في الماء شيئًا من السدر سبع ورقات، من السدر المعروف .. ويجعل في الماء، ويقرأ فيه ما ذكر هذا مجرب -بإذن الله- لإزالة السحر، ولعلاج من صرف عن زوجته، فلم يطأها، هذا مجرب ... ومنها: الدعاء، دعاء الله، والضراعة إليه، واللجأ إليه في السجود .. يسأل الله أن يرفع عنه ... ومنها: ما عرف من فعله أنه يؤخذ، ويزجر، ويؤدب حتى يزيل ما فعله إذا عرف أنه فلان أخذ، وأجري عليه ما يلزم من التعذيب .. حتى يزيل ما فعله، وهو يستحق القتل إذا عرف بعدما يزيل ما فعل، يستحق أن يقتل. السؤال:.. الجواب: هذا ما يتنافى مع هذا، هذا قالوه لما كان النبي ﷺ في مكة -عليه الصلاة والسلام- والسحر المعروف الذي لا يعقل صاحبه، يتحير، ويذهب عقله، أما هذا السحر العارض فقد فُعِل به ﷺ ولم يؤثر  على عقله، ولا على بلاغه -عليه الصلاة والسلام- فهو شيء عارض، خفيف، أثر فيما بينه، وبين أهله، لم يؤثر على شيء فيما يتعلق بالبلاغ، والبيان، وإصدار الأحكام، فهو شيء مخصوص، مستثنى مما رماه به أعداء الله.","link":"https://binbaz.org.sa/fatwas/1543/طريقة-العلاج-من-السحر-وحكم-الساحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_473.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6289,"question":"بعض المصابين بأمراض نفسية يذهبون إلى الكهان، والمنجمين؟","title":"حكم الذهاب إلى الكهان والمنجمين","answer":"الجواب: لا يجوز هذا، لا يجوز الذهاب إلى المنجمين، ولا الكهان، ولا سؤالهم عن مرض، ولا عن غيره، النبي -عليه الصلاة والسلام- يقول: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا رواه مسلم في صحيحه، ويقول لما سئل عن الكهان قال: ليسوا بشيء، ونهى عن إتيانهم، وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام- وقال: ليس منا من تكهن، أو تكهن له، أو سحر، أو سحر له، أو تطير، أو تطير له فقوله: ليس منا، هذا وعيد، فلا يؤتون، ولا يسألون.  هؤلاء الذين يقولون: اعطنا .. اعطنا اسم أمك، واسم أبوك، هؤلاء كهنة، أو كذابين، والمشعوذين يأكلون أموال الناس بالباطل، إما أنهم خدام للجن، ويكذبون على الناس، وإما أنهم يريدون بهذا التلبيس على الناس حتى يأخذوا أموالهم بغير حق، والدواء، والعلاج يكون عند الأطباء المعروفين، أو عند الناس المعروفين بالخير من العرب الذين يداوون بالكي، بالحمية، بأدوية أخرى معروفة، ولا يتهمون بخدمة الجن، ولا طاعة الجن، ولا سؤال الجن، هذا لا بأس به، والطيب معروف عند الناس.","link":"https://binbaz.org.sa/fatwas/1806/حكم-الذهاب-الى-الكهان-والمنجمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_647.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6569,"question":"مرض رجل، وذهب إلى آخر يسمى سيدًا، وشرط على المريض عدة رؤوس من الغنم، وكمية من الحب، ومبلغًا من الدراهم، وكتب له حرزًا، وكتب له عدة أوراق يمحو البعض منها، ويشربه، والآخر يتبخر عليها، وشرط عليه كل سنة رأسًا من الغنم، أفتونا جزاكم الله خير الجزاء عن هذا؟","title":"حكم التداوي عند من عرف بالكهانة والشعوذة","answer":"الجواب: هذا وأشباهه لا يؤتى، ولا يسأل، هذا من الكهنة، والفجرة الذين يأكلون أموال الناس بالباطل، هذا لا يجوز أن يسأل أبدًا، هذا غلط، من الدلائل على خبثه: اشتراطه رؤوس الغنم، ماذا يفعل برؤوس الغنم؟ يذبحها للجن، أو لمن؟ هذا شر، ثم إعطاؤه حروزًا يعلقها هذا من سنة الجن.. المقصود: أن هذا لا يجوز سؤاله، ونرجو من السائل أن يعطينا خبره حقيقه، وأين يكون هذا الرجل؟ وفي أي مكان؟ وما هو اسمه؟ ولو سرًا بيننا، وبينه، أنت أيها السائل تعطينا خبره؛ لأن هذا ما يجوز إقراراه، هذا عمله سيئ، وهذا يضر المسلمين. السؤال: من أنواع الشرك؟ الجواب: هذا من الكهنة، يدعون الغيب، ومن ادعى الغيب؛ كفر. السؤال: الذين يعالجون بدون أن يشترطوا شيء؟ الجواب: هذا لا يجوز يعلق التمائم .. التمائم شرك. السؤال: بعضهم يعالجون بالطب الشعبي، ولا يشترطون.. ؟ الجواب: لا يجوز شيء، ما يجوز تعليق التمائم أبدًا، ولا يجوز .. على صاحبها، ولا يجوز إقراره؛ لأنها من التمائم، وقد أخبر أنها من الشرك، وقال: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة؛ فلا ودع الله له ومن تعلق شيئًا؛ فقد أشرك وقال: إن الرقى، والتمائم، والتولة شرك. فلا يجوز تعليقها، ولو كانت من القرآن؛ لأنها وسيلة إلى الشر، والرسول ﷺ نهى عن التمائم كلها، ولم يستثن شيئًا، وقال إبراهيم النخعي - رحمه الله-: كان أصحاب ابن مسعود يكرهونها، من القرآن، ومن غير القرآن، يعني يحرمونها. ثم تعليق التمائم التي من القرآن، ومن الدعوات الأخرى وسيلة لفتح باب للشرك؛ لأنه إذا علق هذا علق هذا، واشتبه الأمر.","link":"https://binbaz.org.sa/fatwas/2397/حكم-التداوي-عند-من-عرف-بالكهانة-والشعوذة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_926.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6627,"question":"سؤالي: في شخص يأتي من دولة البحرين اسمه: أبو دجانة، لكن اسمه الحقيقي علي الملا يدعى أنه يعالج المرضى، ولكن يوم ذهبت للدمام؛ لأن والدي وعده يوم الخميس أن يعالج الوالدة، فجاء البيت، وعالج الوالدة، ولكن رأيته أنا، وكدت أضربه، لكن خفت من والدي؛ لأنه شخص يشرب الدخان، وحليق اللحية سألته لماذا تشرب؟ قال: يجب أن أكون هادئًا عندما يأتوني، ويعلموني الأمراض أين هي. فقال ما اسمك -للوالدة-؟ فقالت: كذا وكذا. فكتب أعدادًا عنده، وقال إن كذا وكذا من الأمراض، فأجاب بعضها صحيح، وبعضها غلط، وأعطى الوالدة أشياء من الأوراق لا يعرف فيه إلا اسم الله أول شيء، والباقي لا يعرف، وقال: هذه تضعينها في المخدة، وهذه تتبخرين بها، وهذه تشربينها، ولكن -بفضل الله- أنا خوفت والدتي، فقلت لها: إذا استعملت هذا الدواء فسيدخل عليك شيء من النافذة، ولم تستعمله، وقال لوالدي هذا الكاهن: إن زوجتك سوف تشفى يوم الخميس، وبالفعل سرقت بقالة والدي يوم الخميس، وأخذ منها مبلغًا وقدره ستون ألف ريالًا، ولكن أنا لم أسكت على هذا الموضوع، بل أخبرت وأردنا أن نقبض عليه، ولكنه شرد منا، وإنه يأتي كل يوم خميس إلى الدمام، وهو مشترك مع شخص سعودي في العملية؛ لأنه هو الذي يتصل به، هل أخبر عن السعودي هذا، أم أسكت، وبالعلم ماذا عليه الذي يصدق بهذا الرجل ويستعمل الدواء؟","title":"كيفية التعامل مع السحرة","answer":"الجواب: لا شك أن هذا من العرافين، ومن الكهنة، ومن المفسدين في الأرض، مثل هذا لا يقبل، ولا يستعمل في العلاج، بل هذا يجب القبض عليه، وتأديبه بما يلزم، وسجنه بما يستحق؛ حتى يعاد إلى بلاده -إذا كان من غير هذه البلاد- بعد النظر، وبعد تحكيم الشريعة فيه، على المحكمة أن تنظر في أمره، وتحضر الشهود العارفين به حتى تحكم عليه المحكمة بما يستحق من التأديب، والسجن، وغير ذلك. هذا لا يجوز الذي يقول: اسمك كذا، أو اسم أبيها، أو يعطي كلمات لا يعرف معناها ... وخطوط مقطعة، أو حروف مقطعة، أو أشباهه من الشيطان التي لا تعرف، هذا كله من الدلائل على أنه من الكهنة، ومن المنجمين، ومن العرافين، أو من الكذابين اللعابين الذي يشوش على الناس. وقوله: إن مرضها يزول يوم الخميس هذا يدل على جهله، وضلاله، فإن زوال المرض لا يعلم متى يزول إلا الله .  الحاصل: أن مثل هؤلاء كذبة، فجرة، لا يجوز إقرارهم، بل هم من جملة العرافين، الكذابين، المدعين للطب، وهم يكذبون، ويأخذون أشياء من الجن، والشياطين، ويستعينون بها على بعض باطلهم ليأخذوا أموال الناس بالباطل.  وأنت أيها الكاتب لا بد تكتب لنا على اسم السعودي -ولا نبين اسمك إن شاء الله- تكتب اسم السعودي، ولا تبين اسمك ما يخالف إذا كانت خائفًا.","link":"https://binbaz.org.sa/fatwas/2493/كيفية-التعامل-مع-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1020.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":6642,"question":"سؤالي: في شخص يأتي من دولة البحرين اسمه: أبو دجانة، لكن اسمه الحقيقي علي الملا يدعى أنه يعالج المرضى، ولكن يوم ذهبت للدمام؛ لأن والدي وعده يوم الخميس أن يعالج الوالدة، فجاء البيت، وعالج الوالدة، ولكن رأيته أنا، وكدت أضربه، لكن خفت من والدي؛ لأنه شخص يشرب الدخان، وحليق اللحية سألته لماذا تشرب؟ قال: يجب أن أكون هادئًا عندما يأتوني، ويعلموني الأمراض أين هي. فقال ما اسمك -للوالدة-؟ فقالت: كذا وكذا. فكتب أعدادًا عنده، وقال إن كذا وكذا من الأمراض، فأجاب بعضها صحيح، وبعضها غلط، وأعطى الوالدة أشياء من الأوراق لا يعرف فيه إلا اسم الله أول شيء، والباقي لا يعرف، وقال: هذه تضعينها في المخدة، وهذه تتبخرين بها، وهذه تشربينها، ولكن -بفضل الله- أنا خوفت والدتي، فقلت لها: إذا استعملت هذا الدواء فسيدخل عليك شيء من النافذة، ولم تستعمله، وقال لوالدي هذا الكاهن: إن زوجتك سوف تشفى يوم الخميس، وبالفعل سرقت بقالة والدي يوم الخميس، وأخذ منها مبلغًا وقدره ستون ألف ريالًا، ولكن أنا لم أسكت على هذا الموضوع، بل أخبرت وأردنا أن نقبض عليه، ولكنه شرد منا، وإنه يأتي كل يوم خميس إلى الدمام، وهو مشترك مع شخص سعودي في العملية؛ لأنه هو الذي يتصل به، هل أخبر عن السعودي هذا، أم أسكت، وبالعلم ماذا عليه الذي يصدق بهذا الرجل ويستعمل الدواء؟","title":"كيفية التعامل مع السحرة","answer":"الجواب: لا شك أن هذا من العرافين، ومن الكهنة، ومن المفسدين في الأرض، مثل هذا لا يقبل، ولا يستعمل في العلاج، بل هذا يجب القبض عليه، وتأديبه بما يلزم، وسجنه بما يستحق؛ حتى يعاد إلى بلاده -إذا كان من غير هذه البلاد- بعد النظر، وبعد تحكيم الشريعة فيه، على المحكمة أن تنظر في أمره، وتحضر الشهود العارفين به حتى تحكم عليه المحكمة بما يستحق من التأديب، والسجن، وغير ذلك. هذا لا يجوز الذي يقول: اسمك كذا، أو اسم أبيها، أو يعطي كلمات لا يعرف معناها ... وخطوط مقطعة، أو حروف مقطعة، أو أشباهه من الشيطان التي لا تعرف، هذا كله من الدلائل على أنه من الكهنة، ومن المنجمين، ومن العرافين، أو من الكذابين اللعابين الذي يشوش على الناس. وقوله: إن مرضها يزول يوم الخميس هذا يدل على جهله، وضلاله، فإن زوال المرض لا يعلم متى يزول إلا الله .  الحاصل: أن مثل هؤلاء كذبة، فجرة، لا يجوز إقرارهم، بل هم من جملة العرافين، الكذابين، المدعين للطب، وهم يكذبون، ويأخذون أشياء من الجن، والشياطين، ويستعينون بها على بعض باطلهم ليأخذوا أموال الناس بالباطل.  وأنت أيها الكاتب لا بد تكتب لنا على اسم السعودي -ولا نبين اسمك إن شاء الله- تكتب اسم السعودي، ولا تبين اسمك ما يخالف إذا كانت خائفًا.","link":"https://binbaz.org.sa/fatwas/2493/كيفية-التعامل-مع-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1020.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":6654,"question":"إن بعض الناس الذين ابتلاهم الله بالجن يذهبون إلى الكهان، مع العلم أن هؤلاء الكهنة يقومون بمنع الجن عن هؤلاء الناس، سواء بالقتل، أو بالمنع، فما رأيكم بهذا؟","title":"استخدام الكهنة للشياطين","answer":"الجواب: هذا كله لا يجوز، لأن الكهنة يستخدمون الشياطين، حتى في عهد الجاهلية الكاهن له صاحب من الجن يسمى كاهنًا، له رئيًا من الجن، صاحب يأتيه يخبره، جرى في الإحساء كذا، جرى في المدينة كذا، جرى في الشام كذا، جرى في مصر كذا، الشياطين فيما بينهم يتناقلون الأخبار: قتل فلان، مات فلان، حدث انقلاب في المحل الفلاني، حدث كذا، هكذا تتناقل الشياطين، فيظن الجاهل أن هذا الكاهن، أو هذا الرمال يعلم الغيب، وإنما هي الشياطين تذكر له بعض الأخبار، فيتظاهر للناس أنه عنده معلومات، وأن عنده معلومات عن الغيب، وأنه يطلع على كذا، وأنه يطلع على كذا.  وقد يكون يستخدم بعض الشياطين الآخرين الذين لهم قوة، ولهم سلطان من ملوك الشياطين، ورؤسائهم، فيأتون بهذا الشيطان الذي تلبس بالمجنونة، او بالمجنون، أو فعل فيه شيء من الأمور التي يتعاطاها الشياطين، فيقولون له إذا أرضاهم هذا الإنسي، إذا أرضاهم بعبادتهم من دون الله، أو ذبح لهم، أو نذر لهم، أو عبدهم بالسجود، أو بغيره، إذا أرضاهم قد يحضرون الشيطان الذي تحت إمرتهم، فيقولون: إما أن تفعل كذا، وإلا قتلناك، وإلا سجناك، وإلا فعلنا بك، فيدع عمله القبيح من أجل طاعة ساداته من الشياطين، والرؤساء.  فيحذر النفع للإنسان بهذه الطرق الخبيثة الشركية الظاهرة، هذا ليس بعذر، ولا يجوز إتيان هؤلاء أبدًا، ولو قدر أنه انتفع به بعض الناس، فيكون النفع لبعض الناس من طريق الشرك ليس بعذر، فعباد الجن قد ينتفعون بالجن، ولكن ضررهم أعظم، فقد يأتي لهم الجني بأشياء، قد يأتي لهم بدراهم، قد يأتي لهم بطيب يسرقه، قد يأتي لهم بغنم يسرقها، قد يأتي لهم بأشياء، فهذا مقتدر في عبادة الجن، واتخاذهم آلهة مع الله، نسأل الله العافية. حتى أهل الجاهلية كانت تسلمهم الأصنام، يأتي الشياطين إلى جوف الأصنام، ويكلمون هؤلاء العبدة من دون الله، ويكلفونهم بأشياء، ويخاطبونهم بأشياء، ويقولون جرى كذا وكذا، وربما خاطبوهم بلغة لا يعرفونها، فيغرونهم بالشرك، ويدعونهم إلى الشرك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2526/استخدام-الكهنة-للشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1021.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6671,"question":"من المعلوم أن السحر لا يبطله إلا ساحر، فهل هذا صحيح؟","title":"حكم فك السحر بمثله","answer":"الجواب: ليس بصحيح، السحر قد ينقضه الساحر، وقد يزول بغير الساحر، الساحر قد ينقضه بسحر مثله، يخدم الشياطين، ويتعاطى ما يرضي الشياطين؛ فيزول السحر الذي أوقعوه بالمسحور؛ لأنهم يحبون أن يتصل بهم الناس؛ حتى يعبدوهم من دون الله. فالشياطين قد تفعل شيئًا بالإنسان حتى يتعاطى ما يرضيهم من الشرك بالله، والتقرب إليه بما حرم الله من العبادات، وغيرها؛ حتى يرفعوا سحرهم، وما .. هذا من عمل السحرة، ولا يجوز إتيانهم، ولا سؤالهم، النبي ﷺ قال: من أتى عرافًا، أو كاهنا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام.  وقال: ليس منا من تطير، أو تطير له، وليس منا من سحر، أو سحر له، وليس منا من تكهن، أو تكهن له، ومن أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام- وقال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة.  فلا يجوز للمؤمن أن يأتي السحرة، ولا الكهنة، ولا العرافين المعروفين بدعوى علم الغيب، ولا المنجمين، كل هؤلاء يحرم إتيانهم، ويحرم سؤالهم، ويحرم تصديقهم.  ولكن هناك علاج ثانٍ لهذه الوسائل بغير السحر، بالقراءة على المسحور، فإن هذا قد ينفعه الله به، ويزول السحر، هناك أدوية أخرى يتعاطاها المسحور لإزالة ما أصابه، منها: أوراق السدر المعروف -النبق المعروف- كان العلماء فيما سبق -علماء هذه الأمة- يأخذون سبع ورقات من السدر، تدق، ثم يقرأ فيها آية الكرسي، وآيات السحر التي نزلت في القرآن الكريم في سورة الأعراف، وسورة طه، وسورة يونس، ويقرأ: قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، مع ما يسر الله من الدعاء اللهم رب الناس، أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقمًا ثم يشرب منها المسحور، ويغتسل بها، ويزول -بإذن الله- السحر، قد يكون يزول بأول مرة، وقد يكون يزول بثاني مرة، وقد يكون يزول بثالث مرة، وهذا مجرب كثيرًا، ونافع، قد نفع الله به كثيرًا.","link":"https://binbaz.org.sa/fatwas/2563/حكم-فك-السحر-بمثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1058.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6690,"question":"في مريض مرضًا مزمنًا، وذهب إلى الأطباء في كل أنحاء المملكة ما جعل الله له سببًا وشفاء بسببهم، فأخذه أخوه، وذهب به إلى الشمال، إلى واحد عنده كلاب، يقولون: إنه كاهن، ونصحته، قال: إن الضرورة تبيح المحرمات؟","title":"حرمة إتيان الساحر للتداوي","answer":"الجواب: لا ما يجوز، هذا غلط، هذا أفتى نفسه فقط. السؤال: وأخذ منه خمسة آلاف ريالًا، هذا الكاهن أخذ منه خمسة آلاف ريالًا، وقال: إن امرأتك سحرتك في خبز، والمرأة هذه بارة به، حتى بعد عرفت ما يمكن أن تسحره، وهي عجوز، وهو فوق الخمسين عامًا. الجواب: وهذه من العقوبات، المقصود أن هذا ما يجوز. السؤال: والآن اختل عقله، ولا يصلي الآن، ما عاد يشعر، ولا عاد يصلي؟ الجواب: يقال له: ما يجوز هذا، إتيان السحرة، والكهنة ما يجوز إتيانهم، ولا يحل، هذا ولو كان مريضًا بعض الأمراض ما لها شفاء، بعض الأمراض قد كتب الله أنه يموت بأسبابها، ما لها علاج، قد يعالجه مائة طبيب، ولا ينفع، إذا كان الله أراد أنه يموت بهذا المرض ما فيه شيء، إنما الإنسان يأخذ بالأسباب، فإن شفاه الله، وإلا فالأمر بيد الله، ما كل مرض له دواء، بعض الأمراض ما لها دواء، قد كتب الله أنه يموت بها. السؤال: والضرورات تبيح المحرمات في ماذا؟ الجواب: إذا جاع ولا عنده شيء يأكله، جاز أن يأكل من الميتة مثلًا، وأشباه ذلك؛ حتى لا يموت، ما هو معناه: أنه إذا ما تزوج يروح يزني ... يشرب الخمر لا، هذا غلط، ما كل الضرورات تبيح المحرمات، ولا كل شيء يسمى ضرورة، الضرورة التي تفضي به إلى الموت، تأخذ من الميتة، أو من أي طعام وجدته حتى تبقي نفسك، وحياتك من هذا الجوع الشديد الذي أصابك: إما بالثمن، وإما بالمعروف. السؤال:... الجواب: ... ولو أن شيئًا سبق القضاء لسبقته العين، ما تسبق القدر، القدر من ورائها، لا يقع شيء إلا بقدر.","link":"https://binbaz.org.sa/fatwas/2567/حرمة-اتيان-الساحر-للتداوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1062.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6797,"question":"لقد اطلعت على كتاب الحديث السنة الثالثة المتوسط في حديث رقم 31 بعنوان: الشيطان يخالف بين المسلمين؛ فاحذروه،  بأن في معاني المفردات كلمة الشيطان معناها: أنه كان من الملائكة، فعاقبه الله بسبب عصيانه، وامتناعه عن السجود لآدم، فهو عدو للبشر، إلى آخره، فهل هو فعلًا كان من الملائكة؟","title":"الخلاف في كون إبليس من الملائكة أم لا","answer":"الجواب: هذا فيه خلاف بين العلماء معروف، بعضهم قال: إنه من الملائكة، ثم طرد، ولعن، وبعض أهل العلم قال: إنه من الجن، وأن الطائفة التي كان منها هم الجن، ولهذا قال -جل وعلا-: إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ [الكهف:50] فبين سبحانه أنه كان من الجن، والجن هم المعروفون، هم الثقل الثاني.  قال بعض أهل العلم: وهو أبوهم، كما أن آدم هو أبو الإنس، فهو أبو الجن، وفيهم الشياطين، وهم المردة، ولكن قال بعض أهل العلم: إن الجن طائفة من الملائكة يقال لهم: الجن؛ لأنهم استجنوا، اختفوا، فقيل لهم: الجن، وهم من الملائكة، وهذان القولان مشهوران، ولكن جماعة من المحققين يرجحون أن الجن غير الملائكة، وأنه كان مع الملائكة يصلي معهم، ويتعبد معهم، فعمه الأمر، فلما أبى، وفسق، وتكبر؛ لعن وطرد -نعوذ بالله- وصار من ذريته الشياطين، والجن منهم المؤمن، ومنهم الفاسق، ومنهم الكافر، كما قال تعالى: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ [الجن:11].  س: يا شيخ هم من الجن، أو من الملائكة؟ ج: القول المشهور عن العلماء مشهور أنه من الملائكة، وأنه طرد لما استكبر، وأن الجن طائفة من الملائكة، يقال لهم: الجن. وقال آخرون: لا، الجن هم الثقل الثاني المعروفون الذين قال الله فيهم: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وأنهم ليسوا من الملائكة، وأن الملائكة خلقوا من النور، والجن خلقوا من النار، كما قال تعالى: وَالْجَانَّ خَلَقْنَاهُ مِنْ قَبْلُ مِنْ نَارِ السَّمُومِ [الحجر:27] قَالَ أَنَا خَيْرٌ مِنْهُ خَلَقْتَنِي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ طِينٍ [الأعراف:12] فهو ليس من الملائكة في العنصر، عنصر الملائكة من النور، وعنصره من النار، فليس منهم في العنصر، ولا في الحقيقة، ولكنه كان معهم، فلما أمر بالسجود؛ لم يسجد، وتكبر، وعصى، فطرده الله، وأبعده، ولعنه. ولهذا اختار هذا شيخ الإسلام ابن تيمية، وجماعة، وقالوا: إنه من الجن، وهو أبوهم، خلقه الله من مارج من نار، وليس من الملائكة، ولكنه كان معهم في السماء، كان يتعبد، فلما استكبر؛ طرد ولعن -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/2674/الخلاف-في-كون-ابليس-من-الملاىكة-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1171.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6948,"question":"يوجد بعض الناس يذهبون خارج البلاد للعلاج عند الكهان، فيقولون لهم: أنت فيك سحر، والذي سحرك فلان، ويعلمونه باسمه، وهو ما عرفه، هل يجب العلاج عندهم، ويدعون أنهم مباح لهم هذا العمل؟","title":"حكم الذهاب إلى الكهان والعرافين والسحرة","answer":"الجواب: العلاج عند السحرة، والكهنة منكر لا يجوز، لا يجوز سؤالهم، ولا إتيانهم، ولا تصديقهم، يقول النبي ﷺ: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا أخرجه مسلم في الصحيح. ويقول ﷺ: من أتى كاهنًا، أو عرافًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام-. فالعرافون هم الذين يدعون علم الكهانة، وعلم السحر، وعلم كل ما كان، ويقولون: ما اسم أمك، واسم أبيك، وهذا سحرك فلان، وقال لك فلان كذا، في يوم كذا، وفي يوم كذا، هكذا أفعالهم.  هؤلاء لا يأتون، ولا يجوز سؤالهم، بل ينبغي فضحهم، من عرفهم يرفع بأمرهم إلى الأمراء الطيبين، إلى المحكمة، وإلى وزارة الداخلية، أو إليّ، وأنا أقوم باللازم -إن شاء الله- إن عرفهم في أي مكان، ولا يجوز له السكوت عنهم، والتغطية عنهم، بل يبينهم في جيزان، في أبها، في الشمال، في المغرب، في أي مكان، هذا من باب التعاون على البر والتقوى. يرفع بأمره إلى المحكمة، إلى المحاكم، إلى الأمراء الطيبين، إلى الملك، إلى وزير الداخلية، إليّ، إلى رئيس الهيئات، من باب التعاون على البر والتقوى، ويبين مكانهم، يقول: في المكان الفلاني اسمه فلان ابن فلان؛ حتى يسعى في إزالتهم، والقضاء عليهم، الله يكفينا شرهم.","link":"https://binbaz.org.sa/fatwas/2878/حكم-الذهاب-الى-الكهان-والعرافين-والسحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1326.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7045,"question":"ذكر السحر في المرتبة الثانية بعد الشرك بالله قبل القتل، مع عظم القتل، وهل هذا دليل على أن القتل أشنع، وقد قيل: إن القتيل يأتي يوم القيامة تقطر أوداجه دمًا؟","title":"عظم جرم السحر وأنه أعظم من القتل","answer":"الجواب:\n\nليس القتل بأشنع من الكفر، الكفر أعظم من القتل، لو كفر وقتل؛ لكان قتله أسهل من الشرك، الكافر له النار مخلدًا فيها أبد الآباد.\n\nوالقاتل قد يعفو الله عنه، ويخرج من النار، ويدخل الجنة إذا كان ما استحله، ولكن قتل بسبب الغضب، والنزاع، والأحقاد، أو الشحناء، أو ما أشبه ذلك، وأنه يعرف أن القتل حرام، ولكنه حمله الشيطان على أن قتل أخاه بسبب شحناء وعداوات بينهما، أو مخاصمات، أو مضاربة، أو ما أشبه ذلك، فهذا أتى جريمة عظيمة، ولكنها دون الكفر، هو موعود بالنار، وقد يعفو الله عنه؛ فلا يدخل النار، وإذا دخلها لا يخلد فيها إذا كان موحدًا لا يخلد، بل له نهاية خلود مؤقت، كما جاء في الآية الكريمة، ولكنه خلود مؤقت، خلود له نهاية؛ لأن الخلود خلودان في النار، الخلود خلودان: \n\nخلود لا نهاية له، وهذا خلود الكفار -نعوذ بالله- هذه حال الكفار، ليس لخلودهم فيها نهاية، بل أبد الآباد.\n\nوهناك خلود مؤقت، له نهاية، وهو خلود بعض العصاة، كما قال : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] هذا الخلود غير مستمر، بل له نهاية، وهكذا قاتل نفسه، وهكذا الزاني موعود بالنار والخلود فيها، لكنه خلود له نهاية، ليس مثل خلود الكفار.\n\nفالحاصل: أن القتل دون السحر؛ لأن السحر كفر، ولا يتعاطاه الساحر إلا بعد كفره، وبعد عبادته للشياطين، ولهذا قرن بالشرك، وقال الله في حق السحرة: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102].","link":"https://binbaz.org.sa/fatwas/3058/عظم-جرم-السحر-وانه-اعظم-من-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1448.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7052,"question":"ما هي الطريقة الشرعية للوقاية من السحر؟","title":"الطرق الشرعية للوقاية من السحر","answer":"الجواب:\n\nمثل ما سمعتم في الندوة أن يسأل الله -جل وعلا- العافية، ويتعوذ بكلمات الله التامات من شر ما خلق، يقول النبي ﷺ: من قال: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات لم يضره شيء.\n\nوكذلك إذا نزل بيتا فقال: أعوذ بكلمات الله التامات من شر ما خلق، لم يضره شيء حتى يرتحل من منزله ذلك ويكرر في الصباح والمساء أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات.\n\nكذلك يقرأ آية الكرسي بعد كل صلاة وعند النوم من أسباب السلامة  وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين بعد كل صلاة من أسباب السلامة، وبعد الفريضة والمغرب ثلاث مرات وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين هذه من أسباب السلامة.\n\nوذكر الله -جل وعلا- والإكثار من قراءة كتابه العظيم وسؤاله  أن يكفيك شر كل ذي شر من أسباب السلامة أعوذ بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة، كذلك أعوذ بكلمات الله التامات التي لا يجاوزها بر ولا فاجر، من شر ما خلق وذرأ وبرأ، ومن شر ما ينزل من السماء ومن شر ما يعرج فيها، ومن شر ما ذرأ في الأرض ومن شر ما يخرج منها، ومن شر طوارق الليل والنهار، ومن شر كل طارق إلا طارق يطرق بخير يا رحمن وهذه من التعوذات التي يقي الله بها العبد الشر.","link":"https://binbaz.org.sa/fatwas/3059/الطرق-الشرعية-للوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1449.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7056,"question":"مرض أخ لي فترة من الزمن، فترة طويلة جدًا، وذهبت به إلى كثير من المستشفيات، ولكن لم يستفد من كل ذلك، وبعد ذلك قالوا: إن عنده بعض سحر، فذهبت به إلى شخص يدعي أنه يعالج مرض السحر، وعالجه بطرق غريبة حسب طرقهم الخاصة والمعروفة للجميع، وقد شفي بإذن الله، وسؤالي هل أنا آثم في ذلك؟","title":"حكم إتيان السحرة والمشعوذين لعلاج السحر","answer":"الجواب:\n\nنعم إذا كان معروفًا أنه يتعاطى السحر، أو علم الغيب أنت آثم، فعليك التوبة إلى الله، والرجوع إليه، وعدم العودة، وإن كان يتعاطى القراءة، والآيات المباحة، لا بالسحر، ولا بخدمة الشياطين، ولا بادعاء علم الغيب؛ فلا بأس. \n\nأما من يعرف بأنه يدعي علم الغيب، ويقول: أصابك فلان، وحصل عليك كذا وكذا، في يوم كذا، وأنت أعطيت كذا يوم كذا، هذا كله دليل على أنه يخدم الشياطين، أو يكذب، يدعي علم الغيب، ويكذب، أو يخدم الشياطين، هذا لا يؤتى، ولا يسأل.\n\nيقول النبي ﷺ: من أتى عرافًا، فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، رواه أهل السنن بإسناد جيد. \n\nوقال أيضًا -عليه الصلاة والسلام-: ليس منّا من سحر، أو سحر له، وليس منّا من تطير، أو تطير له، وليس منّا من تكهن، أو تكهن له فلا يجوز للمسلم أن يسأل هؤلاء، قد يشفى المرض بأسباب كثيرة، وقد لا يشفى، فليس كل مريض يشفى، وليس كل مرض له دواء يشفى منه، قد يعالج له دواء، لكن ما قدر الله له الشفاء؛ لأن الحكمة المدة قد تمت، والأجل قد حضر، فالأدوية مشروطة بعدم وجود الأجل، أما إذا جاء الأجل ما تنفع الأدوية.","link":"https://binbaz.org.sa/fatwas/3062/حكم-اتيان-السحرة-والمشعوذين-لعلاج-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1451.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7064,"question":"ما رأي سماحتكم في رجل استعمل الرقية، ولم ير أنها تنفعه، فيؤول إلى السحر، ويقول: إنه لا يضر ذلك ما دام أنه لا يسبب شيئًا من المشاكل؟","title":"حكم إتيان السحرة لمعالجة المرضى","answer":"الجواب:\n\nمثل ما تقدم، مثل ما سمعت، السحر منكر وكفر، وإذا كان ما ينفعك في القراءة فقد الطب بعد ما ينفع، حتى الطب نفسه الذي هو معروف عند الأطباء، ما كل علاج ينفع، ويحصل به المقصود، قد يؤجل الله الشفاء إلى مدة طويلة، وقد يموت الإنسان بهذا المرض، ليس من شرط العلاج أن يشفى الإنسان. \n\nفليس له عذر إذا عالج عند إنسان بالقراءة، يقول: أروح للسحرة، لا، يعالج عند ثان مثل ما عالج عند طبيب ثاني، يقرأ في يديه عند النوم قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات كما كان النبي يفعل -عليه الصلاة والسلام- كان إذا مسه مرض؛ قرأ في يديه قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، ثم يمسح بهما ما أقبل من جسده، وجهه وصدغيه وصدره، هكذا أخبرت عائشة -رضي الله عنها- أنه كان يفعل هذا -عليه الصلاة والسلام- فلما مرض، وعجز عن ذلك؛ صارت تقرأ في يديه هي، وتمسح بهما على وجهه وصدره -عليه الصلاة والسلام-.\n\nفالمقصود: أن هذا علاج ،يقرأ في يديه، أو يطلب من بعض إخوانه أن يقرؤون عليه؛ لا بأس، وإذا قرأ هو يكون أنفع، يقرأ في يديه الفاتحة وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، آية الكرسي، يقرأ ويمسح ولو ألف مرة، ولو آلاف، الحمد لله لا ييأس، يقرأ ويسأل ربه الشفاء والعافية.\n\nالسؤال: سبق أن أخبرت بشأن الساحر الموجود في منطقة القنفذة ببلدة الحبيل، وإلى ذلك هذا الرجل يعمل عمله الخبيث، وبعدما طلع من السجن الآن يتحدى ويقول: الكتب التي أخذت مني أحفظها عن ظهر قلب، أو عن غيب، وهو رجل كبير السن، يبلغ من العمر ثمانين عامًا، وقد سبق من سماحة الشيخ ابن باز بقوله: بأنه أقدم حتى يحصل العثور عليه، ومتى وهذا الرجل لم ينته، بل يتحدى كل شيء الآن، نحن والله مغلوبون منه، نرجو من الله، ثم من سماحتكم المساعدة؟\n\nالجواب: الذي يعرفه يجينا البيت؛ حتى يسميه باسمه، الذي يعرفه، تعرفه يا شيخ محمد؟\n\nالطالب: نعم الحبيل معروف. \n\nالجواب: تعرف الرجل؟\n\nالطالب: الرجل ما أعرفه.\n\nالجواب: الذي كتب هذا إذا كان يعرفه يجينا، يسميه حتى نكتب للقاضي.\n\nالطالب: .. الرجل معروف زيد بن عبده ... معروف محله ومعروف..\n\nالجواب: لعل الشيخ أحمد يذكرنا يوم السبت، إن شاء الله، بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/3056/حكم-اتيان-السحرة-لمعالجة-المرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1447.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7070,"question":"ذكر السحر في المرتبة الثانية بعد الشرك بالله قبل القتل، مع عظم القتل، وهل هذا دليل على أن القتل أشنع، وقد قيل: إن القتيل يأتي يوم القيامة تقطر أوداجه دمًا؟","title":"عظم جرم السحر وأنه أعظم من القتل","answer":"الجواب:\n\nليس القتل بأشنع من الكفر، الكفر أعظم من القتل، لو كفر وقتل؛ لكان قتله أسهل من الشرك، الكافر له النار مخلدًا فيها أبد الآباد.\n\nوالقاتل قد يعفو الله عنه، ويخرج من النار، ويدخل الجنة إذا كان ما استحله، ولكن قتل بسبب الغضب، والنزاع، والأحقاد، أو الشحناء، أو ما أشبه ذلك، وأنه يعرف أن القتل حرام، ولكنه حمله الشيطان على أن قتل أخاه بسبب شحناء وعداوات بينهما، أو مخاصمات، أو مضاربة، أو ما أشبه ذلك، فهذا أتى جريمة عظيمة، ولكنها دون الكفر، هو موعود بالنار، وقد يعفو الله عنه؛ فلا يدخل النار، وإذا دخلها لا يخلد فيها إذا كان موحدًا لا يخلد، بل له نهاية خلود مؤقت، كما جاء في الآية الكريمة، ولكنه خلود مؤقت، خلود له نهاية؛ لأن الخلود خلودان في النار، الخلود خلودان: \n\nخلود لا نهاية له، وهذا خلود الكفار -نعوذ بالله- هذه حال الكفار، ليس لخلودهم فيها نهاية، بل أبد الآباد.\n\nوهناك خلود مؤقت، له نهاية، وهو خلود بعض العصاة، كما قال : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] هذا الخلود غير مستمر، بل له نهاية، وهكذا قاتل نفسه، وهكذا الزاني موعود بالنار والخلود فيها، لكنه خلود له نهاية، ليس مثل خلود الكفار.\n\nفالحاصل: أن القتل دون السحر؛ لأن السحر كفر، ولا يتعاطاه الساحر إلا بعد كفره، وبعد عبادته للشياطين، ولهذا قرن بالشرك، وقال الله في حق السحرة: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102].","link":"https://binbaz.org.sa/fatwas/3058/عظم-جرم-السحر-وانه-اعظم-من-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1448.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7125,"question":"أخبرك يا سماحة الشيخ أنني أحبك في الله، أطال الله في عمرك على طاعته، أخبرك أنني اطلعت على كتاب روائع البيان، للشيخ ابن الشيخ محمد بن علي الصابوني جزء واحد، وعند تفسيره لقوله تعالى: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ [البقرة:102] إلى آخر الآيات قال: إن السحر نوعان:فمن تعلمه ليتوقى به ضرر، أو يدفع أذاه عن الناس؛ فقد نجا، وثبت على الإيمان، ومن تعلمه معتقدًا صحته؛ ليلحق الأذى بالناس؛ فقد ضل وكفر، فكان الناس فريقين، فريق تعلمه عن نية صالحة؛ ليدفع ضرره عن الناس، ويطلب من سماحتكم بيان ذلك حتى لا يعني؟","title":"تعلم السحر وتعليمه للناس منكر لا يجوز","answer":"الجواب:\n\nوالجواب: أن حبك لي في الله، فأقول: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم جميعًا من المتحابين في الله  فقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي نسأل الله أن يجعلنا وإياكم منهم. \n\nوأما هذا الكتاب \"روائع البيان\" للصابوني ما اطلعت عليه، ولكن إذا كان أجاز فيه تعلم السحر؛ فقد أخطأ وغلط، لا يجوز تعلم السحر، ولو حسن قصد المتعلم؛ لأن تعلم السحر لا يكون إلا بالكفر بالله -نعوذ بالله- لا يكون إلا بعبادة الشياطين، والتقرب إلى الشياطين، وحتى يعلموه ما غمض من علم الغيب بزعمهم.\n\nفالمقصود: أن تعلم السحر، وتعليمه للناس منكر، لا يجوز عند أهل العلم، سواء قاله الصابوني، أو غير الصابوني، هذا لا يجوز أبدًا، بل هو منكر، وقد غلط، وأفحش إن كان قال هذا الكلام.\n\nالسؤال: ما رأيك بالكتاب يا شيخ؟\n\nالجواب: ما اطلعت عليه، لكن إذا كان فيه هذا، فهذا غلط منكر.","link":"https://binbaz.org.sa/fatwas/3148/تعلم-السحر-وتعليمه-للناس-منكر-لا-يجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1506.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7178,"question":"بعض أئمة المساجد والشيوخ يقرؤون على الناس بآيات من القرآن والدعاء، فيعلموهم ماذا أصابهم، فبعضهم يقول له: أصابك سحر، وبعضهم يقول: أصابتك عين، إلى غير ذلك من الكلام الذي يقولون، فما حكمكم في هؤلاء، وحكم الذهاب إليهم، وحكم التصديق بهم؟ وهل ما يقولون صحيحًا؟","title":"معرفة السحر والعين من خلال الخبرة","answer":"الجواب:\n\nإذا كان طالب العلم الذي يرقي الناس قد اعتاد علامات يعرفها مما يصيب المسحور، أو علامات يعرف بها العين؛ فلا بأس بذلك، يقرأ عليه ما يسر الله من كتاب الله، كالفاتحة، وآية الكرسي، وقل هو الله أحد، والمعوذتين، أو غيرها من الآيات، الله جعل القرآن شفاء من العين، ومن السحر أيضًا، حتى قال ﷺ: لا رقية إلا من عين أو حمة. \n\nقال العلماء: معنى لا رقية أولى وأشفى، أو لا أولى وأنفع إلا من عين أو حمة، والعين هي النظرة يسمونها النظرة، هي النفس، والحمة السم من ذوات السموم، وقال -عليه الصلاة والسلام-: لا بأس بالرقى ما لم تكن شركًا وقد رَقى ورُقي -عليه الصلاة والسلام- وأمر أن يرقى أولاد جعفر وقال: إنها أصابتهم العين قال لأمهم: إنها أصابتهم العين فأمرها أن تسترقي لهم، فالرقية نافعة من العين. \n\nفإذا كان طالب العلم المعروف بالعقيدة الصالحة أنه جرب هذه الأمور، ورأى أن ما في فلان أنه مما يعرف أنه عين، أو أنه سحر، مسحور، فيتعاطى بعلاج السحر، أو علاج العين، النبي  قال: العين حق، ولو أن شيئًا سبق القضاء؛ لسبقته العين وقال: استغسلوا فإذا عرف العائن يستغسل، يطلب منه أن يغسل وجهه، ويتمضمض، ويغسل داخلة إزاره، وأطراف يديه ورجليه، حتى يصب على المعين، وهو يشفى بإذن الله، أو يرفع بما يسر الله من القرآن، من الفاتحة، وآية الكرسي، وغير ذلك، والغالب أنه ينفعه ذلك بإذن الله.\n\nوهكذا المسحور يرقى بالفاتحة، وآية الكرسي، وآية السحر التي في سورة الأعراف، ويونس، وطه تقرأ في ماء له مع القواقل -قل يا أيها الكافرون، قل هو الله أحد، والمعوذتين- ويشرب منه بعض الشيء، ويغتسل بالباقي، فينفع الله بذلك كثيرًا ممن يصاب بالسحر.\n\nوالسحر واقع يقع كثيرًا، كما قال الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ [البقرة:102]. \n\nفالسحر واقعن وكثير من الناس منه ما يقتل، ومنه ما يمرض، ومنه ما يغير العقل، لهم فيه أنواع من التصرفات، فيستعينون بالجن والشياطين في ذلك، وقد وقع هذا في عهد موسى -عليه الصلاة والسلام- وقام سحرة فرعون بجمع العصي، والحبال  على أعين الناس، وسحروا أعينهم؛ حتى ظن الناس أن هذه العصي، وهذه الحبال حيات يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فلما ألقى موسى عصاه لقفتهان وأخذتها كلها، وعرف الناس بطلان هذا السحر، وخر السحرة سجدا لله  وتابوا وأنابوا إلى الله .\n\nوالمقصود: أن هذا له علاج، فإذا عرف بالعلامات التي اعتادها أنه سحر؛ استعمل الرقية من السحر، وذكر بعض المتقدمين أن من أسباب العلاج، وأن مما يدخل في العلاج سبع ورقات سدر، تدق وتجعل في الماء أيضًا، وأن هذا أيضًا قد ينفع بإذن الله من أمر السحر.\n\nوهكذا في أمر الرجل الذي يحبس عن زوجته، ويمنع من زوجته إذا قرئ له هذه الآيات مع الفاتحة، مع آية الكرسي، مع قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، وشرب منه، واغتسل بالباقي، فالغالب أنه يزول أثره ويطلق حبسه.","link":"https://binbaz.org.sa/fatwas/3220/معرفة-السحر-والعين-من-خلال-الخبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1565.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7345,"question":"تغيب أخي عن المنزل منذ مدة، وبحثنا عنه في كل مكان بواسطة الشرطة، وعن طريقنا، وفي المستشفيات، ولكننا لم نجد له أثرًا أبدًا، فأخذت أبحث أنا وبعض الناس عن الموضوع، فنصحوني بأن أخبر سماحتكم عن الموضوع؛ لأنهم قالوا لي: ربما اهتم الشيخ بالموضوع، ويرى رؤيا تدلكم على مكانه، أما القسم الآخر فقالوا لي: اذهب إلى أي ساحر؛ لكي يخبرني عن مكانه فقط، ولكن رفضت كلا الافتراضين خوفًا من حرمتهما، نرجو أن تخبرونا إلى الطريق السليم أثابكم الله؟","title":"حكم الذهاب إلى السحرة والكهنة","answer":"الجواب: أما الذهاب إلى السحرة والكهنة فلا يجوز، قال النبي ﷺ: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام وسئل عن الكهان فقال: لا تأتوهم، وقال: ليسوا بشيء فقالوا له: قد يصدقون؟ فقال: تلك الكلمة يسمعها الجني من السماء فيقرها في أذن وليه من الإنس، فيكذب معها مائة كذبة، وفي لفظ آخر: أكثر من مائة كذبة فلا يجوز سؤالهم ولا إتيانهم.  لكن بالإمكان سؤال الناس في مجامع الناس، بإمكان الكتابة في الجرايد والصحف، من رأى فلانًا وصورته كذا وصورته كذا؟ قد يقرأ الجريدة بعض الناس، ويكون عنده خبر أو يسمع الجريدة هو في أي مكان، المقصود بالإذاعة والصحف المحلية أو الصحف الأخرى في البلد التي تظن أنه ذهب إليها، وكذلك مجامع الناس، فينطبق عليه ما ينطبق على الضالة، من رأى فلانًا وصفته كذا وكذا وكذا، أما الرؤيا فقد تقع الرؤيا من بعض الناس، قد تنفع الرؤيا، الرؤيا جزء من ستة وأربعين جزءًا من النبوة، ذهبت النبوة وبقيت المبشرات، قد تقع في بعض الناس، ويستدل ...","link":"https://binbaz.org.sa/fatwas/3433/حكم-الذهاب-الى-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1741.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7356,"question":"تغيب أخي عن المنزل منذ مدة، وبحثنا عنه في كل مكان بواسطة الشرطة، وعن طريقنا، وفي المستشفيات، ولكننا لم نجد له أثرًا أبدًا، فأخذت أبحث أنا وبعض الناس عن الموضوع، فنصحوني بأن أخبر سماحتكم عن الموضوع؛ لأنهم قالوا لي: ربما اهتم الشيخ بالموضوع، ويرى رؤيا تدلكم على مكانه، أما القسم الآخر فقالوا لي: اذهب إلى أي ساحر؛ لكي يخبرني عن مكانه فقط، ولكن رفضت كلا الافتراضين خوفًا من حرمتهما، نرجو أن تخبرونا إلى الطريق السليم أثابكم الله؟","title":"حكم الذهاب إلى السحرة والكهنة","answer":"الجواب: أما الذهاب إلى السحرة والكهنة فلا يجوز، قال النبي ﷺ: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام وسئل عن الكهان فقال: لا تأتوهم، وقال: ليسوا بشيء فقالوا له: قد يصدقون؟ فقال: تلك الكلمة يسمعها الجني من السماء فيقرها في أذن وليه من الإنس، فيكذب معها مائة كذبة، وفي لفظ آخر: أكثر من مائة كذبة فلا يجوز سؤالهم ولا إتيانهم.  لكن بالإمكان سؤال الناس في مجامع الناس، بإمكان الكتابة في الجرايد والصحف، من رأى فلانًا وصورته كذا وصورته كذا؟ قد يقرأ الجريدة بعض الناس، ويكون عنده خبر أو يسمع الجريدة هو في أي مكان، المقصود بالإذاعة والصحف المحلية أو الصحف الأخرى في البلد التي تظن أنه ذهب إليها، وكذلك مجامع الناس، فينطبق عليه ما ينطبق على الضالة، من رأى فلانًا وصفته كذا وكذا وكذا، أما الرؤيا فقد تقع الرؤيا من بعض الناس، قد تنفع الرؤيا، الرؤيا جزء من ستة وأربعين جزءًا من النبوة، ذهبت النبوة وبقيت المبشرات، قد تقع في بعض الناس، ويستدل ...","link":"https://binbaz.org.sa/fatwas/3433/حكم-الذهاب-الى-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1741.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7737,"question":"سماحة الشيخ هذه رسالة وردت من عبد الله محمد علي العذري اليماني يسأل عن التطبب، يقول: يوجد امرأة في قرية وملقبة مصاصة يذهب إليها الرجال والنساء وكل واحد يشتكي مرض في بطنه أو ظهره أو صدره، وكل واحد يعطيها مبلغ مائة ريال، وإذا كان المريض يشتكي من بطنه ترقده على ظهره وتمص بطنه بفمها، يعني تعمل فمها على بطنه أو صدره أو ظهره وتمص مثل المحجم بدون أن تستعمل شيء بفمها، وبعد ذلك تخرج من فمها حصاة أو عرق أو غير ذلك، هل هذا الأمر صحيح، أفيدونا جزاكم الله خيراً؟","title":"حكم الذهاب إلى المشعوذين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذه المرأة المسئول عنها يظهر أنها دجالة وأنها تعمل أعمالاً تغر بها الناس ليظنوا أن عندها علماً وأن عندها شيئاً خارقاً أو شيئاً لا يعرفه الأطباء، فتعمل ما ذكر من مص بطن الرجل ثم إخراج أشياء من فمها كحصى أو نحوه، هذه إما أن تكون تستخدم الجن وتلعب على أبصار الحاضرين، فتريهم أنها تخرج من بطنه شيئاً وليس هناك شيء، وإنما هو ...... على أعين الناس وسحر لأعينهم، كما فعل السحرة في وقت موسى عليه الصلاة والسلام مع فرعون ، وإما أن تكون أن تجعل في فمها شيء عند مجيئها إلى المريض من حصى أو غيره وتخرجه عندما تمص بطنه لتري الناس أن هذا الشيء خرج من بطنه، والذي نرى في هذه وأمثالها أنه لا يجوز أن يذهب إليها ولا أن تستطب لأن هذه وأشباهها من المشعوذين وممن يتلاعب على الناس بالكذب أو باستخدام الجن وتعاطي ما حرم الله عز وجل من الشرك وغيره من المنكرات التي تفعل مع الجن، لسؤالهم عن مرض الشخص الذي يراد تطببها فيه.\nفالحاصل أن هذه المرأة يظهر من عملها هذا أنها دجالة وأنها متلاعبة وأنها كذابة أو مستخدمة للجن، فلا يجوز إتيانها ولا أشباهها، وقد قال النبي عليه الصلاة والسلام في الحديث الصحيح: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً أخرجه مسلم في الصحيح، وفي لفظ آخر: من أتى كاهناً أو عرافاً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فهذه وأشباهها من العرافين الذين يكذبون ويتعاطون أموراً لا صحة لها بل هي أشياء مكذوبة أو مأخوذة عن الجن لتغرير الناس وإدخال السوء عليهم من دون أن يعلموا الحقيقة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4936/حكم-الذهاب-الى-المشعوذين ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_034/03401.mp3","categories":["السحر والكهانة"]},{"id":7785,"question":"استعرضنا السؤال الأول لـعبد الرحمن ، أما سؤاله الثاني فيقول فيه: أرجو من فضيلتكم أن تبينوا حرمة استعمال وقراءة كتب السحر والتنجيم، حيث أنها موجودة بكثرة، وبعض زملائي يريدون شراءها، ويقولون: إنها إذا لم تستعمل فيما يضر فليس في ذلك حرام، نرجو الإفادة وفقكم الله؟","title":"وجوب إتلاف كتب السحر والتنجيم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: هذا الذي قاله السائل حق، يجب على المسلمين أن يحذروا كتب السحر والتنجيم، ويجب إتلافها، يجب على من وجدها أن يتلفها؛ لأنها تضر المسلم وتوقعه في الشرك، والنبي عليه الصلاة والسلام قال: من اقتبس شعبة من النجوم فقد اقتبس شعبة من السحر زاد ما زاد، والله يقول في كتابه العظيم عن الملكين: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102]، فدل على أن تعلم السحر والعمل به كفر ، فيجب على أهل الإسلام أن يحاربوا الكتب التي تعلم السحر والتنجيم، وأن يتلفوها أينما كانت، هذا هو الواجب، ولا يجوز لطالب العلم ولا غيره أن يقرأها أو يتعلم فيها، أو غير طالب العلم كذلك ليس له أن يقرأها ولا أن يتعلم ما فيها ولا أن يقرها؛ لأنها تفضي إلى الكفر بالله، فالواجب إتلافها أينما كانت، كل الكتب التي تعلم السحر والتنجيم مثل شمس المعارف وأشباهها يجب إتلافها. نعم.","link":"https://binbaz.org.sa/fatwas/5102/وجوب-اتلاف-كتب-السحر-والتنجيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04801.mp3","categories":["السحر والكهانة"]},{"id":7804,"question":"هذا سائل يقول: رجل أصيب بمرض وقد عالج بالدواء وقراءة القرآن ولم يشف، وقد أشار عليه البعض بالذهاب إلى أحد السحرة، وعلل له بأنه إذا لم يشف فالذهاب للسحرة لا بأس به، فما الجواب؟","title":"حكم الذهاب إلى السحرة للعلاج","answer":"الجواب: هذا منكر لا يجوز، الرسول ﷺ نهى عن ذلك: من أتى عرافاً أو كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وفي الحديث الآخر: ليس منا من سحر أو سحر له أو تكهن أو تكهن له، كذلك في الحديث الآخر: ثلاثة لا يدخلون الجنة: مدمن خمر وقاطع رحم ومصدق بالسحر.\nفالواجب على المسلم الحذر من ذلك، وأن يقرأ القرآن ويذهب إلى العلماء الأخيار وقراء القرآن الطيبين، ويسأل ربه الشفاء والعافية، يلجأ إلى الله في سجوده وفي الليل وفي آخر الليل وفي آخر الصلاة يسأل ربه العافية والشفاء.\nأما الذهاب إلى العرافين أو الكهنة أو المنجمين أو السحرة كله منكر والعياذ بالله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5202/حكم-الذهاب-الى-السحرة-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05120.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":7824,"question":"هذا سائل يقول: رجل أصيب بمرض وقد عالج بالدواء وقراءة القرآن ولم يشف، وقد أشار عليه البعض بالذهاب إلى أحد السحرة، وعلل له بأنه إذا لم يشف فالذهاب للسحرة لا بأس به، فما الجواب؟","title":"حكم الذهاب إلى السحرة للعلاج","answer":"الجواب: هذا منكر لا يجوز، الرسول ﷺ نهى عن ذلك: من أتى عرافاً أو كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وفي الحديث الآخر: ليس منا من سحر أو سحر له أو تكهن أو تكهن له، كذلك في الحديث الآخر: ثلاثة لا يدخلون الجنة: مدمن خمر وقاطع رحم ومصدق بالسحر.\nفالواجب على المسلم الحذر من ذلك، وأن يقرأ القرآن ويذهب إلى العلماء الأخيار وقراء القرآن الطيبين، ويسأل ربه الشفاء والعافية، يلجأ إلى الله في سجوده وفي الليل وفي آخر الليل وفي آخر الصلاة يسأل ربه العافية والشفاء.\nأما الذهاب إلى العرافين أو الكهنة أو المنجمين أو السحرة كله منكر والعياذ بالله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5202/حكم-الذهاب-الى-السحرة-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05120.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8093,"question":"ونبدأ أولاً برسالة عبد الله صالح محمد أبو صافية العمري من قرية آل عطيف، يقول: ما حكم من لجأ إلى المشعوذين، الذين يدعون أن لهم القدرة على رفع بعض الأمراض العقلية عن بعض الناس، وقد لجأ إليهم بعض الناس وشوفي من مرضه، ويقال: إنهم يستعينون بالجن في ذلك، فما جزاؤهم عند الله؟ وما حكم من لجأ إليهم؟","title":"حكم الذهاب إلى المشعوذين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فاللجأ إلى المشعوذين وسؤالهم عما يبتلى به بعض الناس من الأمراض، أمر لا يجوز، وقد صح عن النبي عليه الصلاة والسلام أنه قال: من أتى عرافاً فسأله عن شيء، لم تقبل له صلاة أربعين يوماً أخرجه مسلم في الصحيح، وقال عليه الصلاة والسلام: من أتى كاهناً -وفي لفظ: عرافاً- فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، في أحاديث أخرى، والعراف والكاهن ونحوهما هو الذي يدعي علم الغيب بواسطة الجن، هذا يقال له: عراف، ويقال له: كاهن، فلا يجوز سؤال هؤلاء، ولا يجوز إتيانهم، بل يجب ترك سؤالهم، ومن سألهم وأتاهم يستحق أن يؤدب ويعزر حتى يدع ذلك، وكذلك هم الكهان والعرافون يجب أن يزجروا ويؤدبوا ويمنعوا من أعمالهم هذه، ويستتابوا عما فعلوا من دعواهم أنهم يعرفون ما يصيب الناس، بواسطة من يتوسطون به من الجن، وهذا كله باطل وكله منكر، أما كون بعض الناس قد يشفى، فهذا قد يكون عن أمراض سببها له الجن وشياطين الجن، ثم إذا تقرب إليهم وتقرب إليهم هذا الذي يدعي أنه طبيب، إذا تقرب إليهم بما يريدون، قد يزيلون ويرفعون ما فعلوه هم بأنفسهم، من أسباب مرض هذا الشخص.\nفالحاصل أنهم قد يتعاطون أشياء تؤذي الإنسان، فإذا اتصل بهم من يعبدهم ويعظمهم، أزالوا ذلك الشيء الذي يفعلونه، فيسكن المرض، كما يروى عن ابن مسعود : «أنه قال لامرأته لما كانت تذهب إلى يهودي فيرقي عينها، قال لها: إنه الشيطان ينخسها بيده، فإذا قرأ عليك ذاك اليهودي كف عنها » يعني لإغرائها باليهودي.\nفالمقصود أن هؤلاء الذين يدعون أنهم يتصلون بالجن، ويسألونهم بعض الحاجات، هؤلاء لا يسألون ولا يصدقون، بل يجب أن يبتعد عنهم المسلم ويحذرهم، ويجب على ولاة الأمور إذا عرفوهم أن يزجروهم وأن يؤدبوهم، حتى يمتنعوا من هذه الأعمال، وإذا كانوا يدعون الغيب وجب أن يستتابوا، فإن تابوا وإلا قتلوا كفاراً؛ لأن دعوى علم الغيب كفر، الغيب لا يعلمه إلا الله . نعم.","link":"https://binbaz.org.sa/fatwas/5885/حكم-الذهاب-الى-المشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08601.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8460,"question":"في السؤال الأخير من رسالتهم أخونا (م. أ. ع) يقول: في قريتهم إمام يصلي بهم وهو يتعاطى أمراً كثيراً ما حيرهم، ذلك الأمر هو: عندما أحد يتزوج بالقرية لم يجعله يتم الزواج الكامل حيث أن العروسين يحصل بينهما غضب شديد، ويقال: اذهبوا إلى هذا الشيخ لكي يعمل لهم ورقة وهم يرضون على بعض، وعندما يحضر الشيخ يأتي بكتب من الإنس والجن ويقرأ فيها، ويمسح على رأس العروسين بزيت الطيب ويحضر معه حبراً أحمر ويقول: هذا الحبر تنقعه في الماء وتشربه وبعد ذلك يقول: ائتوني بدجاجة كي أذبحها ويأخذ دمها ويضعه على رأس العروسين، وبعد ذلك ينصرف الغضب ويستمر سماحة الشيخ على وصف تلكم الطريقة التي يتبعها ذلكم الرجل ويرجو التوجيه للناس في تلك المنطقة؟","title":"حكم الصلاة خلف المشعوذين","answer":"الجواب: هذا العمل الذي يعمله هذا الرجل تخريف وخطأ وغلط، وتلبيس على الناس لا وجه له ولا أساس له من الصحة، بل الواجب على من أحس بشيء من الغضب أن يتعوذ بالله من الشيطان حتى يهدأ غضبه، ويشرع له الوضوء يتوضأ الوضوء الشرعي كما أمر النبي ﷺ؛ لأن الشيطان خلق من النار، والنار تطفأ بالماء والغضب من الشيطان، فالمؤمن يفعل الأشياء الشرعية يتعوذ بالله من الشيطان الرجيم يتوضأ هذا مشروع، كذلك من أسباب إطفاء الغضب كونه يجلس إن كان قائماً ويضطجع إن كان قاعداً أو يخرج من المحل حتى يهدأ الغضب.\nأما ما يعمله هذا الشيخ من تلطيخ رءوسهم بالزيت أو بدم الدجاجة أو بغير هذا مما يقول، كل هذا لا أصل له، كله غلط وكله تلبيس وخداع لا وجه له، وإذا كان قصد ذبح الدجاجة للجن صار شركاً أكبر، يعني: ذبحها للجن يتقرب إلى الجن صار شركاً أكبر، في الحديث الصحيح: لعن الله من ذبح لغير الله والله يقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163] ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] والنحر: هو الذبح.\nفالمقصود: أن هذا العمل الذي يعمله هذا الرجل غلط، فينبغي أن يعرضوا عنه ولا يقبلوا منه وينصحوه، فإن لم ينتصح ينبغي أن يتفقوا على شخص غيره يصلي بهم، ولا يصلي بهم هذا؛ لأن هذا متهم بالشركيات، عمله ذبح الدجاجة هذا يوهم شراً كثيراً.\nفالحاصل: إن مثل هذا ما ينبغي أن يكون إماماً لهم إن لم يتب، فإن تاب فالحمد لله، وإلا فليزيلوه ويلتمسوا إماماً آخر لمسجدهم ولا يلتفتوا إليه في مسألة إذا حصل بين العريسين شيء من الغضب أو الجفوة لا يلتفتوا إليه، بل يعالج ما بين العريسين بالطرق الأخرى، بالنصيحة بالتوجيه بقراءة القرآن بأن يقرأ لهم إذا كان نوع مرض يعني: أصابهم شيء توقف من الزوج عن زوجته، هذا يقرأ له القرآن يقرأ له قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] .. قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين وآية الكرسي، وآيات السحر من سورة الأعراف ويونس وطه ويشرب من ذلك ويتروش من ذلك، ويزول ما قد يصيبه من المنع والحبس.\nفالحاصل: أن هذا قد يقع لبعض الناس حبسه عن زوجته، فيعالج بالقرآن والأدوية الشرعية، أما عمل هذا الرجل فهو عمل باطل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6466/حكم-الصلاة-خلف-المشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12307.mp3","categories":["صلاة الجماعة","السحر والكهانة"]},{"id":8590,"question":"هذه رسالة وردتنا من السائل محمد علي القرني من جدة القاعدة الجوية، والسؤال موجه لسماحة الشيخ عبد العزيز بن باز ، يقول: هل يجوز التداوي عند بعض الناس من النساء والرجال الذين يدعون أنهم يعالجون المريض عن طريق استحضار الجن، والسؤال يدور حول امرأة تستدعي الجن عند معالجة المريض، وهي تذكر الله ورسوله صلى الله عليه وسلم وتقرأ الفاتحة وبعض سور القرآن، ثم يحضر الجان ويسلم على الجالسين حوله، ويذكر أن الفساد منتشر في الأرض، وأن الظلم سائر بين الناس، ثم يصف العلاج من بعض الأعشاب، ومن ضمن ما يذكر للمريض أن يذبح ديكاً أو دجاجة ويخصها بلون من الألوان، ويضعها على صدر المريض، ويقول: بمشيئة الله أن يزول هذا المرض عن المريض، ولكن بعد أن يتم الشفاء يطلبون من المريض أن يزورهم في السنة مرة أو مرتين عند عيد الفطر أو الأضحى أو في رجب، وللأسف يعود المرض على المريض أو أحد أقربائه مما جعل لها الأثر الكبير في قلوب من يذهب إليها أو غيرهم، وأن من يذكرها بسوء أو يقول: إنها مشعوذة -إن جاز له التعبير عند هؤلاء- يردون عليه بقولهم: إنها طيبة ويغدقون عليها المدح، ويدعون لها بالستر والرضا من الله، هل يجوز الذهاب إلى هذه المرأة لغرض العلاج إذا عجز الطب الحديث، أفيدونا أفادكم الله؟","title":"حكم الذهاب إلى العرافين والمشعوذين","answer":"الجواب: هذه المرأة وأشباهها لا يجوز أن تؤتى لطلب العلاج ولا للسؤال عن شيء، هذه المشعوذة ويطلق عليها كاهنة وعرافة، فلا يجوز إتيانها ولا سؤالها، بل يجب إبعادها عن الأرض، والقضاء عليها، إن كانت غير سعودية يجب أن تؤدب وتبعد، وإن كانت سعودية يجب أن تؤدب وتضرب وتسجن حتى تدع هذا العمل القبيح، فإن التقرب إلى الجن واستحضارهم والاستعانة بهم في العلاج من أعظم الشرور، ومن أعظم الفساد، وقد يفضي إلى الشرك، فقد تدعوهم من دون الله، وقد تستغيث بهم، وقد تقرب إليهم بعض القرابين من الذبائح وهذا شرك أكبر، نعوذ بالله، وقد قال النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح.\nوقال عليه الصلاة والسلام: من أتى كاهناً أو عرافاً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ فهذه من العرافات، فلا يجوز إتيانها ولا سؤالها، وذلك مما دلت عليه السنة الصحيحة عن رسول الله عليه الصلاة والسلام، وهو أيضاً يفضي إلى فساد كبير، وإلى الشرك الأكبر، ومما يدل على خبثها وفسادها أنها تأمر بذبح بعض الحيوانات ويجعل على المريض، وهذا من الكذب وليس له دخل في العلاج، ولكنها تلبس به وربما بعد حين تأمر بذبحه للجن، فيقع الشرك الأكبر.\nومن تلبيسها أنها تذكر الله وتصلي على النبي ﷺ حتى لا يظن بها سوء، حتى يقال: إنها طيبة، ومن تلبيس الجني وخداعه أنه يأتي ويقول للناس: فعلوا وفعلوا ويتوجع من ظلم الناس ومعاصيهم حتى يظن الناس به خيراً، وحتى يقلدوه ويقبلوا علاجه، فكل هذا تلبيس وخداع، فالواجب الحذر منها، والواجب على من عرفها أن يرفع أمرها إلى ولاة الأمور، إلى الأمير، أمير البلد والحاكم.. القاضي.. حتى يقوموا بما يلزم من جهة إبعادها وتأديبها ومنعها من هذه الأعمال القبيحة. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6668/حكم-الذهاب-الى-العرافين-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20907.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8699,"question":"هنا رسالة من حوطة بني تميم باعثها أخونا عبد الله راشد طالب، أخونا يقول: أرجو أن تقدموا رسالتي هذه إلى سماحة الشيخ عبدالعزيز بن باز، وتساؤلي هو: نسمع كثيراً عن الكهنة والمنجمين، فما صحة ديانة من يذهب إليهم والإيمان بأقاويلهم ذلكم أنهم يأتون بما يثبت الصحيح، فمن ذلك: أنهم يخبرون المرء باسم قريب من أقاربه ويصفون له منزله وربما وصفوا له ما عنده من المال والأولاد.. ويستمر في سرد ما يقوله أولئك سماحة الشيخ ويرجو التوجيه؟","title":"حقيقة الكهنة والمشعوذين وحكم إتيانهم","answer":"الشيخ: هذا موجود في عهد النبي ﷺ وقبله وبعده ولهذا نهى النبي ﷺ عن إتيان الكهان وعن سؤالهم، قال عليه الصلاة والسلام: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في صحيحه، وقال أيضاً عليه الصلاة والسلام: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ وسأله بعض الناس عن إتيان الكهان؟ قال: لا تأتوهم، وقال: ليسوا بشيء. قالوا: يا رسول الله! إنهم يصدقوننا في بعض الأحيان، قال: تلك الكلمة يسمعها الجني من السماء -المسترق للسمع- فيقرها في أذن وليه من الإنس -وهو الكاهن والساحر- فيصدق في تلك الكلمة ولكنهم يقرفون ويزيدون عليها مائة كذبة -وفي رواية: أكثر من مائة كذبة فيقول الناس: إنه صدق يوم كذا وكذا، فيصدقونه بتلك الكلمة التي سمعت من السماء وتكون وسيلة إلى تصديقه في كذبه الكثير.\nفالكهان لهم أصحاب من الشياطين من الجن، الكاهن هو الذي له رئي، يعني: صاحب من الجن يخبره عن بعض المغيبات وعن بعض ما يقع في البلدان، وهذا معروف في الجاهلية وفي الإسلام وهو الكاهن، وهو الذي له صاحب من الجن يشعره ويخبره عما يلقاه من شياطينه وإخوانه فيقول: جرى كذا، ووقع كذا في البلد الفلانية؛ لأن الجن يتناقلون الأخبار فيما بينهم، والشياطين تتناقل الأخبار فيما بينها، فيخبر بعضهم بعضاً بسرعة هائلة من الشام إلى اليمن من اليمن إلى الشام إلى مصر إلى نجد إلى أمريكا إلى أي مكان، بينهم تناقل للأخبار فلهذا قد يغتر بهم من يسمع صدقهم في بعض المسائل.\nوكذلك قد يعرف الشيطان قريب هذا المبتلى؛ أخوه.. عمه من الشياطين التي بينهم، كل إنسان معه شيطان، كل إنسان منا معه شيطان، معه قرين من الإنس وقرين من الجن، كل واحد من بني آدم، فالشياطين يخبر بعضها بعضاً ويدل بعضها على عورات بعض وقد تخبر عما عندهم من المال، ما عندهم من الأولاد، ما عندهم من الأثاث، كل هذا يقع بين الناس.\nوقد يسترقون السمع فيسمعون بعض ما يقع في السماء بين الملائكة مما يتكلم الله به جل وعلا من أمور أهل الأرض وما يحدث في الأرض، فيتسامعون تلك الكلمة، فإذا سمعوها قروها في أذن أصحابهم من الكهنة والسحرة والمنجمين، فيقول المنجم والساحر والكاهن: سوف يقع كذا سوف يقع كذا، عن تلك الكلمة التي سمعت من السماء، ولا يكتفي بهذا بل يكذب معها الكذب الكثير حتى يروج بضاعته وحتى يأخذ أموال الناس بالباطل، فهي بسبب هذا الكلام الذي ينقله إليهم سوف يجري كذا سوف يقع كذا، إذا صدق في موضع نقل الناس هذا الصدق الذي وافق فيه الخبر الذي وقع في السماء، أو وافق فيه الحوادث التي وقعت في بعض البلدان، فعند هذا الناس يغلب عليهم تصديقهم بسبب هذه الحوادث، فيقولون: صدق في يوم كذا، صدق في كذا، صدق في كذا، والمرضى يتعلقون بخيط العنكبوت ويتشبثون بكل شيء، فلهذا يأتون الكهنة ويأتون المنجمين ويأتون السحرة بسبب ما قد يسمعون عنهم أنهم صدقوا في كذا وصدقوا في كذا.\nفالواجب عدم إتيانهم وعدم سؤالهم وعدم تصديقهم ولو قدر أنهم صدقوا في بعض الشيء، الواجب تركهم بالكلية؛ لأن الرسول ﷺ نهى عن إتيانهم، ونهى عن سؤالهم ونهى عن تصديقهم، فالواجب على المسلمين أن لا يصدقوهم وأن لا يسألوهم وأن لا يأتوهم بالكلية، هذا هو الواجب على الجميع، وأن يسلكوا في علاج المرضى ما شرعه الله من القراءة والدواء المباح ونحو ذلك مما يعرفه الأطباء، فبين الأطباء وبين القراء الذين يرقون المرضى ويعرفون بإسلامهم ودينهم، هذه هي الأسباب الشرعية والوسائل الشرعية، أما إتيان الكهان والمنجمين والرمالين والعرافين وسؤالهم هذا منكر لا يجوز، نسأل الله العافية والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/6846/حقيقة-الكهنة-والمشعوذين-وحكم-اتيانهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13106.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8713,"question":"كما ينوه الإخوان سماحة الشيخ من خوفهم على عقيدتهم عند اللجوء إلى أولئك الذين يجسدون الأمور وقد يتكهنون بأشياء وأشياء لعل لسماحة الشيخ توجيه في علاج مثل هذا ولاسيما فيما يتعلق أيضاً بخوف الناس من السحر ومن الجن؟","title":"النهي عن إتيان الكهنة والمشعوذين وسؤالهم","answer":"الجواب: أما ما يتعلق بسؤال الكهنة والمنجمين والعرافين والرمالين وأشباههم من أصحاب الشعوذة ودعوى علم الغيب ودعوى أنهم يدركون أشياء بواسطة الجن ما أدركها غيرهم فهذا كله لا يجوز، والرسول ﷺ نهى عن إتيانهم وعن سؤالهم، سئل عن الكهان عليه الصلاة والسلام فقال: إنهم ليسوا بشيء وقال: لا تأتوهم وقال عليه الصلاة والسلام: من أتى عرافاً فسأله عن شيء لمم تقبل له صلاة أربعين يوماً خرجه الإمام مسلم في صحيحه من حديث بعض أزواج النبي عليه الصلاة والسلام، وفي لفظ: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ.\nهذا يدل على أن هؤلاء لا يؤتون ولا يسألون ولا يصدقون؛ لأن عمدتهم الخرص والتكهنات التي لا أساس لها أو الاعتماد على ما يقوله الجن وخرافات الجن وشياطينهم، فلا ينبغي أن يعتمد عليهم، وقد قال ﷺ لما قيل له: إن الكهان قد يصدقون قال: إنهمم يصدقون في كلمة ويكذبون في مائة وفي اللفظ الآخر: في أكثر من مائة وبين عليه الصلاة والسلام أن هذه الكلمة التي يصدقون فيها هي التي يسمعونها من السماء يسمعها مسترقو السمع من السماء من الملائكة فيكذبون معها الكذب الكثير، في إحدى الروايات: فيكذبون معها مائة كذبة وفي لفظ آخر: فيقرفون ويزيدون في بعضها: فيكذبون أكثر من مائة كذبة فيقال: قد صدقوا في كذا وكذا فيصدقون بسبب تلك الكلمة التي سمعت من السماء، والناس من عادتهم الميل إلى الشعوذة وإلى كل ما يظنون أنه ينفع فيتشبثون بكل شيء، والمريض يتشبث بكل شيء أيضاً، فلهذا يصدقون الكهنة والمنجمين في كذبهم الكثير بأسباب أنهم قد صدقوا في واحدة أو نفعوا في واحدة أو ثنتين مثلاً، وهذا كله من طبيعة البشر الميل إلى من ظن أن عنده شيئاً ولاسيما إذا كان قد عرف أنه نفع فيه ولو في واحدة، فيتعلق به ويصدقه في كل شيء ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6863/النهي-عن-اتيان-الكهنة-والمشعوذين-وسوالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_133/13303.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8715,"question":"فيما يتعلق بالجن أو السحر سماحة الشيخ؟","title":"كيفية الوقاية من السحر والجن","answer":"الجواب: السحر قد يقع قد يقع السحر بين الناس لا شك فيه وهو في الغالب يكون بعمل من شياطين الإنس الذين يتلقونه عن الجن فيعقدون عقداً وينفثون فيها بريقهم الخبيث وكلماتهم الشيطانية فقد يقع بإذن الله ما يريدون، كما قال جل وعلا: قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ [الفلق:1-2] وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ [الفلق:4] هم السواحر اللاتي ينفثن في العقد بالريق الخبيث والكلمات الخبيثة والدعوات الخبيثة، فقد يقع ما أرادوا بإذن الله وقد لا يقع، ولهذا قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونََ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ [البقرة:102].\nفالسحر حق قد يقع وهو منكر عظيم والرسول ﷺ قرنه بالشرك قال ﷺ: اجتنبوا السبع الموبقات. قلنا: وما هن يا رسول الله؟ قال: الشرك بالله والسحر فجعله قرين الشرك، هكذا جاء في الصحيحين من حديث أبي هريرة، فالله جل وعلا قال: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فهو من تعليم الشياطين ومن تعديهم على بني آدم وإيذائهم لهم وإيقاعهم في أنواع الباطل.\nفينبغي للمؤمن أن يتحرز عن ذلك بما تقدم من التعوذات الشرعية؛ آية الكرسي، من قراءة (قل هو الله أحد) والمعوذتين بعد الصلوات، قراءتها عند النوم، قراءة (أعوذ بكلمات الله التامات من شر ما خلق) يقول ﷺ: من نزل منزلاً فقال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله ذلك وجاءه رجل فقال: لقد لقيت كذا وكذا هذه الليلة من لدغةة عقرب -أو كما قال الرجل- فقال له ﷺ: أما إنك لو قلت: أعوذ بكلمات الله التامات من شر ما خلق لم يضرك وجاء في حديث آخر أنه قال: من قال: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات لم تضره الحمة يعني: سم السموم، فالمقصود أن هذه التعوذات الله جل وعلا جعلها سبباً للعافية والسلامة من هذه الشرور.\nفينبغي للمؤمن أن يكون عنده قوة إيمان وقوة ثقة بالله وحسن ظن بالله مع إتيانه بهذه الأوراد الشرعية والتعوذات الشرعية، والله جل وعلا هو الكافي المعافي سبحانه وتعالى بيده كل شيء أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ [الزمر:36]. نعم.\nالمقدم: هناك علاج من آيات من القرآن الكريم بالنسبة للسحرة أو الجن؟\nالشيخ: كذلك الجن ..... التعوذ بالله منهم من أسباب السلامة، فإن الجن مخلوقون مربوبون فالذي خلقهم هو الذي يعيذ منهم سبحانه وتعالى، فإذا الإنسان لجأ إلى الله وتعوذ بكلماته التامة من شر ما خلق أعاذه منهم ومن غيرهم، وهكذا آية الكرسي عند النوم من أسباب السلامة منهم ومن غيرهم، وهكذا قراءة (قل هو الله أحد) والمعوذتين من أسباب السلامة من كل شر ومن الشياطين أيضاً، فالله سبحانه هو الخلاق وبيده تصريف الأمور جل وعلا، وبيده الضر والنفع والعطاء والمنع فما شاء الله كان وما لم يشأ لم يكن سبحانه وتعالى، قد ذكر عن السحرة أنهم يتعلمون من السحر الذي تفعله الشياطين وتلقيه الشياطين، يفعلون من ذلك ما يفرقون بين المرء وزوجه، يعني: يفعلون أشياء تسبب كراهة الزوج لزوجته أو كراهتها له حتى يفارقها، ثم قال بعده: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] يعني: من حظ ولا نصيب وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ ۝ وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102-103] فدل على أنه خلاف التقوى وخلاف الإيمان. نعم.\nوبين أيضاً أنه كفر قال: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] فدل على أن تعلم السحر وتعليم السحر واستعماله كفر بعد الإيمان نعوذ بالله؛ لأنه إنما يكون بطاعة الشياطين وعبادتهم من دون الله، فإذا أطاع الشياطين من الجن وعبدهم من دون الله علموه بعض الأشياء التي تضر الناس، ويروى عن أبي هريرة  أن النبي ﷺ قال: من سحر فقد أشرك.\nفالمقصود أن السحر من أسباب الشرك؛ لأنه لا يتوصل إليه إلا بعبادة الجن والاستغاثة بهم والاستعانة بهم، والتقرب إليهم بذبح أو نذر أو سجود أو غير ذلك، فلهذا حكم العلماء على السحرة بأنهم كفار، هذا هو المعروف عند جمهور أهل العلم: أن كل ساحر كافر، من عرف بالسحر فهو كافر.\nقال بعض أهل العلم: يسأل عن صفة سحره؟ فإن وصف شيئاً يدل على الكفر صار كافراً وإلا صار من جملة المعاصي ومن جملة الظلم للناس، وبكل حال هذا المعنى ما يخالف ما قاله الجمهور، فإن مراد الجمهور هو السحر الذي لا يعرف له أسباب تبعده عن الكفر، فالساحر في الغالب إنما يكون ساحراً بخدمته للجن وعبادته للجن، أما إذا ادعى سحراً في شيء لا يكون من جنس السحر ولكنه قد يضر الناس بعمل آخر غير عبادة الجن وخدمة الجن وطاعتهم والاستغاثة ونحو ذلك كأشياء يستعملها من مواد تؤكل أو تشرب أو يدخن بها أو يدهن بها فتضر بعض الناس هذا من باب الضرر من باب الظلم من باب الإيذاء ليس من باب عبادة الجن. نعم.\nالمقدم: بارك الله فيكم. تتفضلون بذكر الآيات التي سمعتكم في مرة تتحدثون عنها سماحة الشيخ آيات التي تدفع السحر؟\nالشيخ: نعم ذكر بعض أهل العلم أن من أسباب العافية مما قد يمس الإنسان من السحر ومس الجن وما قد يمسه أيضاً من حبسه عن زوجته أن من أسباب الشفاء من ذلك: قراءة آية الكرسي ينفث بها في الماء والفاتحة سورة الفاتحة و قُلْ يَا أَيُّهَا الْكَافِرُونَ[الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين فإذا قرأ هذه السور والآيات الكريمة آية الكرسي وقرأ مع ذلك أيضاً آيات السحر الموجودة في سورة الأعراف وسورة يونس وطه كان ذلك من أسباب الشفاء إذا شرب من الماء وتروش به فإنه من أسباب سلامته من السحر ومن أسباب إطلاقه عن حبسه عن أهله.\nوآيات الأعراف هي قوله تعالى: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف:117-119] هذه الآيات في الأعراف من أسباب الشفاء قراءتها في الماء أو ينفثها على المريض ينفث بها مع الفاتحة ومع آية الكرسي ومع قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين إما أن ينفث بها على المصاب وإما أن يقرأها في ماء ثم يشرب منه ويتروش بالباقي.\nوفي سورة يونس يقول جل وعلا: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:79-82] يعني: إما ينفث بها عليه وإما يقرأها في الماء ونحوه.\nأما آيات طه فهي قوله سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69].","link":"https://binbaz.org.sa/fatwas/6865/كيفية-الوقاية-من-السحر-والجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_133/13304.mp3","categories":["الأدعية والأذكار","السحر والكهانة"]},{"id":9297,"question":"وأخيراً. يسأل الأخ أحمد علي معوضة في رسالته، فيقول: هل صحيح أن الجن تستطيع أن تدخل جسم الإنسان وتجعله يتكلم أو تتكلم بصوته، أفيدونا أفادكم الله؟","title":"ما صحة تلبُّس الجِنِيِّ بالإنس؟","answer":"الجواب: نعم، الجن تلتبس بالإنسان، تلتبس به على صفة خاصة حتى تنطق على لسانه، وتتكلم على لسانه بأشياء يعرف صوت الجني من صوت الإنسي، وهذا واقع قديماً وحديثاً، وهو المجنون الذي تلتبس به الجن هو المجنون، يتكلم الجني على لسانه، أعطوني كذا، أعطوني طيب، اذبحوا لي كذا، افعلوا كذا، ترى الدراهم في المحل الفلاني، بصوت يسمعه الناس غير صوت الإنسي، وهذا شيء يقع، ومن أنكره فقد غلط، وهذا التباس الجني بالإنسي، وبهذا يكون مجنوناً يختل عقله ويضطرب، فإذا ذهب عنه وفارقه رجع إليه عقله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7470/ما-صحة-تلبس-الجني-بالانس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9317,"question":"وهذه رسالة وردت من السائل عبد خلف محمد من العراق، يقول في رسالته: كنت غافلاً فوجدت سحراً قد عملوه لي ولزوجتي ليطردوني عن داري؛ لأنهم يقولون: هذا البيت مسكون وفيه شياطين، وذهبت إلى سيد من السادة أهل الدين وكشف لعائلتي ولبيتي، وقال لي: فعلوا لك سحراً قدره مائتين وخمسين دينار فهل هذا صحيح، ووجدت منه قطعة طويلة مكتوبة بالأزرق، وذهبت إلى هذا السيد وسحبه وأخذ مني عشرين دينار، وأن البيت لم يأتيه أي شيء، هل يصيبني ذنب مما فعلت أم لا؟","title":"حكم الذهاب إلى السحرة والعرافين","answer":"الجواب: السحرة والكهنة والعرافون لا يجوز سؤالهم ولا تصديقهم بما يقولون، يقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح، والعراف: هو الذي يدعي معرفة الأمور من طريق الغيب والتكهن، وهكذا الكاهن وهو الذي له رئي من الجن وصاحب من الجن يخبره ببعض المغيبات التي يسمعها من الناس في بلدان بعيدة أو قريبة أو يسمعها حين يسترق السمع من جهة السماء، فهؤلاء لا يسألون ولا يصدقون، وهكذا السحرة: وهم الذين يتعاطون أموراً يضرون بها الناس، فالسحر له وجود وله حقيقة وبعضه خيال، لكن بعضه له حقيقة يقتل، ويمرض، ويفرق بين المرء وزوجه، فلا يجوز سؤال السحرة ولا تصديقهم ولا العلاج عندهم، ولكنك تعالج المرض عند الأطباء المعروفين، أو بقراءة القرآن، يقرأ عليك القرآن وآيات السحر وينفث عليك، أو في ماء تشربه وتتروش به لا بأس.\nأما المعروفون بالسحر والمعروفون بتعاطي السحر أو الكهانة أو العرافة التي فيها دعوى علم الغيب فهذا كله لا يجوز، هؤلاء كلهم لا يجوز سؤالهم ولا تصديقهم.\nوعليك أن تتوب إلى الله من سؤال هذا الساحر، وعليك أن تعمل الأدوية المباحة والطب المباح، ومن ذلك أن تقرأ أنت أو يقرأ لك بعض الإخوان الطيبين أصحاب العقيدة الطيبة في ماء، يقرأ لك الفاتحة وآية الكرسي، وقل هو الله أحد والمعوذتين، وآيات السحر الموجودة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها في الماء ثم تشرب من ذلك الماء وتتروش بالباقي، هذا بإذن الله علاج لما قد يقع من السحر، وقد يجعل فيه سبع ورقات من السدر الأخضر يدق ويجعل في الماء ويكون أيضاً من باب الطب والعلاج المباح، لأنه مجرب ونافع في حق المسحور، وفي حق من حبس عن زوجته لأسباب، فإن هذا العلاج الشرعي بقراءة الفاتحة وآية الكرسي، وآيات السحر المعروفة في سورة الأعراف، وسورة يونس، وسورة طه، وقل يا أيها الكافرون، وقل هو الله أحد والمعوذتين، تقرأ في الماء وفيه السدر، أو ليس فيه سدر ثم يشرب منه الإنسان ويتروش منه المصاب بالسحر، أو المحبوس عن زوجته، ثم يبرأ بإذن الله ، وإن نفث فيه مع ذلك: اللهم رب الناس، أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقماً، وكرر هذا ثلاثاً طيب، هذه دعوات طيبة ثابتة عن رسول الله عليه الصلاة والسلام: اللهم رب الناس، أذهب البأس، واشف أنت الشافي لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nوهكذا الدعاء المعروف: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، باسم الله أرقيك ثلاث مرات أيضاً هذا ثابت عن النبي ﷺ أيضاً، فإذا نفث في هذا في الماء فهو أيضاً طيب ومن أسباب الشفاء وهو علاج نبوي علاج شرعي، الدعاء الأول: اللهم رب الناس أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nوالدعاء الثاني: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، باسم الله أرقيك يقوله ثلاث مرات.\nهذا من الدعاء الطيب الذي يرجى فيه النفع، والله المستعان، نعم، مع سؤال الله جل وعلا.. الإنسان يسأل ربه أن الله يمن عليه بالشفاء.. يضرع إلى الله في سجوده، وفي آخر التحيات، بين الأذان والإقامة، في آخر الليل، في جميع الأوقات، يدعو ربه، يسأله ويضرع إليه أن الله يشفيه مما أصابه، ويزيل عنه ما به من أذى، والله يحب السائلين جل وعلا، وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7487/حكم-الذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23705.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9466,"question":"للأخت من العراق سؤال ثان في هذه الرسالة تقول فيه: هناك بعض الاعتقادات عند بعض الناس لإفساد السحر وإبطاله، وهي عبارة عن أخذ شيء من الرصاص المذاب على النار، وسكبه في إناء فيه ماء، ثم يوضع على رأس المسحور وتعاد العملية ثلاث مرات في اليوم، فهل هذا له أصل؟ وما حكم الشرع فيه؟","title":"حكم إبطال السحر بإذابة الرصاص وجعله مع الماء على الرأس","answer":"الجواب: هذا شيء لا أصل له، ولا فائدة فيه، وهو تلبيس وتخييل، وإلا فهذا لا فائدة فيه، إذابة الرصاص وجعله على الرأس، وجعله في الماء ثم جعله.. كل هذا يفعله الكاهنات، ويفعله الملبسون والمشعوذون تلبيساً، وإلا فهم يعملون في خدمة الجن، وخدمة الشياطين، فلا يجوز الحل بهذا الشيء، وإنما يحل السحر بما شرع الله من الأدوية الشرعية، والقراءة، هذا هو الطريق في حل السحر، فإذا أصيب الإنسان بالسحر، أو حبس عن زوجته عولج بالقراءة، يقرأ عليه الرجل الطيب المعروف بالخير، وإن كانت امرأة قرأت عليها المرأة الطيبة بالخير، المعروفة بالخير، آيات من القرآن، بفاتحة الكتاب، آية الكرسي، آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس وفي سورة طه مع قراءة: قل يا أيها الكافرون، وقل هو الله أحد والمعوذتين، ثم يشرب منه ما تيسر ثم يتروش بالباقي، فإنه بإذن الله يزول عنه السحر، وهكذا يزول عنه الحبس الذي جرى عليه حين حبس عن زوجته، وإذا كرر ذلك مرتين أو ثلاث أو أكثر فلا بأس، حتى يزول عنه الأذى، وإذا جعل فيه سبع ورقات من سدر كان هذا أيضاً طيباً، فقد استعمل هذا وذكره المتقدمون وينفع بإذن الله، والسدر شيء طاهر لا بأس به، فإذا دق وجعل في الماء مع القراءة فيه كان هذا من أسباب الشفاء، وإذا أضاف إلى ذلك الدعاء المعروف الثابت عن النبي ﷺ: اللهم رب الناس، أذهب الباس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nإذا دعا بهذا الدعاء ثلاث مرات كان حسناً ينفث به في الماء، وهكذا: باسم الله أرقيه من كل شيء يؤذيه، من شر كل نفس أو عين حاسد، الله يشفيه باسم الله أرقيه ثلاث مرات، يكرر هذا: باسم الله أرقيه يعني: المريض، أو باسم الله أرقيك يخاطبه من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك، يكررها ثلاث مرات، هذا أيضاً من الدعوات المناسبة لهذا العلاج، وآيات السحر معروفة، في الأعراف قوله : وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ[الأعراف:117-119] .\nوفي يونس يقول : وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:79-82]، وفي طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69]، ثم يقرأ: قل يا أيها الكافرون، قل هو الله أحد ثلاث مرات، قل أعوذ برب الفلق ثلاث مرات، قل أعوذ برب الناس ثلاث مرات، فهذا هو الدواء الشرعي، والعلاج الشرعي الذي قد وصفه أهل العلم وجربه أهل العلم وجربناه أيضاً فنفع الله به، فهو دواء طيب بآيات الله، وإذا جعل فيه ما تقدم من ورقات السدر السبع ودقت هذا كله طيب أيضاً.\nوإذا عرف دواء آخر لا محذور فيه، دواء آخر بأوراق، أو بحبوب أو بإبر فلا بأس، إذا كان سليماً مما حرم الله من نجاسة أو غيرها، أما التداوي بما يتعاطاه خدام الجن، والمشعوذون من الرصاص وغيره أو بالذبح للجن، أو بالاستجارة بالجن فهذا كله ما يجوز منكر، وبعضه شرك.. الاستجارة بالجن ودعاؤهم، والاستغاثة بهم والذبح لهم كل هذا من الشرك الأكبر، نسأل الله العافية، فيجب الحذر ويجب على من بلي بهذا الشيء أن يحذر ما حرم الله وأن يتعاطى ما أباح الله.. لا بأس، يشرع له التداوي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7628/حكم-ابطال-السحر-باذابة-الرصاص-وجعله-مع-الماء-على-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24006.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9543,"question":"تسأل الأخت أيضاً وتقول: يوجد في مدينتا بعض الناس يستفتحون بالسلة، وهذه الطريقة هي أنهم يأتون بسلة طاهرة ويضعون بداخلها قرآناً ويغلقون فتحتها بسجادة الصلاة، ويضعون فوق السجادة مفتاح ويضعون على جانب السلة قلم وتحتها ورقة، ويأتي شخصان ويحملان السلة ويحركانها، وآخر يقرأ سورة الجن وعندما يقرؤها تأتي روح ميت، ويسألونها بعض الأسئلة وتجيب بواسطة القلم والورقة، والأسئلة التي في علم الغيب تقول: الله أعلم، والأسئلة التي لا تستطيع أن تجيب عليها كتابة بواسطة الورقة والقلم تقول فيها أيضاً: الله أعلم، المهم: هل هذه فعلاً روح ميت أم أنها جني وما الحكم في مثل هذا العمل؟","title":"التحذير من عمل الكهان والعرافين","answer":"الجواب: هذا عمل منكر ولا يجوز وهو من الكهانة المحرمة، فلا يجوز فعل هذا بالكلية، وهذا العمل من أعمال الشياطين وليس من أرواح الموتى ولكنه من أعمال الشياطين التي بها يلبسون على الناس ويأخذون أموالهم بالباطل، هذا العمل لا يجوز بل هو منكر ومن أعمال الكهانة، والواجب على ولاة الأمور منع هذا وتأديب من فعله حتى لا يعود إلى مثله، ولا يجوز للمسلم أن يشارك في هذا ولا أن يسألهم عن شيء، نعم لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ، هذا من جنس العرافين والكهنة، وهذه الأرواح التي تطلب هي من أرواح الجن والشياطين وليست أرواح الموتى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7712/التحذير-من-عمل-الكهان-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9546,"question":"تسأل الأخت أيضاً وتقول: يوجد في مدينتا بعض الناس يستفتحون بالسلة، وهذه الطريقة هي أنهم يأتون بسلة طاهرة ويضعون بداخلها قرآناً ويغلقون فتحتها بسجادة الصلاة، ويضعون فوق السجادة مفتاح ويضعون على جانب السلة قلم وتحتها ورقة، ويأتي شخصان ويحملان السلة ويحركانها، وآخر يقرأ سورة الجن وعندما يقرؤها تأتي روح ميت، ويسألونها بعض الأسئلة وتجيب بواسطة القلم والورقة، والأسئلة التي في علم الغيب تقول: الله أعلم، والأسئلة التي لا تستطيع أن تجيب عليها كتابة بواسطة الورقة والقلم تقول فيها أيضاً: الله أعلم، المهم: هل هذه فعلاً روح ميت أم أنها جني وما الحكم في مثل هذا العمل؟","title":"التحذير من عمل الكهان والعرافين","answer":"الجواب: هذا عمل منكر ولا يجوز وهو من الكهانة المحرمة، فلا يجوز فعل هذا بالكلية، وهذا العمل من أعمال الشياطين وليس من أرواح الموتى ولكنه من أعمال الشياطين التي بها يلبسون على الناس ويأخذون أموالهم بالباطل، هذا العمل لا يجوز بل هو منكر ومن أعمال الكهانة، والواجب على ولاة الأمور منع هذا وتأديب من فعله حتى لا يعود إلى مثله، ولا يجوز للمسلم أن يشارك في هذا ولا أن يسألهم عن شيء، نعم لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ، هذا من جنس العرافين والكهنة، وهذه الأرواح التي تطلب هي من أرواح الجن والشياطين وليست أرواح الموتى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7712/التحذير-من-عمل-الكهان-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9696,"question":"هذه رسالة وردت إلى البرنامج من الجمهورية الجزائرية، جنوب الجزائر قرية تماسين من السائلة (ب. س) تقول في رسالتها: هناك بنت مشلولة في يديها ورجليها، وعجز الأطباء عن علاجها، وسمع أهلها برجل يعالج بطريقة خاصة، حيث أنهم يضعون الكمون تحت رأسها وفي الصباح يأخذونها إلى الرجل ومعهم هذا الكمون فيقول لهم: بأنها بها مس من الجنون، فطلب منهم أن يأتوه بجدي، فأخذوا له الجدي فبدأ الرجل يسن السكين فصار الجدي مشلولاً مثل الطفلة، وبعد ذلك قطع شيئاً من أذن الجدي ومسح بها عند أنف الطفلة ووراء أذنيها، وأمر الجدي بالذهاب فقام مسرعاً وقال لهم: ابنتكم بخير إن شاء الله، فقامت الطفلة كأن لم يكن بها شلل، وبعد ذلك كتب لها بعض الأدوية من الحشائش لتتابع العلاج في البيت، لكي تشفى تماماً، وقبل أن يبدأ في مخاطبتهم، يبدأ باسم الله، ويقرأ آية الكرسي، ثم يأخذ هذا الكمون وينظر فيه ويبدأ يقول: ويصف حالة المريض ما به ومتى وكيف، أرجو أن تدرسوا هذه القضية وتفيدونا برأيكم في هذا، وإذا كانت الإجابة بمنع مثل هذا العمل فما الدليل، علماً بأن أهل هذه الطفلة سألوني عن الجواب فلم أستطع أن أجبهم وكتبت إليكم أفيدونا أفادكم الله؟","title":"حكم الذهاب بالمرضى إلى الكهان والمشعوذين","answer":"الجواب: هذا العمل يدل على أن الرجل كاهن يستخدم الجن ويتقرب إليهم بما يريدون، وأما جعله الكمون تحت الرأس، وقطع أذن الجدي وما أشبهه هذا تلبيس، حتى لا يكشف أمره، وإنما هو رجل مستخدم للجن، وقد يكون بعض الجن مس المرأة بشيء حتى حصل لها ما حصل، ثم اتفق معهم على أن يتركها فتركها فحصل الشفاء، وليس في الحقيقة من جهة قراءته وإنما يلبس على الناس بقراءة آية الكرسي أو بقوله: باسم الله عند إعطائهم الكمون كل هذا تلبيس.\nوالواجب عدم الذهاب إلى هذا الرجل وأشباهه؛ لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ رواه أهل السنن؛ ولقوله ﷺ في الكهان: لا تأتوهم وهذا منهم، فإن عمله هذا يدل على أنه يستخدم الجن ويسألهم ويتفق معهم على ما يريدون، ويعطونه ما أراد حتى يعبدهم من دون الله، ويعطيهم ما يريدون حتى يخدموه فلا يجوز سؤال هذا، ولا يجوز أخذ علاجه، ولا الذهاب إليه بالكلية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7866/حكم-الذهاب-بالمرضى-الى-الكهان-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25307.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9773,"question":"أولى الرسائل وردت من المستمعة مهدية بنت صدام من العراق، تقول في رسالتها: ما هو العمل لإبطال السحر بارك الله فيكم؟","title":"الوسائل الشرعية لإبطال السحر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفعلاج السحر يكون بشيئين:\nأحدهما: الرقى الشرعية.\nوالثاني: الأدوية المباحة التي جربت في علاجه.\nومن أنجع العلاج وأنفع العلاج الرقى الشرعية، فقد ثبت أن الرقية يرفع الله بها السحر، ويبطل بها السحر.\nوهناك نوع ثالث وهو: العثور على ما فعله الساحر من عقد أو غيرها وإتلافها، كذلك من أسباب من زوال السحر وإبطاله.\nفمن الرقى التي تستعمل أن يرقى المسحور بفاتحة الكتاب وآية الكرسي، وقل يا أيها الكافرون، قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، مع آيات السحر التي جاءت في سورة الأعراف وسورة يونس وسورة طه.\nوهي في سورة الأعراف قوله سبحانه: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف:117-119].\nوفي سورة يونس يقول سبحانه: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:79-82].\nوفي سورة طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69].\nفهذه الآيات الكريمات العظيمات ينفث بها في الماء، ثم بعد ذلك يصب هذا الماء الذي قرئ فيه على ماء أكثر، ثم يتروش به المسحور، ويشرب منه بعض الشيء كثلاث حسوات يشربها منه، ويزول السحر بإذن الله ويبطل، ويعافى من أصيب بذلك، وهذا مجرب مع المسحورين، جربناه نحن وغيرنا ونفع الله به من أصابه شيء من ذلك.\nوقد يوضع في الماء سبع ورقات من السدر تدق وتلقى في الماء الذي يقرأ فيه أيضاً ولا بأس، قد ينفع الله بذلك أيضاً، سبع ورق سدر وهي شجر النبق، تدق وهي خضر رطبة تدق ثم توضع في الماء الذي يقرأ فيه، ويشرب منه ما تيسر ويغتسل بالباقي المسحور.\nهذا من الدواء النافع والرقية النافعة.\nوهناك أدوية لمن يتعاطى هذا الشيء.. ويعالج بهذا الشيء أدوية مباحة قد يستفاد منها في علاج السحر وإزالته، كما أشار إلى هذا العلامة ابن القيم رحمه الله في بيان النشرة المشروعة، وقد ذكر ذلك أيضاًَ الشيخ عبد الرحمن بن حسن آل الشيخ في كتابه فتح المجيد في شرح كتاب التوحيد في باب ما جاء في النشرة.\nأما ما يتعلق بإتيان الكهان أو السحرة أو المشعوذين هذا لا يجوز، وإنما الطريق الشرعي هو ما ذكرنا من القراءة على المسحور، أو القراءة في ماء ويشربه ويتروش منه، وإن وضع فيه سبع ورقات من السدر الأخضر الرطبة ودقت فهذا أيضاً قد ينفع بإذن الله مع القراءة، وهذا شيء مجرب.\nوالغالب على من استعمل هذا مع إخلاصه لله وتوجهه إلى الله في طلب الشفاء أنه يعافى بإذن الله، وعلى المسحور أن يضرع إلى الله وأن يسأله كثيراً أن يشفيه ويعافيه، وأن يصدق في طلبه، وأن يعلم أن ربه هو الذي يشفي، وهو الذي بيده الضر والنفع، والعطاء والمنع، ليس بيد غيره سبحانه وتعالى. نعم.\nالمقدم: بارك الله فيكم، ما أدري رأي سماحتكم في مقولة يتناقلها كثير ممن يرتادون أماكن السحرة يقولون: لا يحل السحر إلا ساحر، وبعضهم يقول: أذهب إلى الساحر ليدلني على مكان العقد حتى أحلها بعد ذلك؟\nالجواب: السحرة والكهنة لا يؤتون، النبي ﷺ نهى عن إتيانهم وعن سؤالهم قال: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً وقال: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام.\nوالسحرة كفرة، لا يجوز إتيانهم ولا سؤالهم.\nوأما هذه العبارة: لا يحل السحر إلا ساحر، فهذا يروى عن الحسن البصري التابعي الجليل أنه قال: لا يحل السحر إلا ساحر، والنبي ﷺ سئل عن هذا، النبي ﷺ سئل عن النشرة يعني: حل السحر عن المسحور، قال: هي من عمل الشيطان يعني: الذي يتعاطى حله بالسحر، قال ﷺ: هي من عمل الشيطان يعني: النشرة بالسحر وأنواعه، هذا هو من عمل الشيطان، رواه الإمام أحمد رحمه الله وأبو داود رحمه الله بإسناد جيد، وهو موجود في باب النشرة هذا الحديث.\nفالمقصود: أن حل السحر بالنشرة الشيطانية التي يتعاطاها السحرة هذا مثل ما قال النبي ﷺ: هي من عمل الشيطان هكذا قاله المصطفى عليه الصلاة والسلام: هي من عمل الشيطان فلا يجوز حلها بطريق السحرة، يعني لا يجوز حل السحر بطريق السحرة وذلك يسمى النشرة، ولكن يحل بطريق القراءة والأدوية المباحة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7940/الوساىل-الشرعية-لابطال-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25801.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10116,"question":"ما رأي الدين الإسلامي في الأساليب والطرق السحرية التي تنتشر في بعض الكتب في المكتبات والتي تغري كل شاب بقراءتها والعمل بما فيها، وخصوصًا أن هناك حديثًا شريفًا يقول: تعلموا السحر ولا تعملوا به، فكيف يمكن تعلم السحر وعدم العمل به؟ أرجو الإجابة عن هذا الاستفسار؟ جزاكم الله خيرًا.","title":"حكم تعلم السحر والواجب تجاه كتب السحر","answer":"الجواب: الكتب التي تعلم السحر يجب إتلافها والقضاء عليها ولا يجوز تعلمها ولا العمل بما فيها، وهذا الحديث الذي ذكره السائل لا أصل له بل هو حديث غير صحيح تعلموا السحر ولا تعملوا به هذا باطل ما له أصل، هذا الحديث الذي ذكره السائل ليس له أصل، والذي عليه أهل العلم أنه لا يجوز تعلم السحر ولا العمل به، بل يجب الحذر من ذلك؛ لأن تعلمه وتعليمه كفر لأنه لا يتوصل إلا بعبادة الشياطين من دون الله والاستغاثة بالجن ونحو ذلك، والله ذكر عن الملكين في سورة البقرة قال سبحانه: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُر [البقرة:102]، فبين أن تعلمه كفر، وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُر [البقرة:102]، فدل ذلك على أن تعلم السحر من أمور الكفر، فالواجب على كل مسلم أن يحذر ذلك وألا يتعلم الكفر والسحر وألا يذهب إلى السحرة والكهنة والمنجمين، ولا يجوز له سؤالهم ولا تصديقهم؛ لقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة رواه مسلم في الصحيح، وإن لم يصدقه من أتى عرافًا فسأله عن شيء ولم يقل: فصدقه، فدل ذلك على أن سؤاله لا يجوز، وتصديقه أكبر في الإثم، فلا يسأله ولا يصدقه، وقال أيضًا عليه الصلاة والسلام: من أتى كاهنًا أو عرافًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، فلا يجوز إتيان الكهان وهم الذين يدعون علم الغيب، ولا العرافون الذين يدعون علم الغيب من مقدمات يدعونها وأشياء يدعونها، كل هذا باطل، فلا يجوز سؤالهم ولا يجوز تصديقهم، ولا يجوز شراء الكتب التي فيها علومهم، بل يجب إتلافها وإحراقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8287/حكم-تعلم-السحر-والواجب-تجاه-كتب-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33405.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10203,"question":"هل صحيح أن من بخر منزله باللبان الشهري يذهب الشياطين من المنزل؟ وهل يوجد دليل على ذلك؟ لأن كثيرًا ممن حولنا يبخرون منازلهم عند الغروب اعتقادًا منهم أنه يذهب الشياطين وأنا لست مقتنعًا بعملهم هذا.","title":"حكم استخدام البخور لطرد الشياطين","answer":"الجواب: هذا شيء لا أصل له، وإنما يذهب الشياطين ذكر الله والتعوذ بكلمات الله التامات من شر ما خلق، هكذا أخبر النبي ﷺ، يقول ﷺ: من نزل منزلًا فقال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله ذلك، وقال: إذا دخل الإنسان منزله مساءً وقال: باسم الله، قال الشيطان: لا مبيت، وإذا سمى عند الأكل قال: لا مبيت ولا عشاء، فالتسمية بالله والتعوذ بكلمات الله التامات من شر ما خلق هذه من أسباب الحفظ من الشياطين، وهكذا قراءة القرآن كل ذلك من أسباب السلامة، فينبغي للمؤمن أن يفعل ما شرعه الله من التعوذ بكلمات الله التامات من شر ما خلق، ومن التسمية عند الدخول يقول: باسم الله عند دخول المنزل، والتسمية عند الأكل وعند الشرب، هكذا السنة، وإذا كرر: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات كان أولى وأفضل، كذلك يقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء هذا من أسباب السلامة من كل شر، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء، وهكذا: أعوذ بكلمات الله التامات من شر ما خلق، إذا قالها لم يضره شيء حتى يرتحل من منزله ذلك، وإن كرر ثلاث مرات أولى وأكمل كما جاء في بعض الروايات عن النبي ﷺ.\nفالحاصل أن هذه التعوذات وهذه الأذكار هي التي يقي الله بها العبد من شر الشياطين، ومن كل ما يضره، أما البخور الذي ذكره السائل فلا أصل له.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8367/حكم-استخدام-البخور-لطرد-الشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33412.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10360,"question":"من المستمع حسين العميري من سوريا رسالة وضمنها سؤالين، في أحد أسئلته يقول: يوجد أشخاص يقال لهم: عرافون، ويدعون أنهم يعرفون علم الغيب، ما حكم الدين في ذلك، وهل يمكن تصديقهم؟","title":"حكم الذهاب إلى الكهنة والعرافين وتصديقهم","answer":"الجواب: العرافون والكهنة والسحرة لا يجوز تصديقهم ولا سؤالهم ولا إتيانهم، بل يجب الحذر منهم والإنكار عليهم، ويجب على ولاة الأمر من المسلمين تتبعهم وعقابهم بما يردعهم وأمثالهم، وإذا ادعوا علم الغيب يستتابون فإن تابوا وإلا قتلهم ولي الأمر. فإن دعوى علم الغيب كفر أكبر، وقد قال النبي ﷺ: من أتى عرافًأ فسأله عن شيء، لم تقبل له صلاة أربعين يوما، هذا سؤال مجرد سؤال من غير تصديق فكيف إذا صدقه؟ من أتى عرافًأ فسأله عن شيء لم تقبل له صلاة أربعين ليلة، هكذا جاء في صحيح مسلم أربعين ليلة.\nفإذا صدقه صار الإثم أعظم، وقال عليه الصلاة والسلام: من أتى عرافًأ أو كاهنًأ فصدقه بما يقول: فقد كفر بما أنزل على محمد ﷺ، فإذا صدقه في علم الغيب كفر مثله، فالذي يدعي علم الغيب أو يصدق من يدعي علم الغيب يكفر كفرًأ أكبر نعوذ بالله، يستتاب فإن تاب وإلا قتل، يجب أن يستتيبه ولي الأمر السلطان أو نائبه من القضاة فإن تاب وإلا قتل كافرًأ نسأل الله العافية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8528/حكم-الذهاب-الى-الكهنة-والعرافين-وتصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33811.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10361,"question":"من المعلوم أن الجن والإنس من مخلوقات الله تعالى، وأمرهم بالعبادة في قوله تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، سؤالي: هل الجن يؤذون الإنس وكيف وبأي طريقة، وما أعراض الشخص المصاب، وكيف الشفاء إذا وقع؟","title":"أذية الجني للإنسي، وطرق الوقاية من ذلك","answer":"الجواب: الجن ثقل عظيم خلقهم الله لعبادته، وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، والصحيح: أنهم أولاد إبليس يقال لهم: الجن، فهو أبوهم كما أن آدم هو أبو الإنس، وهم فيهم الكافر وفيهم المسلم، وفيهم العاصي، مثل بني آدم ، فيهم الطيب والخبيث، والله كلفهم بعبادته وطاعته، وفرض عليهم فرائض، فالواجب عليهم أن يسمعوا ويطيعوا، وأن ينقادوا لأمر الله، وأن يعظموا حرماته.\nوهم أصناف وأشكال يأكلون ويشربون، وينكحون ويتناسلون، وهم أصناف وأشكال، وقد يؤذون بني آدم كما يؤذي بنو آدم بعضهم بعضا، قد يؤذي الجن الإنس في بعض الأحيان بالحجارة، أو بشب النار في بعض أمتعتهم، أو بالكلام المزعج أو بغير ذلك، وقد يؤذون أيضًأ بتلبس الجني بالإنسي، والغالب يكون هذا بأسباب من الإنس، إما بطرح شيء ثقيل ولم يسم، أو صب ماء حار ولم يسم، أو ما أشبه ذلك، مما قد يؤذيهم هم، فيتسلطون بسبب الأذى الذي حصل من الإنسي فيتلبس به الجني، ولكن متى قرأ عليه من آيات الله العزيز من آيات الله جل وعلا الكريمة وطولب بالخروج وخوف من الله سبحانه وتعالى، وقرأ عليه من لديه قوة في دين الله وإيمان قوي، فإنه يخرج إذا كان فيه دين إذا كان فيه خير يخرج ويتعظ ويتذكر، وقد لا يخرج إذا كان فاسقًأ أو كافرًأ مثل فسقة الإنس قد يظلمون ويتعدون ولا يبالون بالنصيحة لكفرهم أو فسقهم، فهم كالإنس فيهم الفاسق وفيهم الكافر وفيهم الظالم وفيهم الطيب وفيهم الخبيث، والله شرع لنا أن نتقي شرهم بالتعوذات، الإنسان مشروع له صباحًأ ومساءً أن يقول: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء، كل هذا من أسباب السلامة من الجن وغيرهم.\nكذلك قراءة آية الكرسي بعد كل صلاة، وقراءتها عند النوم، من أسباب حفظ الله له من الشياطين، وهكذا قراءة قل هو الله أحد والمعوذتين بعد كل صلاة، وقراءتها ثلاث مرات بعد المغرب والفجر، كل هذا من أسباب السلامة من شياطين الإنس والجن.\nوالمؤمن ينبغي له أن يكون بعيدًأ عن أسباب الأذى للإنس والجن جميعًأ، ومن كان معتصمًأ بالله آخذًأ بالأسباب الشرعية وقاه الله شر الإنس والجن جميعًأ، ومن تساهل فقد يسلط عليه الإنس والجن بسبب تساهله أو عدوانه أو ظلمه، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8531/اذية-الجني-للانسي-وطرق-الوقاية-من-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33812.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10467,"question":"له سؤال طويل ملخصه: أن له أخت كانت مع رجل وطلقها بسبب والدته، ثم إنها بعد الطلاق أصيبت بحالة مرضية، أرغمه والده ووالدته على الذهاب بها إلى أحد الأشخاص يعتقد أنه مشعوذ، ومنذ ذلك الوقت وهو يفكر في أمره، ويرجو من سماحتكم توجيهه كيف يتصرف، وهل يكون قد وقع في الإثم، جزاكم الله خيراً؟الشيخ: أعد. الله المستعان.المقدم: يقول: إن له أخت كانت متزوجة من أحد الأشخاص، ثم إنه طلقها بسبب والدته، وبعد الطلاق أصيبت أخته بحالة مرضية، اضطر معها بسبب والده ووالدته إلى الذهاب بها عند أحد الأشخاص يعتقد أنه مشعوذ، وحينئذ أصيب بالقلق وأصبح يفكر هل قمت بعمل محرم كالشرك، ويرجو توجيهكم جزاكم الله خيراً؟","title":"حكم الذهاب إلى المشعوذين طاعة للوالدين","answer":"الجواب: نعم لا يجوز له ذلك، ليس له طاعة والديه فيما حرم الله، والذهاب بأخته إلى المشعوذ لا يجوز؛ لأن الرسول ﷺ نهى عن إتيان الكهان وعن سؤالهم، والمشعوذون هم العرافون والمنجمون والكهنة، فلا يجوز إتيانهم ولا سؤالهم، وإذا أمره بذلك والده لم يجز له طاعته؛ لأن الرسول عليه السلام قال: إنما الطاعة في المعروف وقال عليه الصلاة والسلام: لا طاعة لمخلوق في معصية الخالق.\nفيعتذر ويقول: يا والدي هذا ما يجوز، لكن نذهب بها إلى من يقرأ عليها من الطيبين امرأة صالحة تقرأ عليها، رجل صالح يقرأ عليها بدون خلوة، إلى الطبيب أما إلى المشعوذين من كهنة ومنجمين وسحرة ونحو ذلك هذا لا يجوز، فإنه لا يجوز إتيانهم ولا سؤالهم ولا العلاج عندهم بالكلية، بل يجب على ولي الأمر أن يمنعهم من ذلك وأن يؤدبهم، حتى يرتدعوا عن تعاطي العلاج. نعم.\nالمقدم: جزاكم الله خيراً، أما الحال وقد وقعت فبم توجهونه جزاكم الله ...؟\nالشيخ: ... التوبة إلى الله والندم، والعزم أن لا يعود في هذا الشيء. نعم.\nالمقدم: وحينئذٍ يكون إن شاء الله تعالى ..\nالشيخ: لأن التوبة تجب ما قبلها، إذا صدقت التوبة بالندم على الماضي والإقلاع من الذنب والعزم الصادق أن لا يعود فيه فإن الله يغفر له سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيرا، هو قلقه من كونه قد وقع منه هذا الشيء.\nالشيخ: إن شاء الله يرجى له الخير في هذا، نعم الإنسان إذا قلق من أجل خوف الله والرغبة فيما عنده فهو على خير عظيم، الله المستعان.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8642/حكم-الذهاب-الى-المشعوذين-طاعة-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32008.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10485,"question":"أختنا تقول: يوجد امرأة تقوم بنثر الودع أمامها وتخبر أنه سوف يحدث كذا وكذا من الأمور الغيبية، ولكنها لا تقول: إنها تعلم الغيب، لكن تقول: إنما تفعله مجرد تسلية، وأن ما تقوله قد يحدث وقد لا يحدث ما حكم ذلك؟","title":"حكم نثر الودع والإخبار عن المغيبات","answer":"الجواب: لا يجوز لها هذا العمل، هذا من عمل أهل السحر والشعوذة، لا يجوز هذا بل يجب الإنكار عليها ومنعها من هذا العمل، وإخبارها أن هذا لا يجوز، وأن هذا يفضي إلى دعواها علم الغيب، والتلبيس على الناس، هذا لا يجوز، فالواجب على هذه المرأة أن تخاف الله وأن تراقب الله، وتحذر هذا العمل السيئ الذي أنكره النبي ﷺ وحذر منه، يقول ﷺ: من علق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، فالواجب الحذر من هذا العمل السيئ، وهو وسيلة إلى دعوى علم الغيب، ووسيلة إلى التلبيس على الناس، نسأل الله للجميع العافية والهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8660/حكم-نثر-الودع-والاخبار-عن-المغيبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28112.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":11475,"question":"يقول: هناك بعض المشايخ -كما سماهم- يضربون أجسامهم بالسكاكين والخناجر والسيوف، وبعضهم يحاد الآخر أحيانًا متوسلًا كل واحد منهم بشيخه، فما حكم الشرع في هذا العمل؟ جزاكم الله خيرًا.","title":"حكم من يضربون أجسادهم بالخناجر والسيوف ويدعونها كرامة","answer":"الجواب:  هذا عمل الصوفية يدعون أنهم لا يضرون أنفسهم، وأن هذا من كراماتهم، وهو باطل، إنما هو تلبيس، ولا حقيقة لذلك، إنما هو تلبيس وتقليب على العيون كونه ضربه بالسيف، أو كسر رأسه، أو كسر رجله، كله تلبيس، لا حقيقة له، وهم بهذا كفار؛ لأنهم يسحرون الناس، كما قال الله عن سحرة فرعون: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، قال: سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ [الأعراف:116]، فهؤلاء المقدمون الذين يلبسون على الناس هم كفرة بذلك، سحرة مجرمون، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9659/حكم-من-يضربون-اجسادهم-بالخناجر-والسيوف-ويدعونها-كرامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38205.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":11959,"question":"يقول: في قريتنا رجل يحفظ القرآن الكريم كاملًا، ويؤم الناس في الصلاة، ولكنه يعمل بعض أعمال السحر، ويقول: إنها أعمال حب فقط، أي: جمع بين اثنين، فهل تحل الصلاة وراءه؟ وإن لم يكن فهل ننصرف عنه إلى مسجد آخر؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يتعاطى السحر","answer":"الجواب:  إذا عرف أنه يتعاطى السحر؛ يجب أن يرفع أمره إلى المحكمة حتى يستتاب، حتى تحكم المحكمة بما يقتضيه الشرع المطهر، والصواب أيضًا أنه لا يستتاب، بل يقتل، ولا يصلى خلفه، فالساحر كافر إذا ثبت السحر عند المحكمة، والمحكمة أعلم بهذا، فارفعوا أمره إلى المحكمة، ولا تصلوا خلفه، واطلبوا من المسؤولين في الأوقاف أن يعينوا بدلًا منه من أهل الخير، ولا يجوز لكم الصلاة خلفه، ولا تركه، بل يجب الرفع عنه إلى المحكمة، حتى تعمل ما يلزم من جهة إثبات سحره، والحكم عليه بما يقتضيه الحكم الشرعي، نسأل الله السلامة والعافية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/10144/حكم-الصلاة-خلف-من-يتعاطى-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42823.mp3","categories":["صلاة الجماعة","السحر والكهانة"]},{"id":12087,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة حطة (ع. س. ف) من حوطة سدير، أختنا رسالتها مطولة بعض الشيء، وملخص ما في سؤالها الأول سماحة الشيخ  عن السحر وأهل السحر، إذ أنهم يعانون كثيرًا من هذا الأمر كما تقول، ولاسيما وأنها تقول: لقد اكتشفنا أن إحدى أخواتي قد أصيبت بالسحر بعد أن تعطلت خطبتها، واضطرت للبحث عن علاج لهذا الموضوع، فأفادتها إحدى النساء بأنك مسحورة وأن مكان السحر تحت عتبة الباب، وتسأل سماحتكم كيف يتقى شر هؤلاء؟ جزاكم الله خيرًا.","title":"أنواع السحر وطرق الوقاية منه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دل القرآن الكريم وهو كلام الله -عز وجل- على أن السحر موجود، وبعضه تخييل، وبعضه له حقيقة وأثر، ومن هذا قوله سبحانه في قصة موسى مع السحرة: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، ومنها قوله -جل وعلا- في سورة البقرة: وَاتَّبَعُوا مَا تَتْلُواا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتََ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102]. فالسحر حقيقة، لكن بعضه تخييل وتلبيس، ولا حقيقة له واقعية، كما جرى من السحرة فيما فعلوا من التخييل بالحبال والعصي، ويقع بعضه مؤثراً كما ذكرنا في سورة البقرة، أن السحرة يتعلمون منهما... الملكين : مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102].  لكن بإذن الله، ولهذا قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102]، أي: بإذن الله الكوني القدري، فهذا يدل على أنه قد يقع منه ضرر، وقد يحصل منه، بسببه تفريق بين الرجل وزوجته، ولكن كثير من الناس قد يتوهموا هذا الشيء، ويظنوا أنه سحر، وليس بسحر، ولكنها أوهام ووساوس. والمشروع في مثل هذا توقي السحر بالتعوذات الشرعية، والأذكار الشرعية التي جعلها الله واقية منه. فالمشروع للمؤمن والمؤمنة توقي ذلك بالأسباب الشرعية، ومنها: قراءة آية الكرسي بعد كل صلاة وعند النوم، ومنها قراءة قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، بعد كل صلاة، وبعد الفجر والمغرب ثلاث مرات، وعند النوم ثلاث مرات، كل هذا من أسباب الوقاية من السحر ومن شر الشيطان. ومن ذلك أيضًا: التعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساءً ثلاث مرات، أعوذ بكلمات الله التامات من شر ما خلق، ومن ذلك: ما جاء عن النبي ﷺ في الحديث الصحيح، وهو أن يقول صباحًا ومساءً: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات، إذا قالها لم يضره شيء : باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباحًا وثلاث مرات مساءً، ثبت عنه ﷺ من حديث عمر : أن من قالها ثلاثًا صباحًا لم يضره شيء حتى يمسي، وإن قالها مساءً لم يضره شيء حتى يصبح. من ذلك: أخذ ورقات سدر أخضر، سبع ورقات تدق وتجعل في ماءـ ويقرأ فيها آية الكرسي، وقل يا أيها الكافرون، وقل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، وإذا قرأ الفاتحة أيضًا؛ فحسن؛ لأن الفاتحة أم القرآن، ولها شأن عظيم، وهي أفضل السور، ويقرأ في الإناء أيضًا آيات السحر سواءً في الأعراف، أو من سورة طه وسورة يونس. في الأعراف يقول -جل وعلا-: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ  ۝  فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ  ۝  فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف: 117- 119]. وفي سورة يونس يقول سبحانه: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ  ۝  فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ* فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ  ۝  وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس: 79-82]. ومن سورة طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69]. \nوينفث أيضاً في الماء: رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاءً لا يغادر سقمًا ثلاث مرات، اللهم رب الناس أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا يعني: لا يترك سقمًا، ويقول أيضًا: باسم الله أرقيك، من كل شيء يؤذيك، من شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك، يسمي باسم الله أرقي فلانًا، أو صاحب هذا الماء الذي ...، باسم الله أرقيك من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد الله يشفيك باسم الله أرقيك يقول ثلاث مرات، كل هذا حسن، وإذا قال أيضًا: أعيذه بكلمات الله التامات من شر ما خلق ثلاث مرات فحسن. ثم يشرب من هذا الماء حسوات، ويتروش بالباقي، يصب عليه ماء يكفي للتروش، ويتروش بالباقي، والغالب بإذن الله أنه يزول الأثر إن كان هناك سحر حقيقي، يزول بإذن الله، وهكذا المحبوس عن زوجته ينفع هذا العلاج أيضًا، يتروش به، يشرب منه ثلاث حسوات، ويتروش بالباقي، فإن زال الأثر، وحصلت العافية؛ فالحمد لله، وإلا يشرع له أن يعيد المسألة مرتين أو ثلاثًا، أو أكثر حتى يزول الأثر من سحر، أو حبس عن الزوجة، والغالب أنه يزول بالمرة الأولى، وقد يحتاج إلى مرة ثانية، أو ثالثة، والحمد لله، فالعلاج بحمد الله ميسر. فأنا أنصح بهذا العلاج من ظن أنه مسحور، أو أنه مصاب بعين أو محبوس عن زوجته، والله -جل وعلا- جعل هذا من أسباب الشفاء  وإذا قرأ نفسه، قرأ على نفسه آية الكرسي، وقل هو الله أحد، والمعوذتين، ومسح على رأسه وصدره ووجهه عند النوم؛ فهذا ينفع أيضًا، كان النبي ﷺ إذا اشتكى قرأ في كفيه قل هو الله أحد والمعوذتين ينفث في كفيه ثلاث مرات، يمسح في كل مرة على وجهه، وصدره ورأسه هذا ينفع بإذن الله، وإذا قرأ معها آية الكرسي؛ فهي أيضًا من أسباب الشفاء. كل هذه أدوية شرعية من أصيب بشيء مما يكره من مرض، أو حبس عن زوجة، أو ظن أنه مسحور، أو وجد بغضاء بينه وبين زوجته، فليستعمل هذا وهو عالم -بإذن الله- أن الله ينفعه بذلك، وليكن صادقًا في الرغبة فيما عند الله، يعلم أن الله على كل شيء قدير، وأنه سبحانه هو الشافي المعافي من كل سوء، وأنه متصرف في عباده كيف يشاء، فليحسن ظنه بربه، وليسأله سبحانه أن ينفع بالأسباب ويضرع إليه -جل وعلا- وهو القائل سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] فليضرع إلى الله صادقًا، وليسأله أن يشفيهن وأن يعافيه، وأن ينفع بهذه الأسباب، وهو سبحانه الجواد الكريم القائل : وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَاا دَعَانِ[البقرة:186] وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60].  نسأل أن يوفق المسلمين جميعًا لما في رضاه، وأن يشفي مريضهم من كل سوء، وأن يوفقهم لكل ما ينفعهم في الدين والدنيا، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10272/انواع-السحر-وطرق-الوقاية-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43601.mp3","categories":["الأدعية والأذكار","السحر والكهانة"]},{"id":12547,"question":"أحد الإخوة المستمعين من جمهورية مصر العربية، هو: محمد محمد علي فرغلي، بعث يقول: عندنا في مصر، في بعض القرى الريفية أناس يقومون بأعمال الطبل والمزمار، ويقولون: إننا نخرج الجن من الناس، ومن النساء، فما حكم ما يفعلون؟","title":"إخراج الجن بالطبل والمزمار","answer":"الجواب:  هذا من عمل بعض الصوفية، وهو منكر، غلط لا يجوز فعله، ولا يجوز تقليدهم، بل يجب الإنكار عليهم، يتعبدون بالطبل والمزامير والغناء، هذا منكر، وهذا من فعل بعض طوائف الصوفية، فأنت يا أخي! تنكر عليهم ذلك وإخوانك، تنكرون عليهم وتعلمونهم وترشدونهم أن هذا لا يجوز، وأن الواجب الاشتغال بما شرع الله من العبادة، من صلاة وقراءة وذكر، لا بالطبل والمزامير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10752/اخراج-الجن-بالطبل-والمزمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45615.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":12586,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين من السودان، يسأل عددًا من الأسئلة من بينها سؤال طويل مكتوب بلهجته العامية، عن أولئك المشعوذين أصحاب البخور، وأصحاب الإخبار بالمغيبات، ويرجو من سماحة الشيخ التوجيه بخصوصهم، جزاكم الله خيرًا.","title":"واجب المسلم تجاه المشعوذين والمخرفين وأهل الطرق البدعية","answer":"الجواب:  يجب على المسلم أن يحذر هؤلاء المخرفين الذين ينسبون إلى التصوف والشعوذة، إما بدعوى علم الغيب، أو بدعاوى أخرى يدعونها أنهم بينهم وبين شيوخهم صلة تمكنهم من أن يفعلوا كذا وكذا، فيشوشوا على الناس، ويوهموهم أنهم لهم قدرة على شفاء المرضى، أو قضاء الحاجات بالطرق غير الشرعية. فهؤلاء يجب الحذر منهم؛ لأنهم مخرفون، ودعاة باطل، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد ﷺ فهؤلاء الذين يدعون أمور الغيب، أو يدعون أن مشايخهم يرشدونهم إلى أشياء تتعلق بالغيب، وأن ما يقول مشايخهم صحيح، وأنهم معصومون، وأن أخبارهم لابد أن تقع وما أشبه، هذا مما يقع لبعض الصوفية، أو يعتقد أنه يأتيه الوحي من السماء، فيقول: حدثني قلبي عن ربي بكذا وكذا، فكل هذه خرافات، والذي يدعيها كافر، الذي يدعي أنه يعلم الغيب، أو أنه يأتيه الوحي من السماء بعد محمد ﷺ كل هذا كفر وضلال، وهكذا من يصدقهم في دعوى علم الغيب، من صدقهم؛ فهو مثلهم. وإذا جعل بخورًا، أو غيره من الأشياء التي يشوش بها، أو يلبس بها؛ فلا يلتفت إليه، العمدة على ما يقول، إذا كان يدعي علم الغيب، أو يدعي أنه يخدم الجن، وأن الجن هم الذين يخبرونه بالمغيبات، أو ما أشبه ذلك، هذا من الخرافيين، ومن المشعوذين؛ فيجب الحذر منهم، وعدم سؤالهم، وعدم تصديقهم، ومتى ظهر منه أنه يدعي علم الغيب، أو أنه يعبد الجن، ويخدمهم بالطاعات، والذبح لهم، والنذر لهم؛ صار بذلك مشركًا، إما بدعواه علم الغيب، وإما لكونه يعبد الجن، ويستغيث بهم، وينذر لهم، ونحو ذلك، وإذا زعم أنه يعرف الأشياء بالطرق الأخرى؛ فهو كذاب؟ لقصده التلبيس؛ لأنه لا يعلم المغيبات إلا الله . أما إذا كان يداوي المريض بالأدوية المعروفة الحسية، كما يفعل الأطباء المعروفون، يداوي بالكي، يداوي بأشياء يستعملها من مأكولات، أو مشروبات، أو مروخات جربت ونفعت، ولا يدعي علم الغيب، ولا يخدم الجن؛ هذا لا حرج عليه، هذا طب شعبي قد اعتاده الناس فيما بينهم، وقد يعتاد الناس أشياء يعرفونها فيما بينهم من أنواع من المأكولات، أو المشروبات، أو الدهونات، والمروخات، أو الكي؛ هذا لا بأس به إذا كان سليمًا ليس معه دعوى علم الغيب، وليس معه عبادته للجن، وقد كانت العرب وغالب الناس على هذا .... معهم فيما مضى، يعرفون عادات يفعلونها ويعالجون بها، ويتطببون بها، فقد تنفع، وقد لا تنفع، وليست من علم الغيب، ولا من خدمة الجن، بل هي أمور اعتادوها من أشربة، أو مأكولات، أو بخور يتبخرون به، وينفع الله به، أو ما أشبه ذلك من الأمور الواضحة والظاهرة التي ليس فيها تلبيس، ولا عبادة للجن، ولا دعوى علم الغيب، وهكذا الكي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10787/واجب-المسلم-تجاه-المشعوذين-والمخرفين-واهل-الطرق-البدعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":12730,"question":"إحدى الأخوات المستمعات بعثت برسالة مطولة بعض الشيء وقعت في نهايتها بقولها أمة الرحمن، ملخص ما في هذه الرسالة السؤال عما يسمى بقراءة الكف، سواءً كان ذلك جدًا، أو هزلًا؟","title":"حكم قراءة الكف والفنجان وضرب الحصا","answer":"الجواب:  هذه باطلة ومن الكهانة، ولا يجوز الكف والفنجال وأشباه ذلك، وضرب الحصى والودع، كل هذا ضلال، ومن دعوى علم الغيب، فإذا زعم أنه يعلم الغيب بهذه الأمور؛ صار كافرًا كفرًا أكبر، نعوذ بالله؛ لأن الغيب لا يعلمه إلا الله، ولا يعلم بضرب الحصى، ولا بضرب الكف، ولا الفنجال، ولا بغير ذلك مما يتعاطاه المشعوذون. فعلم الغيب إلى الله  فمن زعم أنه بضرب الكف، أو ضرب الحصى، أو حساب بالأصابع، أو بأي شيء من الأشياء أنه يعلم الغيب، كل هذا من الكفر بالله -عز وجل- والله يقول سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول -جل وعلا- في كتابه العظيم لنبيه ﷺ: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ [الأنعام:50] فمن ادعى بعمل الكف، أو عمل الحصى، أو الودع، أو غير هذا من الحسابات؛ فكله باطل، وكله كفر وضلال، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10943/حكم-قراءة-الكف-والفنجان-وضرب-الحصا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46102.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13241,"question":"في آخر أسئلتها تقول السائلة أم عبدالرحمن: جدتي امرأة كبيرة في السن، وليس عندها ما تشتغل به وقت الفراغ، وتتسلى بما يسمى الخط، علمًا بأننا نصحناها كثيرًا بالابتعاد عن هذا الخط، لكنها تقول: بأنني آخذ ذلك من باب التسلية، ولا أصدق ما يأتي فيه، وتقول: بأن السيدة فاطمة -رضي الله عنها- كانت تتسلى به، فهل هذا صحيح، وماذا يجب عليها، ونلاحظ أن هناك أمور تقولها، فيحدث في الواقع، فما تفسير ذلك، مأجورين؟","title":"حكم العيافة والطرق والخط في الأرض","answer":"الجواب: هذا فيه تفصيل: إن كان الخط يعني عن اعتقاد أنه يقع شيء هذا هو الذي أنكره النبي ﷺ وسماه من السحر، قال: إن العيافة والطرق من الجبت.  فالمقصود: أن الطرق في الأرض، والخطوط في الأرض إذا كان لمقصد أنها تستعلم بها أمور الغيب، وأنها تريد أن هذا يفيدها شيئًا من الغيب، هذا باطل، وهذا من أعمال الجاهلية، وقال النبي ﷺ: إن العيافة والطرق والطيرة من الجبت فالواجب على المؤمن ترك ذلك. أما إذا كانت الخطوط من باب العبث... من باب التسلي، الخطوط تخطط في الأرض للتسلي والعبث، وليس عن عقيدة شيء؛ فهذا لا يضر، كونها تتسلى بخطوط، أو بأحجار تصفها، أو تلعب بها، أو شعابة، أو ما أشبه ذلك؛ هذا كله لا بأس إذا كان من باب التسلي والعبث، ليس عن اعتقاد شيء. أما أن تخط، أو تعمل بحصى، أو بودع، أو غيره، تعتقد أن هذا يترتب عليه شيء، هذا لا يجوز؛ لأن هذا من عمل السحرة، ومن عمل العرافين، ومن عمل الجاهلية، ولا يجوز، وسماه النبي ﷺ الطرق، قال: إن العيافة والطرق والطيرة من الجبت قال عمر: «الجبت السحر، والطاغوت الشيطان» وقال بعضهم: الجبت معناه: الشيء الذي لا خير فيه، الشر الذي لا خير فيه، فإذا فعلت ما يفعله جهال العرب، وهي العيافة، إذا مر بهم طائر، أو رأوا حيوانًا ما هو بزين، أو مقطوع الذنب؛ تشاءموا، ورجعوا عن حوائجهم، هذه الطيرة، هذه العيافة التي أنكرها الرسول ﷺ يقال: عاف يعيف إذا زجر الطير، وقال: خيرًا يا طير، أو رجع عن قصده، أو توقف عن قصده، هذا كله من العيافة .. من التشاؤم المنكر. وهكذا الطرق يعني: الخط في الأرض إذا كان لقصد يتعلم علوم الغيب، أو يظن أن هذا يعطيه شيئًا من علم الغيب، هذا من الجبت .. من الشيء الذي لا خير فيه، ومن أعمال السحر المنكرة، فلا يجوز، كما تقدم. نعم. وأما ما تقول عن فاطمة؛ فلا أعلم له أصلًا، ما تذكره عن فاطمة -رضي الله عنها- هذا لا أعلم له أصلًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11525/حكم-العيافة-والطرق-والخط-في-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51307.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13618,"question":"السائلة التي رمزت لاسمها بـ (س. ل. ع) جمهورية مصر العربية، تذكر في هذه الرسالة بأنها فتاة تبلغ من العمر الثالثة والعشرين، وتعمل بالسحر والشعوذة، تقول: منذ صغري، وأريد أن أعرف من فضيلتكم بعض الإجابة عن هذا السؤال، وهي  هل الأموال حرام، والمأكل، والمشرب، والملبس حرام، مع العلم بأنني أصوم وأصلي، وأساعد أبي في عمله، فأبي يعمل في هذه العملية، وهي السحر والشعوذة، علمًا بأنني عندما أحاول أن أبتعد عنه يغضب مني هو ووالدتي، وجهونا في ضوء سؤالنا؟","title":"حكم السحر وتعلمه والذهاب إلى السحرة والعرافين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا شك أن تعاطي السحر من المنكرات العظيمة، بل من الشرك، إذا عرف أنه يستخدم الجن، ويسألهم، ويدعي بذلك علم الغيب، وأنه يكون كذا، ويقع كذا، هذا كله من الشرك الأكبر، قال الله -جل وعلا- في كتابه العظيم: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فجعلهم كفارًا بتعليم الناس السحر، ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] يعني: حتى يقول الملكان: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] دل على الكفر فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنْ اشْتَرَاهُ [البقرة:102] يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] يعني: من حظ ولا نصيب وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ ۝ وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102- 103] دل على أنه ضد التقوى، وضد الإيمان. فالواجب على كل حال: الحذر من هذا الأمر، وإذا كان في بلاد إسلامية تحكم بالشريعة؛ وجب أن يحكم فيه شرع الله -هذا الساحر- بأن يقتل؛ لأن السحرة قد يقتلون كما كتب عمر إلى عماله في الشام: أن يقتلوا كل ساحر وساحرة. حكم السحرة القتل لكفرهم؛ لأنهم يعبدون الجن، ويستعينوا بهم في إيذاء الناس، وفي ظلم الناس. أما الشعوذة تحتاج لتفصيل، لابد يعرف ما هي الشعوذة، فإن كان يدعي علم الغيب -المشعوذ- يدعي أنه كاهن، وأنه يسرق السمع، فهذا من جنس الساحر، يدعي علم الغيب؛ حكمه حكم الساحر، من ادعى علم الغيب؛ كفر. فأما إن كان شعوذة غير هذا، شعوذة بأن يكذب على الناس، يقول: ترى المحل الذي تطلبونه ... الفلاني، وترى سيارتكم في المحل الفلاني الضايع، بعيركم في المحل الفلاني، يكذب عليهم وإلا هو ما يدعي علم الغيب، ولكن يكذب.. يقول: إنه بعلامات، ثم آثار وإلا غيرها دلت على ذلك، هذا يسمى مشعوذ، ولا يجوز في مثل هذا سؤاله، ولا إتيانه إذا عرف منه الشعوذة والكذب، لا يسأل؛ لأنه داخل في العرافين، والنبي ﷺ يقول: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين ليلة وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام. فهذا العراف الذي يدعي أنه يعرف الأمور دعوته علم الغيب ... بكذا وكذا من الشعوذة، يصير في يوم كذا كذا، يخسف القمر في يوم كذا، وهو ما عنده خبر بالحساب، بل بزعمه علم الغيب، أو أنه يموت فلان في يوم كذا، أو يصاب بكذا. المقصود: دعوى علم الغيب، هذا العراف الذي يدعي هذا حكمه حكم السحرة، كافر -نسأل الله العافية- فعليه يستتاب، فإن تاب وإلا قتل، والقاعدة: كل من ادعى علم الغيب؛ يكون كافرًا؛ لأن الله يقول: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول سبحانه: وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59]. فهو -جل وعلا- الذي يعلم الغيب، فمن ادعى علم الغيب؛ كفر، ومن تعاطى السحر؛ كفر؛ لأنه بتعاطيه السحر، يعبد الجن، ويستعين بهم في حاجاته من ضرر الناس، أو أخذ أموالهم، أو ما أشبه ذلك مما يفعله بسبب دعواه السحر. نعم. ومثل هذا التنجيم الذي يعبد النجوم، ويستعين بالنجوم، ويرى أنه يعلم الغيب بواسطة النجوم، يستتاب، فإن تاب وإلا قتل؛ لأن دعوى علم الغيب كفر، سواء من طريق النجوم، أو من طريق الجن، أو من غير ذلك، أو من أي طريق، نسأل الله العافية. المقدم: جزاكم الله خيرًا. سماحة الشيخ! هذا الموضوع حقيقة يحتاج إلى بسط في القول، ولكن هناك تساهل الناس في الذهاب إلى السحرة والمشعوذين، ما توجيهكم لهم يا سماحة الشيخ؟ الشيخ: مثل ما تقدم، الواجب الحذر، لا يجوز سؤالهم، ولا التوجه لهم، لا السحرة، ولا المنجمين، والعرافين، ولا المشعوذين، يجب الحذر من هؤلاء الذين يدعون علم الغيب، سواء بالسحر، أو بالشعوذة، أو بالكهانة، أو بالتنجيم، أو ما أشبه ذلك، يجب الحذر منهم، وألا يصدقوا، وألا يسألوا؛ لأن الرسول ﷺ حذر من ذلك، حذر من سؤالهم، ومن تصديقهم، فيجب الحذر من ذلك، والذي يدعي علم الغيب؛ يكون كافرًا، نسأل الله العافية، كالساحر سواء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11960/حكم-السحر-وتعلمه-والذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53401.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13625,"question":"السائلة التي رمزت لاسمها بـ (س. ل. ع) جمهورية مصر العربية، تذكر في هذه الرسالة بأنها فتاة تبلغ من العمر الثالثة والعشرين، وتعمل بالسحر والشعوذة، تقول: منذ صغري، وأريد أن أعرف من فضيلتكم بعض الإجابة عن هذا السؤال، وهي  هل الأموال حرام، والمأكل، والمشرب، والملبس حرام، مع العلم بأنني أصوم وأصلي، وأساعد أبي في عمله، فأبي يعمل في هذه العملية، وهي السحر والشعوذة، علمًا بأنني عندما أحاول أن أبتعد عنه يغضب مني هو ووالدتي، وجهونا في ضوء سؤالنا؟","title":"حكم السحر وتعلمه والذهاب إلى السحرة والعرافين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا شك أن تعاطي السحر من المنكرات العظيمة، بل من الشرك، إذا عرف أنه يستخدم الجن، ويسألهم، ويدعي بذلك علم الغيب، وأنه يكون كذا، ويقع كذا، هذا كله من الشرك الأكبر، قال الله -جل وعلا- في كتابه العظيم: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فجعلهم كفارًا بتعليم الناس السحر، ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] يعني: حتى يقول الملكان: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] دل على الكفر فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنْ اشْتَرَاهُ [البقرة:102] يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] يعني: من حظ ولا نصيب وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ ۝ وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102- 103] دل على أنه ضد التقوى، وضد الإيمان. فالواجب على كل حال: الحذر من هذا الأمر، وإذا كان في بلاد إسلامية تحكم بالشريعة؛ وجب أن يحكم فيه شرع الله -هذا الساحر- بأن يقتل؛ لأن السحرة قد يقتلون كما كتب عمر إلى عماله في الشام: أن يقتلوا كل ساحر وساحرة. حكم السحرة القتل لكفرهم؛ لأنهم يعبدون الجن، ويستعينوا بهم في إيذاء الناس، وفي ظلم الناس. أما الشعوذة تحتاج لتفصيل، لابد يعرف ما هي الشعوذة، فإن كان يدعي علم الغيب -المشعوذ- يدعي أنه كاهن، وأنه يسرق السمع، فهذا من جنس الساحر، يدعي علم الغيب؛ حكمه حكم الساحر، من ادعى علم الغيب؛ كفر. فأما إن كان شعوذة غير هذا، شعوذة بأن يكذب على الناس، يقول: ترى المحل الذي تطلبونه ... الفلاني، وترى سيارتكم في المحل الفلاني الضايع، بعيركم في المحل الفلاني، يكذب عليهم وإلا هو ما يدعي علم الغيب، ولكن يكذب.. يقول: إنه بعلامات، ثم آثار وإلا غيرها دلت على ذلك، هذا يسمى مشعوذ، ولا يجوز في مثل هذا سؤاله، ولا إتيانه إذا عرف منه الشعوذة والكذب، لا يسأل؛ لأنه داخل في العرافين، والنبي ﷺ يقول: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين ليلة وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام. فهذا العراف الذي يدعي أنه يعرف الأمور دعوته علم الغيب ... بكذا وكذا من الشعوذة، يصير في يوم كذا كذا، يخسف القمر في يوم كذا، وهو ما عنده خبر بالحساب، بل بزعمه علم الغيب، أو أنه يموت فلان في يوم كذا، أو يصاب بكذا. المقصود: دعوى علم الغيب، هذا العراف الذي يدعي هذا حكمه حكم السحرة، كافر -نسأل الله العافية- فعليه يستتاب، فإن تاب وإلا قتل، والقاعدة: كل من ادعى علم الغيب؛ يكون كافرًا؛ لأن الله يقول: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول سبحانه: وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59]. فهو -جل وعلا- الذي يعلم الغيب، فمن ادعى علم الغيب؛ كفر، ومن تعاطى السحر؛ كفر؛ لأنه بتعاطيه السحر، يعبد الجن، ويستعين بهم في حاجاته من ضرر الناس، أو أخذ أموالهم، أو ما أشبه ذلك مما يفعله بسبب دعواه السحر. نعم. ومثل هذا التنجيم الذي يعبد النجوم، ويستعين بالنجوم، ويرى أنه يعلم الغيب بواسطة النجوم، يستتاب، فإن تاب وإلا قتل؛ لأن دعوى علم الغيب كفر، سواء من طريق النجوم، أو من طريق الجن، أو من غير ذلك، أو من أي طريق، نسأل الله العافية. المقدم: جزاكم الله خيرًا. سماحة الشيخ! هذا الموضوع حقيقة يحتاج إلى بسط في القول، ولكن هناك تساهل الناس في الذهاب إلى السحرة والمشعوذين، ما توجيهكم لهم يا سماحة الشيخ؟ الشيخ: مثل ما تقدم، الواجب الحذر، لا يجوز سؤالهم، ولا التوجه لهم، لا السحرة، ولا المنجمين، والعرافين، ولا المشعوذين، يجب الحذر من هؤلاء الذين يدعون علم الغيب، سواء بالسحر، أو بالشعوذة، أو بالكهانة، أو بالتنجيم، أو ما أشبه ذلك، يجب الحذر منهم، وألا يصدقوا، وألا يسألوا؛ لأن الرسول ﷺ حذر من ذلك، حذر من سؤالهم، ومن تصديقهم، فيجب الحذر من ذلك، والذي يدعي علم الغيب؛ يكون كافرًا، نسأل الله العافية، كالساحر سواء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11960/حكم-السحر-وتعلمه-والذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53401.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13698,"question":"يقول هذا السائل طه عبدالحميد من السودان: يزعم أحد الدجالين بأنه يستطيع أن يتعرف على السارق بعد أن يسرق غيبًا، وذلك بأمور لا يعلمها كثير من الناس، منها: بأنه يأمر بإحضار صحن ماء، وطفل دون سن البلوغ، ويكون قد رضع من ثديي أمه حولين كاملين، ولم يخيفه كلب، ثم يقوم بقراءة شيء من القرآن، وبعض الكلمات التي لا تفهم، ثم يسأل الطفل، هل رأيت شيئًا في الماء الذي في الصحن، فيصف الطفل السارق بالتفاصيل، وأين أخفى المسروقات، فما حكم الشرع في مثل هذا؟ وهل تجوز الصلاة خلفه؟ وهل يجوز لنا أن نقوم بوصله في السراء والضراء، علمًا بأننا نصحناه، ولكنه لا يقبل النصيحة، ويقول: بأنه على حق، أفتونا مأجورين؟","title":"حكم الصلاة خلف العراف والتعامل معه","answer":"الجواب: هذا من باب التلبيس والخداع والكذب، وإنما هو يستخدم الجن، ويسأل الجن، فقد يخبرونه، وقد يعرفون السارق فيخبرونه، مثل هذا لا يصلى خلفه، بل يجب أن يرفع أمره للمحكمة، أو للهيئة، أو للإمارة حتى يردع عن هذا العمل؛ لأن هذا من باب دعوى علم الغيب، وذكر الطفل والصبي، وكذا، والماء، كل هذه من باب التلبيس والخداع. وإنما الحقيقة أنه يسأل الجن، ويستعين بالجن، ويخبر عنهم، وقد يغلطون، وقد يصدقون. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12069/حكم-الصلاة-خلف-العراف-والتعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53502.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13700,"question":"يقول هذا السائل طه عبدالحميد من السودان: يزعم أحد الدجالين بأنه يستطيع أن يتعرف على السارق بعد أن يسرق غيبًا، وذلك بأمور لا يعلمها كثير من الناس، منها: بأنه يأمر بإحضار صحن ماء، وطفل دون سن البلوغ، ويكون قد رضع من ثديي أمه حولين كاملين، ولم يخيفه كلب، ثم يقوم بقراءة شيء من القرآن، وبعض الكلمات التي لا تفهم، ثم يسأل الطفل، هل رأيت شيئًا في الماء الذي في الصحن، فيصف الطفل السارق بالتفاصيل، وأين أخفى المسروقات، فما حكم الشرع في مثل هذا؟ وهل تجوز الصلاة خلفه؟ وهل يجوز لنا أن نقوم بوصله في السراء والضراء، علمًا بأننا نصحناه، ولكنه لا يقبل النصيحة، ويقول: بأنه على حق، أفتونا مأجورين؟","title":"حكم الصلاة خلف العراف والتعامل معه","answer":"الجواب: هذا من باب التلبيس والخداع والكذب، وإنما هو يستخدم الجن، ويسأل الجن، فقد يخبرونه، وقد يعرفون السارق فيخبرونه، مثل هذا لا يصلى خلفه، بل يجب أن يرفع أمره للمحكمة، أو للهيئة، أو للإمارة حتى يردع عن هذا العمل؛ لأن هذا من باب دعوى علم الغيب، وذكر الطفل والصبي، وكذا، والماء، كل هذه من باب التلبيس والخداع. وإنما الحقيقة أنه يسأل الجن، ويستعين بالجن، ويخبر عنهم، وقد يغلطون، وقد يصدقون. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12069/حكم-الصلاة-خلف-العراف-والتعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53502.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13905,"question":"السائل من ليبيا يقول سماحة الشيخ: ما هو العلاج الشرعي للسحر؟ وما هو العلاج الشرعي للوسواس؟ وهل هناك أدعية شرعية تنصحوننا فيها؟","title":"العلاج الشرعي للسحر","answer":"الجواب: علاج السحر بالتعوذات الشرعية: بقراءة آية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] والمعوذتين، وتكرار ذلك، هذا من أعظم العلاج، تدبر القرآن والاستفادة من القرآن، يقرأ ما تيسر من القرآن .. الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1]، والمعوذتين، وكذلك ما تيسر من الآيات الأخرى، يقرؤها على المسحور حتى يخلصه الله من ذلك، وقد أخبر النبي ﷺ أن الله جل وعلا أزال عنه ما قد أصابه من السحر لما أنزل الله عليه سورة المعوذتين وقال: ما تعوذ متعوذ بمثلهما، فالتعوذ بالمعوذتين مع قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] من أعظم الأسباب في زوال السحر مع قراءة الفاتحة وآية الكرسي، وما تيسر من الآيات القرآنية كآخر سورة الحشر وغير ذلك، مع التعوذ بكلمات الله التامات من شر ما خلق يكررها: أعوذ بكلمات الله التامات من شر ما خلق، أعوذ بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامة كل هذا من العلاج. وإذا وجد طبيب حاذق أو إنسان يعرف علاجًا آخر مادي لا منكر فيه ولا شبهة فيه فلا بأس، مثل: كونه يأخذ سبع ورقات من السدر الأخضر ويدقها بين حجرين ثم يقرأ فيهما آية الكرسي وقُلْ يَا أَيُّهَا الْكَافِرُونَ[الكافرون:1]، وقُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1]، والمعوذتين وفاتحة الكتاب ثم يشرب منها ويغتسل، هذا مجرب في علاج السحر، وقد نفع كثيرًا، وقد استعملناه مع ناس كثير ونفعهم الله بذلك، وهو أيضًا نافع للرجل إذا حبس عن زوجته هذا العلاج جاء عن بعض السلف، وهو مجرب ونافع للسحر ولحبس الرجل عن زوجته، لكن أعظم من ذلك العلاج بالقرآن بفاتحة الكتاب.. بآية الكرسي .. قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] والمعوذتين بغير هذا من الآيات القرآنية، يقرأ وينفث ويتعوذ بكلمات الله التامات من شر ما خلق، هذا كله علاج عظيم نافع قد نفع الله به نبينا ﷺ ونفع به غيره من المسلمين.\nولا يجوز إتيان السحرة ولا تصديقهم، لا يجوز العلاج عند السحرة، ولا سؤالهم ولا تصديقهم؛ لقوله ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة، وقال: من أتى كاهنًا أو عرافًا فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ، فالواجب الحذر من إتيان السحرة، والكهان، والمنجمين، والعرافين، والحذر من تصديقهم؛ لأن هذا كله لا يجوز، بل هو شر عظيم، فيجب الحذر منه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12287/العلاج-الشرعي-للسحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53814.mp3","categories":["الأدعية والأذكار","السحر والكهانة"]},{"id":14056,"question":"رسالة وصلت إلى البرنامج من صنعاء باعثها مستمع من هناك يقول: (ج.ع. ي) وزميل له هو (ن. د. ي. ط) يقولون في هذه الرسالة: إننا في زمن كثرت فيه الخرافات والشعوذة، وإن هناك رجلًا يدعي أنه يعلم المخفيات مثل السرقة وغير ذلك، والأمر أنه في حالة عجز المواطنين عن معرفة أي شيء حصل في البلاد فإن العمدة يرسل بعض الأشخاص إلى هذا الرجل ليعرفوا منه ما حدث، وقد يكذب أو يصدق ولكن المؤسف أنهم يحكمون على الناس بما قال هذا الدجال ولا يحق لأحد أن يتكلم أو يدافع عن نفسه بعد هذا، نرجو من سماحة الشيخ التوجيه؟ جزاكم الله خيرًا.","title":"حكم الأخذ بأقوال الكهنة والمشعوذين","answer":"الجواب: هذا غلط عظيم، لا يجوز الاعتماد على الكهنة والمشعوذين والعرافين، بل يجب أن يقضى عليهم، يجب على الدولة إذا كانت مسلمة تخاف الله يجب عليها أن تقضي عليهم وأن تلتمسهم وأن تؤدبهم وتعاقبهم حتى يتركوا هذا العمل، وقد صح عن رسول الله عليه الصلاة والسلام: أنه سئل عن الكهان؟ فقال: لا تأتوهم فقيل له: إنهم قد يصدقون في بعض الشيء؟ فقال: تلك الكلمة يسمعها الجني يسمعها من الملائكة عند استراقه السمع فيقرها في أذن وليه من الإنس، يعني يقرها في أذن الكاهن أو الساحر فيصدق أولئك الكهنة بتلك الكلمة التي سمعت من السماء في كذبهم الكثير، ويقولون: قد قال كذا وكذا وصدق، فيصدقونه بما يكذب فيه من مئات الكذبات التي لا أساس لها.  وقد قال عليه الصلاة والسلام في الحديث الصحيح: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وقال عليه الصلاة والسلام: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، لم تقبل له صلاة أربعين ليلة كما في مسلم في الصحيح، ........ رحمه الله، وقال عليه الصلاة والسلام: ليس منا من سحر أو سحر له أو تكهن أو تكهن له أو تطير أو تطير له.  فهؤلاء لا يصدقون ولا يعتمد عليهم، وإذا صمموا وأقروا بأنهم يعلمون الغيب أو يدعون علم الغيب صاروا كفارًا بذلك، فمن ادعى أنه يعلم المغيبات يكون كافرًا كما قال الله : قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ[النمل:65]، فمن زعم أنه يعلم الغيب فهو مكذب لله ومشارك لله فيما اختص به ، وهذا كفر أكبر وضلال بعيد، علم الغيب لا يعلمه إلا الله، حتى الأنبياء لا يعلمونه، حتى محمد عليه الصلاة والسلام -وهو أفضل الخلق- لا يعلم الغيب إلا ما علمه الله إياه، كما قال : قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ[الأعراف:188]، وقال جل وعلا: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ[الأنعام:50] الآية. فمن زعم أنه يعلم الغيب من الكهنة ونحوهم وهو كافر ضال ومن صدقه بذلك فهو مثله يكون كافرًا مثله، نسأل الله العافية.\nالمقصود أن هؤلاء المشعوذين من الكهنة يجب أن يحاربوا وأن يقضى عليهم من جهة الدولة وأن يؤدبوا ويعاقبوا حتى يتركوا هذا الأمر، فإن أصروا على هذا الباطل وجب قتلهم؛ لأنهم من المفسدين في الأرض. نعم.\nالمقدم: جزاكم الله خيرًا، الواقع تكثر شكاية كثير من الناس من أمثال هؤلاء يا سماحة الشيخ، لعل لسماحتكم توجيه فيما يخص التعامل معهم ومقاطعتهم إذا لزم الأمر؟\nالشيخ: نعم، مثلما تقدم يجب أن يقاطعوا ويجب على من عرفهم أن يعرف عنهم ولاة الأمور من الهيئة والمحكمة والإمارة ولاسيما في هذه المملكة التي هي بحمد الله تحكم بالشرع.\nفالواجب على من عرف أحدًا من هؤلاء الكهنة والمنجمين والرمالين والمشعوذين أن يرفع أمره إلى الإمارة في بلده أو المحكمة أو الهيئة أو إلى الجميع حتى تبرأ ذمته وحتى يحصل التعاون، ولا يجوز التستر عليه ولا إخفاء أمره، بل يجب إعلان أمره وفضيحته حتى لا يضر الناس.\nوهكذا في اليمن، في اليمن يجب على من عرف ذلك أن يرفعه إلى ولاة الأمر حتى يمنعوه من التعدي على الناس والكذب عليهم، بل يجب على ولاة الأمور في اليمن وفي غيرها أن يقضوا على هؤلاء المشعوذين والرمالين والكهنة وأن يمنعوهم من تعاطي هذه الأعمال القبيحة المنكرة التي فيها.. تضل الناس وخداعهم وأخذ أموالهم بالباطل والكذب عليهم.\nالمقصود: أن هذا واجب على المسلمين أن يتعاونوا فيه، في الدول الإسلامية وفي غير الدول الإسلامية مع المسلمين في الأقليات الإسلامية إذا وجد بينهم من يفعل هذا يتعاونون في نصيحته وفي بيان باطله حتى يرجع إلى الحق والصواب، أما في الدول الإسلامية فالواجب عليهم القضاء عليه، كما يجب على الدول الإسلامية القضاء على كل ما حرم الله من المنكرات الظاهرة وأعظمها الشرك بالله  من دعوة أصحاب القبور والاستغاثة بالأموات والنذر لهم والذبح لهم كل ذلك يجب القضاء عليه؛ لأنه منكر عظيم وشرك وخيم، وهكذا إظهار البدع المنكرة المخالفة لشرع الله يجب القضاء عليها، وهكذا وجود الكهنة والمنجمين والمشعوذين يجب القضاء عليهم وإعلان أن الدولة ضدهم حتى يفضحهم الناس وحتى يرفعوا بأمرهم إلى ولاة الأمور للقضاء عليهم وحماية المجتمع الإسلامي من شرهم ومكائدهم. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12495/حكم-الاخذ-باقوال-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61305.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14118,"question":"كما توقعنا في الحلقة الماضية شيخ عبد العزيز أن هناك عددًا من السادة المستمعين سيسألون عن هؤلاء الكهان والدجالين، هذا هو المستمع إدريس محمد فضل المولى يسأل أيضًا عن هذا الموضوع، ويبدو أن القضية موجودة حتى في السودان، فهم يتعلقون بهم ولاسيما أولئك الذين ابتلي بعض أقاربهم بالمرضى أو بضياع شيء من الأموال وما أشبه ذلك، ويرجو التوجيه جزاكم الله خيرًا، وسؤال أخينا حول هذا الموضوع استغرق ما يقرب من صفحة؟","title":"حكم سؤال الكهنة والمشعوذين","answer":"الجواب: سبق التنبيه على هذا وأنه لا يجوز لأي مسلم أن يسأل الكهنة والمنجمين والعرافين والمشعوذين الذين يدعون علم الغيب أو يعرفون بأشياء تدل على ذلك، فمن كان يتهم بذلك أو يعرف بذلك لا يسأل ولا يصدق، بل يلتمس أهل الخير وأهل العلم والإيمان حتى يقرأ على المريض، ينفث على المريض، أو الطبيب المعروف بالحذق والفهم، يسأل عن المرض، الطبيب المعروف، أما الكهان والمنجمون والرمالون والمشعوذون والعرافون كل من يدعي شيئًا من أمور الغيب ويزعم أنه يعرف هذا بكذا وكذا منهم، هذا كله منكر يجب الحذر منهم. وقد قال عليه الصلاة والسلام في الحديث الصحيح: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، «أربعين ليلة» في ..... وقال ﷺ: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فالأمر عظيم، وقال النبي ﷺ لما سئل عن الكهان قال: لا تأتوهم، وقال: ليسوا بشيء. فالكاهن والعراف والرمال ونحوهم يدعون علم الغيب بأمور وأشياء يشبهون بها على الناس ويخدعون بها الناس من ضرب بالحصى أو سؤال عن اسم أمه واسم فلانة وفلانة، أو غير ذلك من الأسئلة التي يزعمون بها أنهم يعلمون الغائب أو يعلمون كذا وكذا من أسباب مرضه غير الطريقة المعروفة من سؤاله عن صفة المرض وأسباب المرض الذي أصابه حتى يهتدوا إلى علاج، الذين يدعون أشياء خارجية عن ذلك من جهة النجوم أو من جهة اسم أمه أو من جهة الأشياء التي لا تعلق بها بالمرض هذا كله من أمارات أنهم مشعوذون وأنهم كهنة يجب الحذر منهم، وإنما يؤتى المعروف بالخير والاستقامة والدين، وأن يتعاطى طبًا واضحًا ليس فيه شبهة وليس فيه ما يوهم دعوى علم الغيب أو خدمة الجن ودعاء الجن وعبادة الجن، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12567/حكم-سوال-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61505.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14191,"question":"السائل الذي رمز لاسمه أبو هاجر من الخرج يقول في هذا السؤال سماحة الشيخ: هل يجوز للإنسان أن يذهب للعلاج عند السحرة وذلك في الضرورة القصوى؟ وجهونا في ضوء هذا السؤال.","title":"حكم الذهاب للعلاج عند السحرة","answer":"الجواب: لا يجوز للمسلم أن يذهب إلى السحرة والكهنة، لا لسؤالهم ولا للعلاج، يجب الحذر منهم وعدم تصديقهم وعدم إتيانهم؛ لأن الرسول حذر من ذلك، الرسول ﷺ حذر من المجيء إلى السحرة والكهنة والعرافين، وقال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة وقال عليه الصلاة والسلام: من أتى عرافًا أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ. فالواجب الحذر من السحرة وغيرهم من الكهنة والعرافين وغيرهم ممن يتكلم في الأمور بالطرق الغيبية ويتخرص، نسأل الله العافية.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12644/حكم-الذهاب-للعلاج-عند-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54723.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14194,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. م. د) أخونا رسالته من صفحتين مجمول ما في هاتين الصفحتين السؤال عن الكهان والمشعوذين حيث انتشر أمرهم حتى بين الطلبة في الامتحانات وبين أولئك الذين يبحثون عن عمل ولا يجدون، فهؤلاء يكتبون لهم أوراق ويأمرونهم بأشياء وأشياء يعتقدون من ورائها أنها ستكون مجلبة للعمل، ويرجون من سماحة الشيخ التوجيه. جزاكم الله خيرًا.","title":"حكم إتيان الكهنة والمشعوذين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد أوضح النبي عليه الصلاة والسلام حكم الكهان والمنجمين والعرافين ومن في حكمهم ممن يدعي علم الحوادث وعلم المستقبل بالتنجيم أو بضرب الحصى أو بغير هذا من الطرق الخفية التي يزعم أنها تطلعه على علم الغيب، وقد أوضح النبي ﷺ أن حكم هؤلاء أنهم لا يجوز أن يؤتوا ولا أن يسألوا ولا أن يصدقوا، فقد ثبت في صحيح مسلم عن بعض أزواج النبي ﷺ أنه قال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة، هذا الحديث الصحيح يدل على تحريم السؤال مجرد من دون تصديق، فكيف إذا كان مع التصديق؟ فلا يجوز سؤال الكهان، ولا إتيانهم، ولا تصديقهم.\nوفي الحديث الثاني يقول عليه الصلاة والسلام: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ أخرجه أهل السنن بإسناد صحيح، وقال أيضًا عليه الصلاة والسلام: ليس منا من سحر أو سحر له أو تكهن أو تكهن له أو تطير أو تطير له. فالذين يدعون علم المغيبات أو الحظ أو الكف أو متى ينجح فلان أو متى يقبل في وظيفة أو غير هذا من هؤلاء وأشباههم كل ذلك مما حرم الله سؤالهم واللجوء إليهم أو تصديقهم، وإنما المؤمن يسأل ربه التوفيق والتسهيل والتيسير، يسأل ربه أن يقضي له حاجته من نجاح في اختبار ومن حصول وظيفة تنفعه ... إلى غير ذلك، أما إتيان الكهان الذين يدعون علم الغيب بأي طريقة فلا يجوز إتيانهم ولا سؤالهم ولا تصديقهم، لما ثبت في حقهم من الأحاديث الصحيحة التي سبق بعضها والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12647/حكم-اتيان-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61601.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14435,"question":"أخيرًا من أسئلة أختنا نعرض هذا السؤال تقول: سمعت خبرًا بأن هناك امرأة تتعامل مع الجن، وأخبرها الجن بأنها ستكون وسيطة خير بين الجن والإنس لتعالج الأمراض المستعصية في الإنس، والتي عجز عنها طب الإنس، والمرأة هي الوسيط، والجن يعطون الأدوية، ويعملون العمليات لبني الإنسان، ولكن الإنسان لا يراهم، ما رأي سماحتكم في مثل هذا؟","title":"حكم التعامل مع الجن لعلاج الناس","answer":"الجواب: ليس لهذا أصل، ولا يعتمد عليه، فإن أخبار الجن، وأخبار العجائز، وأخبار من يخدم الجن لا يوثق بها، ولا يعتمد عليها، ولا يجوز أن يعتمد على قول عجوز أو شيخ أو شاب، أو غير ذلك ينقل عن الجن أشياء، بل يجب أن يحذر منهم، وأن لا يستخدمهم في شيء؛ لأنهم إذا استخدموه قد يجرونه إلى الشرك بالله ، إذا كانوا غير مؤمنين، وليس المؤمن منهم معروفًا معرفة يقينية، فقد يكون منافقًا، وقد يكون يدس السم في الدسم؛ لأنك لا تعرفهم ولا تخالطهم مخالطة جهرية، وتعرف أحوالهم وأحوال قرنائهم من الأخيار، حتى تعرف الثقة من غير الثقة. فالحاصل: أنّ بيننا وبينهم جهلًا كبيرًا، وأخلاقًا متباينة، وصفات متباينة، لا نستطيع معها أن نتحقق ما هم عليه، ومن عرفنا منهم بما يظهره من الإيمان ندعو له بالتوفيق، وندعو له بالصلاح، ولكن لا نثق به، ولا نطمئن إليه في أن نأخذ منه طبًا، أو غير ذلك، أو نستشيره في شيء، أو ما أشبه ذلك، فإن هذا قد يفضي إلى دعوى علم الغيب، قد يبتلى الإنسان بذلك فيظن أن عنده شيئًا من علم الغيب بواسطة الجن، وقد يدعو إلى ذلك، فيكون ممن قال الله فيهم -جل وعلا-: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا[الجن:6].\nفهو مع الجن على خطر، قد يستخدمونه في الشرك، قد يستخدمونه في البدع، قد يستخدمونه في المعاصي، فيضر نفسه، وهو لا يدري، ويضر غيره وهو لا يدري. فلا تجوز المعاملة لهم في الطب ولا في غيره، بل من عرف منهم أحدًا أو اتصل به أحد يدعوه إلى الله يعلمه الخير، يدعوه إلى توحيد الله، وإلى طاعة الله، وينصحه أن يعلم من عنده خير طاعة الله ، ولا يطمئن إليه في شيء، ولا يطلب منه شيئًا للناس؛ لأنه قد ينقل شيئًا يضر الناس، وقد يعطيه شيئًا طيبًا ثم يغشه بعد ذلك. فالحاصل: أنه على خطر؛ لأنك لا تعلم أحوالهم على اليقين، وهم يرونك ولا تراهم، وقد يخفون عنك أشياء كثيرة، وقد يدعون الإيمان وهم منافقون، وقد يتصلون بك لأغراض أخرى، حتى يأخذوها منك، ثم يفعلوا بك ما يريدون، فأنت على خطر، فالواجب الحذر منهم إلا من الدعوة إلى الله  وتبصيرهم بالحق، ودعوتهم إليه، وإرشادهم إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12925/حكم-التعامل-مع-الجن-لعلاج-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63105.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14697,"question":"سمعت من برنامجكم بأن تقرأ بعض آيات القرآن الكريم لإبطال عمل السحر، فما هي هذه الآيات؟ وهل يجوز قراءتها من قبل الشخص نفسه أم من قبل شخص آخر؟","title":"آيات فك السحر، وهل يجوز قراءتها من المسحور؟","answer":"الجواب: نعم، قراءة الآيات قد ينفع الله بها من الشخص نفسه، ومن غيره من أهل الإيمان والتقوى، فإذا ظن الإنسان أن به سحرًا، أو علم أن به سحرًا، وقرأ على نفسه آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] مع فاتحة الكتاب، ومع قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1]، وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] ينفث على صدره، ويقرأ هذه السور والآيات، كل ذلك يفيده -إن شاء الله-، ومن أسباب عافيته، وسلامته من السحر. والأحسن أن يكرر قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين ثلاث مرات، مع النفث على صدره، ويحسن أيضًا أن يقرأ آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها أيضًا، مع ذلك في الماء، ويشرب منه، ويغتسل بالباقي، كل هذا من أسباب العافية، إن نفث على نفسه بذلك على صدره بذلك فهذا من أسباب العافية، وإن قرأ ذلك في ماء ثم شرب منه واغتسل به فذلك أيضًا من أسباب الشفاء، وإن جعل في الماء سبع ورقات من السدر دقها -السدر الأخضر- دقها وجعلها في الماء، فذلك أيضًا مفيد في علاج السحر، وهكذا في علاج الرجل الذي حبس عن زوجته ينفعه هذا -بإذن الله-، وإن قرأها غير المصاب -قرأها بعض إخوانه في الله- في ماء وشرب منه، واغتسل به، فذلك نافع -إن شاء الله-، وينبغي أن يختار من ذلك أهل الخير المعروفون بالخير والعلم والفضل حتى يقرأ هذه الآيات في الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13197/ايات-فك-السحر-وهل-يجوز-قراءتها-من-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62902.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14704,"question":"سمعت من برنامجكم بأن تقرأ بعض آيات القرآن الكريم لإبطال عمل السحر، فما هي هذه الآيات؟ وهل يجوز قراءتها من قبل الشخص نفسه أم من قبل شخص آخر؟","title":"آيات فك السحر، وهل يجوز قراءتها من المسحور؟","answer":"الجواب: نعم، قراءة الآيات قد ينفع الله بها من الشخص نفسه، ومن غيره من أهل الإيمان والتقوى، فإذا ظن الإنسان أن به سحرًا، أو علم أن به سحرًا، وقرأ على نفسه آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] مع فاتحة الكتاب، ومع قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1]، وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] ينفث على صدره، ويقرأ هذه السور والآيات، كل ذلك يفيده -إن شاء الله-، ومن أسباب عافيته، وسلامته من السحر. والأحسن أن يكرر قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين ثلاث مرات، مع النفث على صدره، ويحسن أيضًا أن يقرأ آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها أيضًا، مع ذلك في الماء، ويشرب منه، ويغتسل بالباقي، كل هذا من أسباب العافية، إن نفث على نفسه بذلك على صدره بذلك فهذا من أسباب العافية، وإن قرأ ذلك في ماء ثم شرب منه واغتسل به فذلك أيضًا من أسباب الشفاء، وإن جعل في الماء سبع ورقات من السدر دقها -السدر الأخضر- دقها وجعلها في الماء، فذلك أيضًا مفيد في علاج السحر، وهكذا في علاج الرجل الذي حبس عن زوجته ينفعه هذا -بإذن الله-، وإن قرأها غير المصاب -قرأها بعض إخوانه في الله- في ماء وشرب منه، واغتسل به، فذلك نافع -إن شاء الله-، وينبغي أن يختار من ذلك أهل الخير المعروفون بالخير والعلم والفضل حتى يقرأ هذه الآيات في الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13197/ايات-فك-السحر-وهل-يجوز-قراءتها-من-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62902.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15001,"question":"يقول صاحب الودع وقارئة الفنجان والرسل وقراءة الكف لنا، هل هي حرام أم حلال؟","title":"حكم قراءة الفنجان والكف والودع","answer":"الجواب: كل هذا بدع، كلها منكرة، لا صحة لها، صاحب الفنجان وقراءة الكف، ورمي الودع، أو ضرب الودع، أو بالحصى كله من تعاطي علم الغيب كله باطل، كله منكر ولا صحة له، بل هو دجل وكذب وافتراء، ويدعون علم الغيب بأشياء أخرى غير هذا كذب، وإنما يعتمدون على ما تقول لهم أصحابهم من الجن، فإن بعضهم يستخدم الجن ويقول ما تقوله له الجن، فيصدقون ويكذبون، يصدقون في بعض الأشياء التي اطلعوا عليها في بعض البلدان، أو استرقوها من السمع، ويكذبون في الغالب، والأكثر يكذبون، ويتحيلون على الناس، حتى يأخذوا أموالهم بالباطل، وهكذا الإنس الذين يخدمونهم، قد يكذبون أيضًا ويفترون ويقولون هذا كذا، وهذا كذا، وهم كذبة، إنما يأكلون أموال الناس بالباطل، وعلم الغيب لا يعلمه إلا الله . أما كلمة الرسل ما أدري إيش مراده بالرسل، كلمة الرسل هذا كلام مجمل، إن كان المقصود قراءة القرآن الذي جاء به الرسول ﷺ يقرؤه ويتدبر ما فيه لعله يجد شيئًا يستعين به على علاج المريض، يعني يتدبر القرآن لعله يجد شيئًا يعني يستعين به على علاج المريض بقراءة آية على المريض، أو ما أشبه ذلك، فهذا لا يحتاج إلى هذا الكلام، القرآن شفاء، فإذا قرأ من بعض الآيات آية الكرسي، أو الفاتحة أو قُل هُو اللّهُ أَحْدٌ [الإخلاص:1]  أو المعوذتين هذا طيب، وهذه من أسباب الشفاء، فتسمية الرسل ما أدري ما مراده.\nالمقدم: بالنسبة للرسل -بارك الله فيكم- يقول: يحكى أنه هناك إذا جاء لهم من يريد الاستفادة من صاحبة الودع وقارئة الفنجال إلى آخره أنهم يرسلون رسولًا يخبر عن هذا الشخص، يخبر أهله وأقاربه أنه بخير. الشيخ: هذا كلام ما له تعلق بالعلاج، إرسال الرسل جمع رسول إلى أهل المريض هذا ما له تعلق بالعلاج، سواء أرسلوا لهم، أو ما أرسلوا لهم، هذا شيء ماله تعلق بالعلاج، إنما هو متعلق بتطمينهم عن صحته، هذا شيء آخر، نعم. المقدم: هو يشتكي من كثرة هؤلاء في البلد، يعني: في بلده في السودان، ويقول: إذا تكرر تحقق ما يقولون، هل في هذا علم بالغيب أم لا؟ الشيخ: أبدًا، فهو كله باطل، ولكن قد يتكرر لأنهم شيء يعرفونه من بلادهم، مثل يخبرون عن إنسان فعل كذا، أو فعل كذا، وهم قد شاهدوه في البلاد الأخرى من السودان، أو أشياء خبرتهم بها جن أن هذا وقع في بلد كذا، وعمل له كذا، وصار كذا، فهم يأخذون عن الجن أخبارًا أدركها الجن في بعض البلدان، فأخبروا بها أولياءهم، هذا كله لا صحة له، ولا يحكم فيه بأنهم يعلمون الغيب أبدًا، علم الغيب إلى الله ، لكن هناك أمور تقع في بعض البلدان فينقلها الجن بعضهم إلى بعض، أو شيء يسترق من السماء، كلمة يسمعونها من الملائكة إذا استرقوا السمع إلى السماء فينقلونها إلى أوليائهم من الإنس، فقد تكون حقًا سمعوه ما لبس عليهم فيه فيقع، ويظن الناس أن كل ما فعلوه، قالوا: صحيح، ويكذبون مع ذلك الكذب الكثير كما في الحديث: أنهم يكذبون معها مائة كذبة وفي بعض الروايات: يكذبون أكثر من مائة كذبة فلا يلتفت إليهم؛ لأن عمدتهم الكذب، أو الاستعانة بالجن في كذب الجن، وفيما يتعاطونه من الباطل الذي يشوشون به على الناس، نسأل الله العافية. والجن كالإنس فيهم الكافر، فيهم المبتدع، فيهم الفاسق، فيهم الطيب، فالفساق للفساق، والكفار للكفار، والطيبون للطيبين، فالجن الذين يخدمون بعض شياطين الإنس، بإخبارهم بعض المغيبات التي سمعوها من السماء، أو سمعوها من بعض البلدان، هؤلاء لأنهم خدموهم بعبادتهم من دون الله، والذبح لهم ونحو ذلك، فالجن الذين يخدمونهم بهذه الأخبار، وهذه الأسفار التي يكذبون فيها، وقد يصدقون فيها شيء قليل فيظنهم الناس صادقين في البقية، نعم.","link":"https://binbaz.org.sa/fatwas/13517/حكم-قراءة-الفنجان-والكف-والودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_662/nour_66204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15004,"question":"يقول صاحب الودع وقارئة الفنجان والرسل وقراءة الكف لنا، هل هي حرام أم حلال؟","title":"حكم قراءة الفنجان والكف والودع","answer":"الجواب: كل هذا بدع، كلها منكرة، لا صحة لها، صاحب الفنجان وقراءة الكف، ورمي الودع، أو ضرب الودع، أو بالحصى كله من تعاطي علم الغيب كله باطل، كله منكر ولا صحة له، بل هو دجل وكذب وافتراء، ويدعون علم الغيب بأشياء أخرى غير هذا كذب، وإنما يعتمدون على ما تقول لهم أصحابهم من الجن، فإن بعضهم يستخدم الجن ويقول ما تقوله له الجن، فيصدقون ويكذبون، يصدقون في بعض الأشياء التي اطلعوا عليها في بعض البلدان، أو استرقوها من السمع، ويكذبون في الغالب، والأكثر يكذبون، ويتحيلون على الناس، حتى يأخذوا أموالهم بالباطل، وهكذا الإنس الذين يخدمونهم، قد يكذبون أيضًا ويفترون ويقولون هذا كذا، وهذا كذا، وهم كذبة، إنما يأكلون أموال الناس بالباطل، وعلم الغيب لا يعلمه إلا الله . أما كلمة الرسل ما أدري إيش مراده بالرسل، كلمة الرسل هذا كلام مجمل، إن كان المقصود قراءة القرآن الذي جاء به الرسول ﷺ يقرؤه ويتدبر ما فيه لعله يجد شيئًا يستعين به على علاج المريض، يعني يتدبر القرآن لعله يجد شيئًا يعني يستعين به على علاج المريض بقراءة آية على المريض، أو ما أشبه ذلك، فهذا لا يحتاج إلى هذا الكلام، القرآن شفاء، فإذا قرأ من بعض الآيات آية الكرسي، أو الفاتحة أو قُل هُو اللّهُ أَحْدٌ [الإخلاص:1]  أو المعوذتين هذا طيب، وهذه من أسباب الشفاء، فتسمية الرسل ما أدري ما مراده.\nالمقدم: بالنسبة للرسل -بارك الله فيكم- يقول: يحكى أنه هناك إذا جاء لهم من يريد الاستفادة من صاحبة الودع وقارئة الفنجال إلى آخره أنهم يرسلون رسولًا يخبر عن هذا الشخص، يخبر أهله وأقاربه أنه بخير. الشيخ: هذا كلام ما له تعلق بالعلاج، إرسال الرسل جمع رسول إلى أهل المريض هذا ما له تعلق بالعلاج، سواء أرسلوا لهم، أو ما أرسلوا لهم، هذا شيء ماله تعلق بالعلاج، إنما هو متعلق بتطمينهم عن صحته، هذا شيء آخر، نعم. المقدم: هو يشتكي من كثرة هؤلاء في البلد، يعني: في بلده في السودان، ويقول: إذا تكرر تحقق ما يقولون، هل في هذا علم بالغيب أم لا؟ الشيخ: أبدًا، فهو كله باطل، ولكن قد يتكرر لأنهم شيء يعرفونه من بلادهم، مثل يخبرون عن إنسان فعل كذا، أو فعل كذا، وهم قد شاهدوه في البلاد الأخرى من السودان، أو أشياء خبرتهم بها جن أن هذا وقع في بلد كذا، وعمل له كذا، وصار كذا، فهم يأخذون عن الجن أخبارًا أدركها الجن في بعض البلدان، فأخبروا بها أولياءهم، هذا كله لا صحة له، ولا يحكم فيه بأنهم يعلمون الغيب أبدًا، علم الغيب إلى الله ، لكن هناك أمور تقع في بعض البلدان فينقلها الجن بعضهم إلى بعض، أو شيء يسترق من السماء، كلمة يسمعونها من الملائكة إذا استرقوا السمع إلى السماء فينقلونها إلى أوليائهم من الإنس، فقد تكون حقًا سمعوه ما لبس عليهم فيه فيقع، ويظن الناس أن كل ما فعلوه، قالوا: صحيح، ويكذبون مع ذلك الكذب الكثير كما في الحديث: أنهم يكذبون معها مائة كذبة وفي بعض الروايات: يكذبون أكثر من مائة كذبة فلا يلتفت إليهم؛ لأن عمدتهم الكذب، أو الاستعانة بالجن في كذب الجن، وفيما يتعاطونه من الباطل الذي يشوشون به على الناس، نسأل الله العافية. والجن كالإنس فيهم الكافر، فيهم المبتدع، فيهم الفاسق، فيهم الطيب، فالفساق للفساق، والكفار للكفار، والطيبون للطيبين، فالجن الذين يخدمون بعض شياطين الإنس، بإخبارهم بعض المغيبات التي سمعوها من السماء، أو سمعوها من بعض البلدان، هؤلاء لأنهم خدموهم بعبادتهم من دون الله، والذبح لهم ونحو ذلك، فالجن الذين يخدمونهم بهذه الأخبار، وهذه الأسفار التي يكذبون فيها، وقد يصدقون فيها شيء قليل فيظنهم الناس صادقين في البقية، نعم.","link":"https://binbaz.org.sa/fatwas/13517/حكم-قراءة-الفنجان-والكف-والودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_662/nour_66204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15170,"question":"هذه رسالة وردتنا من خميس مشيط من المستمع عبد بن حمد، يقول في رسالته: هل يجوز التداوي من عند الساحر أو الكاهن؟ وهل هذا يعد من الشرك المحبط للعمل أم لا؟","title":"ما حكم التداوي عند السحرة والكهان؟","answer":"الجواب: لا يجوز التداوي عند السحرة والكهنة؛ لأن النبي ﷺ نهى عن إتيان الكهنة والسحرة، قال: لا تأتوهم وقال -عليه الصلاة والسلام-: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، والعراف يطلق على الكاهن والمنجم والساحر والرمال وأشباههم، وقال ﷺ: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد -عليه الصلاة والسلام-، قال: ليس منا من سحر أو سُحر له، وليس منا من تكهن أو تُكهن له. فلا ينبغي للمؤمن أن يأتي العرافين، ولا الكهنة، ولا المنجمين، بل يحذرهم غاية الحذر، ولا يجوز سؤالهم، ولا تصديقهم، سؤالهم منكر، وليس من الشرك، لكنه منكر، وتصديقهم في علم الغيب إذا صدقهم بأنهم يعلمون الغيب هذا كفر أكبر؛ لأن علم الغيب إلى الله ، فمن زعم أن أحدًا يعلم الغيب الرسول ﷺ أو غيره فهو كافر؛ لأن علم الغيب إلى الله ، قال تعالى: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] فالغيب عنده  ليس إلى غيره، نعم.","link":"https://binbaz.org.sa/fatwas/13677/ما-حكم-التداوي-عند-السحرة-والكهان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65907.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15530,"question":"هذا سائل من جازان نور الدين، يقول في هذا  هل تجوز الصلاة خلف رجل يؤمن بالدجالين والعرافين؟ علمًا بأنه مواظب على الصلاة، ويصوم رمضان ويفعل الخير.","title":"حكم الصلاة خلف من يصدق الدجالين والعرافين","answer":"الجواب: من يصدق الكهنة والعرافين والمنجمين لا يصلى خلفه، وينصح ويعلم، أنه لا يجوز له تصديقهم، ولا إتيانهم، ولا سؤالهم، فإذا أصر على ذلك ولم يبال، لا يصلى خلفه، بل هو على خطر؛ لأن الرسول -عليه الصلاة والسلام- قال: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول، فقد كفر بما أنزل على محمد -عليه الصلاة والسلام- وفي اللفظ الآخر: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة ولم يصدقه مجرد سؤال، فكيف إذا صدقه؟! لأن التصديق يقتضي أنه يؤمن بأنه يعلم الغيب، والذي يقول: إن أحدًا يعلم الغيب سوى الله هو كافر.  فالواجب الحذر من تصديق الكهان والعرافين، والحذر من سؤالهم، ومن كان لا يبالي بهذا، بل يصدقهم ويسألهم لا يصلى خلفه، نسأل الله العافية. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14066/حكم-الصلاة-خلف-من-يصدق-الدجالين-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56923.mp3","categories":["صلاة الجماعة","السحر والكهانة"]},{"id":15753,"question":"يقول: إن أبي وعمي يذهبون إلى السحرة ويصدقونهم، وقد نهيتهم عن ذلك، ولكن لم يستجيبوا لنهيي، فكيف لي وأنا ساكن معهم؟جزاكم الله خيرًا.","title":"التحذير من إتيان السحرة وتصديقهم","answer":"الجواب: الواجب عليك الاستمرار في النصيحة لهم، تحذرهم من ذلك، فإن امتنعوا فينبغي لك، بل الواجب عليك الخروج منهم، والانتقال إلى محل آخر؛ لقول النبي ﷺ في الحديث الصحيح: ليس منا من سحر أو سحر له وقوله ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، وقوله ﷺ: من أتى عرافًا، أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، هذا وعيد عظيم، والساحر من العرافين، وأشد من الكهنة، وأخبث، فيجب الحذر من المجيء إليه، ومن سؤاله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14343/التحذير-من-اتيان-السحرة-وتصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74105.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16192,"question":"من محافظة حمص في الجمهورية العربية السورية، المستمع (ح. م. م) رسالة وضمنها جمعًا من الأسئلة، في سؤاله الأول يقول: هل صحيح أن بعض الناس يجتمعون مع الجن، ويتكلمون معهم، وهل للجن تأثير على المؤمن؟","title":"هل يجتمع الجن بالأنس؟ وهل لهم تأثير على المؤمن؟","answer":"الجواب: قد يجتمع بعض الناس مع الجن، قد يكون له اختلاط بهم، وخدمة لهم في عبادتهم من دون الله، أو الذبح لهم، أو النذر لهم، فيخدمونه، فالمقصود أنه قد يجتمع بالجن، والجن ثقل عظيم، خلقهم الله للعبادة، قال تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] فهم مأمورون بعبادة الله وطاعته، كما أن الإنس مأمورون بذلك، وبعض الناس قد يخدمهم، ويعبدهم من دون الله؛ ليقضوا له بعض الحوائج، فيكون قد أشرك بالله، وعبد معه سواه . وقد يتراؤون لبعض الناس في بيته، أو في السفر، أو في أي مكان يبرزون للناس، ولكن الغالب أنهم يروننا، ولا نراهم، كما قال -جل وعلا-: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ [الأعراف:27] وطاعتهم في المعاصي مثل طاعة الإنس محرمة، لا يجوز طاعتهم في المعاصي، وعبادتهم شرك بالله . فإذا طلبوا من الإنسي أن يضرب أحدًا، أو يأخذ مال أحد، يعطيهم مال أحد؛ فهذا من الظلم، وإذا تقرب إليهم بذلك، بالمال، أو بالذبح، أو بالدعاء؛ صار شركًا أكبر، نسأل الله العافية. وكان أهل الجاهلية يستعينون بالجن، إذا نزلوا الأودية؛ خافوا منهم، وقالوا: نعوذ بعزيز هذا الوادي من سفهاء قومه، فأنكر الله عليهم ذلك في قوله سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] في سورة قل أوحي إلي يقول سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] فلا يجوز الاستعانة بالجن، ولا دعاؤهم، ولا الاستغاثة بهم، ولا الذبح لهم، ولا النذر لهم، كل هذا من الشرك بالله. أما كونهم قد يسمع أصواتهم، أو قد يجتمع بهم، أو قد يخدمهم؛ فهذا يقع لبعض الناس، قد يقع لعباد القبور، عباد الشياطين، قد يجتمعون بهم، ويخدمونهم، كل طائفة تخدم الأخرى، نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا، إذًا لهم تأثير على المؤمن كما يسأل أخونا؟ الجواب: نعم، قد يلتحق الجني بالإنسي فيصرعه، يدخل فيه، يشتمل عليه؛ فيكون مجنونًا بسبب ذلك، ويؤذيه بذلك، يكون ظالمًا له، وهذا موجود كثيرًا، مثلما قال ﷺ في الحديث الصحيح، يقول النبي ﷺ: إن الشيطان يجري من ابن آدم مجرى الدم قد يكون يدخل فيه، يعني: يلتبس به حتى يتكلم على لسانه، قد يكون رجلًا، قد يكون امرأة، قد يكون مسلمًا، قد يكون كافرًا، فالمسلم يكون ظالمًا متعديًا، والكافر معروف ظلمه وشره. وينبغي علاجه، وتذكيره بالله، وتحذيره من الظلم، فالمسلم قد يخرج بسهولة، يخاف الله إذا ذكر ويخرج، وبعض المسلمين من الجن قد يكون فيه ظلم، وشر كثير، لا يخرج إلا بتعب، والكافر كذلك قد لا يخرج لظلمه وكفره، ولكن مع القراءة قراءة القرآن، والتعوذات الشرعية يخرج -بإذن الله- في الغالب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14877/هل-يجتمع-الجن-بالانس-وهل-لهم-تاثير-على-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80609.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16209,"question":"من محافظة حمص في الجمهورية العربية السورية، المستمع (ح. م. م) رسالة وضمنها جمعًا من الأسئلة، في سؤاله الأول يقول: هل صحيح أن بعض الناس يجتمعون مع الجن، ويتكلمون معهم، وهل للجن تأثير على المؤمن؟","title":"هل يجتمع الجن بالأنس؟ وهل لهم تأثير على المؤمن؟","answer":"الجواب: قد يجتمع بعض الناس مع الجن، قد يكون له اختلاط بهم، وخدمة لهم في عبادتهم من دون الله، أو الذبح لهم، أو النذر لهم، فيخدمونه، فالمقصود أنه قد يجتمع بالجن، والجن ثقل عظيم، خلقهم الله للعبادة، قال تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] فهم مأمورون بعبادة الله وطاعته، كما أن الإنس مأمورون بذلك، وبعض الناس قد يخدمهم، ويعبدهم من دون الله؛ ليقضوا له بعض الحوائج، فيكون قد أشرك بالله، وعبد معه سواه . وقد يتراؤون لبعض الناس في بيته، أو في السفر، أو في أي مكان يبرزون للناس، ولكن الغالب أنهم يروننا، ولا نراهم، كما قال -جل وعلا-: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ [الأعراف:27] وطاعتهم في المعاصي مثل طاعة الإنس محرمة، لا يجوز طاعتهم في المعاصي، وعبادتهم شرك بالله . فإذا طلبوا من الإنسي أن يضرب أحدًا، أو يأخذ مال أحد، يعطيهم مال أحد؛ فهذا من الظلم، وإذا تقرب إليهم بذلك، بالمال، أو بالذبح، أو بالدعاء؛ صار شركًا أكبر، نسأل الله العافية. وكان أهل الجاهلية يستعينون بالجن، إذا نزلوا الأودية؛ خافوا منهم، وقالوا: نعوذ بعزيز هذا الوادي من سفهاء قومه، فأنكر الله عليهم ذلك في قوله سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] في سورة قل أوحي إلي يقول سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] فلا يجوز الاستعانة بالجن، ولا دعاؤهم، ولا الاستغاثة بهم، ولا الذبح لهم، ولا النذر لهم، كل هذا من الشرك بالله. أما كونهم قد يسمع أصواتهم، أو قد يجتمع بهم، أو قد يخدمهم؛ فهذا يقع لبعض الناس، قد يقع لعباد القبور، عباد الشياطين، قد يجتمعون بهم، ويخدمونهم، كل طائفة تخدم الأخرى، نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا، إذًا لهم تأثير على المؤمن كما يسأل أخونا؟ الجواب: نعم، قد يلتحق الجني بالإنسي فيصرعه، يدخل فيه، يشتمل عليه؛ فيكون مجنونًا بسبب ذلك، ويؤذيه بذلك، يكون ظالمًا له، وهذا موجود كثيرًا، مثلما قال ﷺ في الحديث الصحيح، يقول النبي ﷺ: إن الشيطان يجري من ابن آدم مجرى الدم قد يكون يدخل فيه، يعني: يلتبس به حتى يتكلم على لسانه، قد يكون رجلًا، قد يكون امرأة، قد يكون مسلمًا، قد يكون كافرًا، فالمسلم يكون ظالمًا متعديًا، والكافر معروف ظلمه وشره. وينبغي علاجه، وتذكيره بالله، وتحذيره من الظلم، فالمسلم قد يخرج بسهولة، يخاف الله إذا ذكر ويخرج، وبعض المسلمين من الجن قد يكون فيه ظلم، وشر كثير، لا يخرج إلا بتعب، والكافر كذلك قد لا يخرج لظلمه وكفره، ولكن مع القراءة قراءة القرآن، والتعوذات الشرعية يخرج -بإذن الله- في الغالب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14877/هل-يجتمع-الجن-بالانس-وهل-لهم-تاثير-على-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80609.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16251,"question":"يسأل سؤالًا ربما يكون فيه شيء من الغرابة، يقول: ما الفرق بين الجن، والشياطين؟","title":"ما الفرق بين الجن والشياطين؟","answer":"الجواب: الجن: من.. جنس الجن، هم الثقل الثاني من المخلوقات، مثل الإنس يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] الجن: هم جنس من المخلوقات، خلقهم الله لعبادته كالإنس. والشياطين: المردة منهم، الشيطان وذرية المردة، وهكذا شياطين الإنس مثل ذلك، الشياطين يكونون من الجن، ويكونون من الإنس، فالشيطان الإنسي، والشيطان الجني داخل في الشياطين، كما قال تعالى: وَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الإِنسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ [الأنعام:112]. فالمقصود: أن الشياطين يكونون من الجن والإنس، وهم المردة المتعدون لحدود الله، يقال لهم: شياطين، والشيطان الذي هو أبو الجن، هو رأسهم، وهكذا من تمرد من ذريته، وتعدى الحدود؛ هو شيطان، ومن استقام على أمر الله؛ فليس من الشياطين، بل من المؤمنين، كما قال تعالى في الجن: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ كُنَّا طَرَائِقَ قِدَدًا[الجن:11] وقال أيضًا عن الجن: وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَ فَمَنْ أَسْلَمَ فَأُوْلَئِكَ تَحَرَّوْا رَشَدًا ۝ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا [الجن:14-15]، فهو فيهم المسلم والكافر .. فيهم المبتدع والسني.. فيهم الرافضي والسني.. فيهم الشيوعي.. فيهم المعتزلي والجهمي، مثلما في الإنس، نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14958/ما-الفرق-بين-الجن-والشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16496,"question":"هذا سائل يقول سماحة الشيخ: كيف يتقي الإنسان السحر قبل وقوعه؟ وما العلاج في ذلك مأجورين؟","title":"أسباب الوقاية من السحر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن المشروع لكل مسلم أن يتقي الشر بالتعوذات الشرعية التي شرعها الله لعباده، السحر وغيره، فهو مأمور بالتعوذ بالله، ومن ذلك: التعوذ بكلمات الله التامات من شر ما خلق، ثلاث مرات صباحًا ومساءً، ومن ذلك قوله: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع العليم، ثلاث مرات صباحًا ومساءً، كل هذا من أسباب العافية من كل سوء كما جاءت به الأحاديث عن رسول الله، عليه الصلاة والسلام. ومن ذلك قراءة آية الكرسي بعد كل صلاة، وعند النوم، هي من أسباب العافية أيضًا والسلامة، ومن ذلك قراءة قل هو الله أحد والمعوذتين صباحًا ومساءً ثلاث مرات من أسباب العافية من كل شر، وقراءة هذه السور الثلاث عند النوم مع النفث في الكفين عند النوم، والمسح على الرأس والوجه والصدر، كل هذا من أسباب العافية من كل سوء من السحر وغيره. وهكذا بقية الدعاء: اللهم إني أسألك العافية في الدنيا والآخرة كما في الحديث يقول ﷺ: سلوا الله العافية في الدنيا والآخرة، فما أعطي أحد خيرًا وأفضل من العافية أو كما قال -عليه الصلاة والسلام- اللهم إني أعوذ بك من الشر كله، اللهم إني أعوذ بك من كل داء، أعوذ بك من كل ما يسخطك، أو اللهم إني أعوذ بك من كل ما يضرني. المقصود: يتعوذ بالله من كل شر، لكن استعمال التعوذات الشرعية والتي في الشرع يكون أفضل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15212/اسباب-الوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58301.mp3","categories":["الأدعية والأذكار","السحر والكهانة"]},{"id":16880,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في أولها: أنا الشاب المسلم صلاح الدين الشبيب من الجمهورية العربية السورية، أخونا له جمع من الأسئلة من بينها سؤال يقول: هل يستطيع الساحر الاتصال بالشياطين كما يزعم فعلًا، وبالتالي يستطيع أن يغير ما يريده الشخص المسلم الواعي، والذي يحفظ قدرًا كبيرًا من القرآن، وذلك بواسطة هؤلاء الشياطين، وإن كان ذلك ممكن، فماذا يترتب على الشخص أن يفعل إذا ابتلي بالسحر؟ أفيدونا جزاكم الله خيرًا.","title":"طرقة الوقاية من السحر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالسحر بينه الله -جل وعلا- في كتابه العظيم، وهكذا الرسول ﷺ أنه موجود، وأن السحرة موجودون، وأن الشياطين هم الأساتذة، هم الذين يعلمونهم السحر، الشياطين، شياطين الجن هم الذين يعلمون شياطين الإنس السحر، والسحر يكون بالرقى الشيطانية، والتعوذات الشيطانية، والعقد والنفث، كما قال تعالى: وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ [الفلق:4] يعني: السواحر اللاتي ينفثن في العقد بكلمات ضالة خاطئة، يردن بها إيذاء المسحور. ويقع بالتخييل، كما قال تعالى: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فيخيلون للإنسان أن الحبل حية، والعصا حية، والكلب نوع آخر، والقط نوع آخر، إلى غير ذلك، يسميه العامة التذمير، يعني يذمر على العيون، كما قال -جل وعلا-: فَلَمَّا أَلْقَوْا سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ [الأعراف:116] وسحروا أعين الناس، أي: لبسوا عليهم حتى صار الإنسان ينظر الشيء على غير وجهه، ويظنه غير المعروف؛ بسبب ما وقع من التلبيس الذي شوش على العين، حتى ظن الناس أن الحبال، والعصي بسبب سحرة فرعون ظنوا أنها حيات، واعتقدوا أنها حيات. والساحر يتلقى من الشياطين، قال تعالى: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102]. هكذا بين  ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ [البقرة:102] يعني: ويعلمونهم ما أنزل على الملكين بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ [البقرة:102] يعني: الملكين هاروت وماروت حَتَّى يَقُولا [البقرة:102] للمتعلم، يقولا للمتعلم،إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102]، يعني: أن الملكين مبتلى بهما الناس، فلا تكفر بتعاطي السحر، فدل ذلك على أن تعاطي السحر كفر بعد الإيمان، وردة بعد الإسلام إذا كان مسلمًا؛ لأنه لا يتوصل إليه إلا بعبادة الشياطين، التقرب إليهم بالذبح، والنذر، والاستغاثة، والسجود لهم، ونحو ذلك. فيكون الساحر بهذا كافرًا مرتدًا؛ لكونه يتعاطى مع الشياطين ما هو من حق الله من العبادة، ولهذا قال -جل وعلا-: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا [البقرة:102] أي: ينصحاه حتى يقولا له: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا [البقرة:102] أي: من هاروت وماروت. مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102] يعني: يتعلمون من الملكين أشياء من السحر، تلبس على الزوج والزوجة، حتى يعتقد الزوج أن المرأة غير امرأته، شانت حالها، وتغيرت حالها، حتى يبغضها، ويطلقها، وهكذا المرأة يلبس عليها ... عليها، ويسحر عينها بالنسبة إلى زوجها، حتى تتخيل أنه غير زوجها، وأن صورته تغيرت، وأن حاله تغيرت؛ فتنكر، فتنكره، وتطلب الفراق.  قال تعالى: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] أي: لا يقع السحر إلا بإذن الله، يعني: بإذن الله الكوني القدري، لا الشرعي؛ لأن الله سبحانه ما أذن فيه شرعًا، بل حرمه، وحذر منه، ولكنه يقع بإذنه الكوني القدري، كل شيء بقدره، الكفر والإيمان، والسحر، والقتل، والأكل والشرب، والموت، والحياة كلها بقدر، كلها بإذن الله القدري، ولهذا قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ. ثم قال : وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ [البقرة:102] دل على أن السحر يضر، ولا ينفع، والمضرة على الساحر، وعلى المسحور جميعًا، وأن شره عظيم، وقدره الله لحكمة بالغة، وابتلاء وامتحان. ثم قال سبحانه: وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ [البقرة:102] يعني: اعتاظه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ  يعني: من حظ، ولا نصيب، وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ يعني: باعوا، ما شرى معنى باع وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ يعني: باعوا أنفسهم على الشيطان لَوْ كَانُوا يَعْلَمُونَ [البقرة:102] ثم قال سبحانه: وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:103]. فدل على أن السحر ضد الإيمان والتقوى، وضد الآخرة، فوجب على كل إنسان أن يحذره، على كل مسلم أن يحذر السحر، وأن يتباعد عنه، وعن أسبابه، وعن أهله، وفي إمكان المؤمن أن يتعوذ بالله من شر السحرة، ويبتعد عنهم بالاعتصام بحبل الله، والاستقامة على دين الله، وعدم الركون لهم، وعدم التعلم منهم، ويتحرز من ذلك بالأشياء المشروعة: مثل آية الكرسي عند النوم، وبعد كل صلاة، ومثل: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] بعد كل صلاة، وبعد المغرب، والفجر ثلاث مرات، وعند النوم ثلاث مرات، كل هذا من أسباب السلامة من السحر. وهكذا كونه يقول: أعوذ بكلمات الله التامات من شر ما خلق هذا أيضًا من الأسباب، من أسباب العافية، فالمؤمن يتحرز من كل شر بما شرعه الله، ومن ذلك السحر؛ فإنه شر عظيم، وخطره كبير. فالواجب على المؤمن أن يحذر كل شر، وأن يتعاطى الأسباب التي جعلها الله أسبابًا للسلامة، ويعلم أن الأمر بيد الله  فلا يضرك ساحر، ولا غيره إلا بإذن الله، فالجأ إلى الله، واستقم على دينه، والتزم التعوذات الشرعية، والأسباب الشرعية، وبه تسلم -بإذن الله- ولا يضرك السحرة، ولا الشياطين. ومن أسباب السلامة: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، صباحًا، ومساءً، باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات، صباحًا، ومساءً، هذه من أسباب السلامة من كل شر، أعيدها: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، صباحًا ومساء، من أسباب العافية من كل سوء.  جاء رجل إلى النبي ﷺ فقال: لدغتني عقرب البارحة، فقال: أما إنك لو قلت: أعوذ بكلمات الله التامات من شر ما خلق لم تضرك وقال ﷺ: من نزل منزلًا، فقال: أعوذ بكلمات الله التامات من شر ما خلق؛ لم يضره شيء حتى يرتحل من منزله ذلك وقال ﷺ: من قال: باسم الله الذي لا يضر مع اسمه شيء، في الأرض، ولا في السماء، وهو السميع العليم، ثلاث مرات صباحًا؛ لا يضره شيء حتى يمسي، وإن قالها مساءً؛ لم يضره شيء حتى يصبح.  هذه نعمة من الله  فعليك يا عبد الله! أن تجتهد في التعوذات الشرعية، والأسباب المرعية، وبذلك تسلم من شر أعدائك، ومكائد أعدائك من الشياطين، ومن السحرة، ومن غيرهم، والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71] فأنت مأمور بأخذ الحذر من كل سوء، مما يضرك في الدنيا، ومما يضرك في الآخرة، بالتحرزات الشرعية، والأسباب المرعية، في جميع الأحوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15635/طرقة-الوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82501.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17451,"question":"هذا السائل أحمد الرفاعي له مجموعة من الأسئلة يقول: كثر في هذه الأيام التحدث عن السحر -أعاذنا الله منه وإياكم- فما هي الوقاية الصحيحة من القرآن والسنة حول هذا الأمر؟ جزاكم الله خيرًا سماحة الشيخ.","title":"كيفية الوقاية من السحر","answer":"الجواب: السحر يقع، معروف، يعني: لا شك أنه قد يقع من بعض الناس، والساحر مشرك يجب قتله إذا عرف -نسأل الله العافية- وقد أمر عمر  أمراءه أن يقتلوا السحرة، يروى عن النبي ﷺ أنه قال: حد الساحر ضربه بالسيف؛ لأنه كافر، ويدعو إلى الكفر، وأما التوقي، فالتوقي بالتعوذ بكلمات الله التامات من شر ما خلق، كونه يتعوذ صباحًا ومساء بكلمات الله التامات من شر ما خلق ثلاث مرات، باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء وهو السميع العليم ثلاث مرات صباحًا ومساء كما جاءت الأحاديث بذلك، من أتى بهذا؛ كفاه الله شر كل شيء، أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات صباحًا ومساء: باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات.  كذلك قراءة قل هو الله أحد والمعوذتين صباحًا ومساء ثلاث مرات من أسباب السلامة من السحر، وغيره ثلاث مرات قل هو الله أحد [الإخلاص: 1] قل أعوذ برب الفلق [الفلق: 1] قل أعوذ برب الناس [الناس: 1] صباحًا ومساء. وهكذا عند النوم يقرأها ثلاث مرات، آية الكرسي عند النوم من أسباب السلامة من السحر والشيطان، قراءتها بعد كل صلاة، كل هذا من أسباب العافية والسلامة، نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين، شكر الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16320/كيفية-الوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77208.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17485,"question":"يقول هذا السائل من سوريا رمز لاسمه بـ (ح. م. س): أستفسر في سؤالي عن الآتي: هل يجوز للمؤمن أن يذهب إلى العراف أو إلى عراف من أجل مشكلة ما اشتكى منها، علمًا بأن هذا العراف يفتتح بالقرآن الكريم، فأريد منكم التوجيه مأجورين؟","title":"حكم إتيان العرافين وسؤالهم","answer":"الشيخ: العرافون: هم الذين يدعون علم المغيبات وعلم الحوادث بطرق غير شرعية، هؤلاء لا يؤتون يقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة رواه مسلم في الصحيح، ويقول ﷺ: من أتى عرافًا أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فلا يجوز إتيان العرافين، ولا الكهنة، ولا المنجمين، ولا السحرة، ولا يجوز سؤالهم، ولا تصديقهم، بل يجب الحذر منهم، والإنكار عليهم، ورفع أمرهم إلى الجهات المسئولة حتى يعاقبوا بما يستحقون. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16394/حكم-اتيان-العرافين-وسوالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77317.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17706,"question":"هذا السائل أبو عبد الله يقول: القرآن فيه شفاء للناس ورحمة نرجو أن تذكروا الآيات التي يشرع قراءتها على المريض وعدد المرات وكيفية النفث جزاكم الله خيرًا؛ لأن عندنا شخص مصاب بمرض ونريد أن نقرأ عليه؟","title":"الآيات والسور التي يرقى بها المريض","answer":"الجواب: كل القرآن شفاء من أوله إلى آخره، وإذا قرأ الفاتحة فهي أعظم سورة في القرآن ... كررها كما قرأها الصحابة على اللديغ لما مروا عليه في بعض أحياء العرب قرأ عليه بعض الصحابة بسورة الفاتحة وكررها فشفاه الله، فإذا قرأ سورة الفاتحة وقرأ معها آية الكرسي أو بعض الآيات الأخرى كله طيب، وإذا قرأ قل هو الله أحد وقل أعوذ برب الفلق وقل أعوذ برب الناس ثلاث مرات كان حسنًا أيضًا من أسباب الشفاء، وكل القرآن شفاء إذا قرأ منه ما يسر الله من البقرة.. من آل عمران.. من النساء.. من المائدة، من بقية القرآن كله شفاء، كما قال الله جل وعلا: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44]، وقال سبحانه: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ[الإسراء:82] يعني: كله شفاء، فإذا تحرى بعض الآيات وقرأها كله طيب، ولكن من أهم ما يقرأ الفاتحة وآية الكرسي، وقل هو الله أحد، وسورة المعوذتين هذه من أهم ما يقرأ على المريض. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16666/الايات-والسور-التي-يرقى-بها-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77618.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":17775,"question":"هذا السائل محمد (و) يقول: ما العلامات التي يعرف بها الساحر والكاهن والمشعوذ؟","title":"علامات الساحر والكاهن وغيرهما","answer":"الجواب: يعرفون بما يقولون من الكلام الباطل والأعمال الباطلة، يعرفون بدعواهم الباطلة المخالفة للشرع، فهذا دليل ظاهر يعني، فيعرف المشعوذ والكاهن والرمال والمنجم والساحر بأعمالهم التي يعملونها، كل واحد يعرف بعمله، فالذي يدعي علم الغيب أو يدعي أشياء لا أساس لها، هذه من الدلائل على أنه يستخدم الجن ويستعين بالجن، أو كذاب يكذب على الناس لأكل أموالهم.\nوهكذا الذي يستعمل أشياء تضر الناس، فهذا ينبغي أن يرفع أمره إلى الجهة المختصة كالهيئة والمحكمة؛ لأنه قد يتعاطى السحر وقد يتعاطى أشياء تضر الناس بغير علم؛ لجهله وعدم بصيرته.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16758/علامات-الساحر-والكاهن-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59627.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":18198,"question":"يسأل أخونا ويقول: يوجد في منطقتنا شخص يسكن في بيت وحده، ويدعي وجود الجان في بيته، ولا يستطيع -حسب قوله - إشعال النور ليلًا ويغمض عينيه في أغلب الأحيان، وقد زار منزله بعض من يدعي معرفة الجان، وقالوا: إن البيت فعلًا يسكنه الجان، يأكلون معه، وهناك جنية تصحبه دائمًا، فهل حقيقة أن الجان تتحكم في بعض الناس بهذه الطريقة؟ وهل في شريعتنا الغراء ما يتم به طرد الجان من مثل هذا البيت أرجو الإفادة، جزاكم الله خيرًا.والسلام عليكم ورحمة الله.","title":"حكم من يتعامل مع الجن ويدعي مصاحبتهم","answer":"الجواب: نعم، نعم، قد يقع هذا لبعض الناس، قد يصحبه الجان، قد يضلونه، وقد يغرونه بأشياء تضر الناس، قد يعطونه بعض العلوم المغيبة التي اطلعوا عليها باستراق السمع أو بمجيئهم من بلدان أخرى، كأن يخبروه بأنه مات أمير البلد أو مات فلان في البلد الفلانية؛ لأن الشياطين يخبر بعضهم بعضًا، وهم سريعو التنقل من بلد إلى بلد، قد يسترقون السمع ويسمعون شيئًا من الملائكة في السماء أو في العنان في سماء الدنيا أو في العنان فيبلغون أولياءهم من الإنس. فالإنسي قد يكون له صاحب من الجن يسمونه الرائي، أهل الجاهلية، ويسمى صاحبه الكاهن، فهذا واقع من قديم الزمان، وكل إنسان معه شيطان، ومعه ملك قرين، قد يكون الشيطان الذي مع الإنسان يصحب هذا ويدعوه إلى الحضور، قد يتعاون معه على مقاصدهم الخبيثة مع هذا الرجل أو مع هذه المرأة، هذا واقع في الناس صحبة الجن واتخاذهم أولياء والاستعانة بهم على ضرر بعض الناس أو نفع بعض الناس كل هذا واقع، ولكنه منكر لا يجوز محرم لا يجوز للمسلم أن يتخذهم أصحاب من طريق الكهانة أو طريق السحر حتى يضر بهم الناس، بل يجب أن يحذرهم. ويجب على المسلمين أن يجاهدوا هؤلاء بما يزيل شرهم، ولي الأمر يبعث لهم من يستتيبهم فإن تابوا ورجعوا إلى الحق والصواب وإلا عذبهم وعاقبهم بالضرب والسجن حتى يتركوا هذه الشعوذة، وهذا الفساد، وإذا علم منهم أنهم يدعون الجن ويستغيثون بالجن ولهم ينذرون صار هذا شركًا أكبر يستحقون معه القتل، أو علم منهم أنهم يدعون علم الغيب بسبب شياطينهم، وأنهم يعلمون الغيب وأنه سوف يكون كذا وسوف يكون كذا، فهم يستتابون أيضًا فإن تابوا وإلا قتلوا كفارًا؛ لأن دعوى علم الغيب كفر كما قال الله سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65]، وقال سبحانه: وَلِلَّهِ غَيْبُ السَّمَوَاتِ وَالأَرْضِ [هود:123]، قال الله  لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188]، فإذا كان محمد ﷺ وهو أفضل الخلق وسيد ولد آدم لا يعلم الغيب، فغيره من باب أولى. فالواجب القضاء على هذه الشعوذة وعلى هذا الشخص الذي يفعل ما ذكرت من جلوسه وحده، ودعواه أنه له جنية، وأنه لا ينور في بيته في الليل، وأنه يغمض عينيه، هذا كله من باب إيهام الناس وأخذ أموالهم بالباطل حتى يقول لهم: افعلوا كذا وافعلوا كذا وسوف يكون كذا وسوف يكون كذا، هذا لا يجوز إقراره على حاله عند من له أدنى تمسك بالشرع من الولاة، بل الواجب على ولاة الأمور الإسلاميين أن يأخذوا على أيدي هؤلاء، وأن يقضوا على خرافاتهم وشعوذتهم وإفكهم. ومعلوم إذا كان صادقًا أنه يزول عن هذا، إذا تاب إلى الله ورجع إلى الحق وتاب إلى ربه من هذه الأشياء فإنها تبتعد عنه، فإنها تنزل على كل أفاك أثيم، وكذاب أثيم على أصحابهم، فإذا تاب رجع إلى الله وصدق واستعاذ بالله من شرهم كفاه الله شرهم. ومن أسباب الوقاية كثرة قراءة القرآن والتعوذ بكلمات الله التامات من شر ما خلق، إذا دخل المنزل، وأن يقول صباح ومساء: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات فإنه لا يضره شيء، وهكذا إذا قال: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات إذا دخل المنزل، كل هذا من أسباب العافية والسلامة من هؤلاء الأشرار من الشياطين شياطين الإنس والجن، ولا يجوز أن يقر هذا الشخص وأشباهه على هذا الباطل وهذه الشعوذة المنكرة التي يضل بها الناس ولاسيما الجهال. والله المستعان. نعم. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17235/حكم-من-يتعامل-مع-الجن-ويدعي-مصاحبتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90705.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":18421,"question":"يقال: إن وضع لبان النار في أوقات الغروب والشروق يبعد الشياطين من البيت، هل هذا صحيح؟","title":"مدى صحة أن لبان النار يطرد الشياطين من البيت","answer":"الجواب: ما بلغني شيء في هذا، أقول: لا أعلم شيئًا في هذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17501/مدى-صحة-ان-لبان-النار-يطرد-الشياطين-من-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73306.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":18705,"question":"ما هي عقوبة الذي يتعامل بالسحر ويؤذي الناس، ما هي عقوبته في الدنيا والآخرة سماحة الشيخ؟","title":"عقوبة الساحر في الدنيا والآخرة","answer":"الجواب: إذا علم أنه ساحر فهو مشرك، عقوبته القتل في الدنيا، وفي الآخرة النار إذا مات على سحره ولم يتب، يقول الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ[البقرة:102] فدل على أن السحر كفر. فالواجب على من يتعاطاه التوبة إلى الله، فإن مات على سحره صار كافرًا من أهل النار؛ لأن السحر من آثار دعاء الشياطين، والاستغاثة بالشياطين، واللجأ إليهم، فهو كفر لما يترتب عليه من دعاء الجن، والاستغاثة بالجن - والعياذ بالله -، هذا هو الواجب من جهة الآخرة. أما من جهة الدنيا فالواجب على ولاة الأمور إذا عرفوا الساحر أن يقتل حد الساحر ضرب بالسيف أمر عمر بقتل السحرة، أمر عماله في الشام أن يقتلوا السحرة، وحفصة كان عندها جارية سحرتها فقتلتها، الساحر يقتل في الدنيا، وإذا مات على سحره مات كافرًا، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17820/عقوبة-الساحر-في-الدنيا-والاخرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78813.mp3","categories":["الجنايات والحدود","السحر والكهانة"]},{"id":19138,"question":"السؤال الأخير الذي نعرضه من رسالة أخينا من الخبر، هو عن حكم من يزور الأولياء أو السادة ويطلب منهم حاجته أو يكون عنده مريض مصروع، علمًا أن الأولياء يذبحون للجن؟ وما حكم من اضطر إلى ذلك بسبب الصرع، أي: الجنون؟ وما حكم من يعمل المحبة والكراهية بين الزوجين؟","title":"حكم دعاء الأولياء وسؤال الكهنة والتولة","answer":"الجواب: هذه أمور خطيرة، فإن زيارة الأولياء والصالحين أو الأنبياء ليطلبهم ويستغيث بهم، وينذر لهم، هذا الشرك الأكبر، وهكذا من يسمون السادة كونه يزورهم ليستغيث بهم، أو ليسألهم المدد والعون عند قبورهم، أو بعيدًا من قبورهم كل هذا منكر، كل هذا من الشرك الأكبر، فالذي يستغاث به والذي يطلب الشفاء هو الله وحده  . أما الذهاب إلى السادة أحياءً أو أمواتًا يطلب منهم أن يشفوا مريضه، ويعتقد فيهم أنهم يشفون المرضى، وأن لهم سرًا، أو يطلب منهم عند قبورهم أو يسألهم المدد والعون، أو شفاء المريض، أو إغناء الفقير، أو ردع الظالم، أو ما أشبه ذلك من الأمور، هذا معناه يعتقد فيهم أنهم يتصرفون، فيكون كفرًا أكبر، وهذا عمل المشركين مع اللات والعزى نعوذ بالله من ذلك، فالواجب الحذر من هذا، والبعد عنه؛ لأنه شرك أكبر. وهكذا الذبح للجن، والتقرب إليهم بالذبائح شرك أكبر، أو الذبح لأصحاب القبور، كـالبدوي والحسين، أو ابن علوان، أو الشيخ عبد القادر الجيلاني أو غيرهم ممن قبلهم أو بعدهم، كونه يذبح لهم ويتقرب إليهم ليشفوا مريضه، أو ليقضوا حاجته، أو ليدفعوا عنه الظلم، أو يردوا ضالته أو ما أشبه ذلك كل هذا من الشرك الأكبر، وهكذا قوله: المدد المدد، المدد المدد، هذا من الشرك الأكبر، نسأل الله السلامة. هكذا سؤال من يدعي الكهانة عن حاجات هذا لا يجوز أيضًا، فإن صدقه في دعوى علم الغيب، كان شركًا أكبر، فإنه وجد من يدعي علم الغيب بواسطة النجوم، والنظر في سيرها واجتماعها وافتراقها، وهذا يسمى المنجم، فهذا إذا صدقه في دعوى علم الغيب كان كفرًا أكبر. وهكذا الكاهن الذي له رئي من الجن، أصحاب من الجن، يستخبرهم ويسألهم، فإذا صدقه الإنسان فقد كفر بما أنزل على محمد عليه الصلاة والسلام؛ لأن الرسول ﷺ قال: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ يعني: صدقه في علم الغيب؛ لأن هؤلاء يدعون علم الغيب، بما يحصل لهم من الأخبار من أصحابهم من الجن، فيظن الظان أن عندهم شيئًا من علم الغيب، فيصدقهم فيما يدعون، وهذا خطر عظيم، أخبر النبي ﷺ عن أصحابه أنهم كفار بما أنزل على محمد عليه الصلاة والسلام. وهكذا من يتعاطى أسباب العطف والمحبة، يعني: يتعاطى أشياء يسمونها الصرف والعطف، يعني: يحبب الرجل لامرأته، والمرأة إلى زوجها، وهو نوع من السحر، ويسمى التولة، كما في الحديث: إن الرقى والتولة والتمائم شرك، فالتولة معناها أن تعمل المرأة أو الرجل ما يسبب بغض زيد لامرأته، أو بغضها لزوجها، وذلك بواسطة الجن ودعائهم والاستغاثة بهم ونحو ذلك، حتى يتسلطوا على هذا الرجل أو على المرأة بأشياء تجعلها تبغض زوجها أو تجعله يبغض زوجته، وينفر منها، وهذا من أقبح المنكرات، وظلم للعباد، ومع ذلك فهو في نفسه شرك؛ لأنه إنما يتوسل إليه بواسطة الجن ودعائهم والاستغاثة بهم، نسأل الله العافية، فقد جمع بين الشرك والظلم للعباد، نعوذ بالله. نعم. المقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/18349/حكم-دعاء-الاولياء-وسوال-الكهنة-والتولة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88610.mp3","categories":["السحر والكهانة"]},{"id":19164,"question":"رسالة وصلت إلى البرنامج من بغداد وباعثها أحد المستمعين من هناك يقول أخوكم أبا عمر، يسأل ويقول: لقد قرأت سورة الجن، وقرأت تفسيرها، ولم أفهم إلا الشيء القليل، والسؤال الذي يخطر ببالي دائمًا وأبدًا وهو: هل يمكن للبشر أن يصادق الجني الصالح؟ وهل يمكن مشاهدة هؤلاء الجن؟ وموضوع الجن موضوع طويل عريض حيث أنه دوخني - كما يقول - وأقلقني، أرجو إجابتي جزاكم الله خيرًا.","title":"حكم مصادقة الجن","answer":"الجواب: ليس للمسلم أن يصادق الجن؛ لأنه لا يأمنهم، ولا يعرف أحوالهم، وليس له أن يصادقهم، ولكن من عرف منهم بالخير، وأرشده إلى الخير؛ يدعو له بالتوفيق والسداد، والهداية والحمد لله. أما أنه يصادقهم فلا يصادقهم؛ لأنه لا يعرفهم كما ينبغي، وقد يكون منافقًا، ولا يعرف حاله، يتظاهرون بالإسلام، ولكن من أظهر له الإسلام دعا له بالخير، ومن ادعى له أنه مسلم دعا له بالتوفيق، والثبات على الحق، وينصحه، ويأمره بالمعروف، وينهاه عن المنكر والحمد لله، ولا يصادقه يتخذه صديقًا ويأمنه في كل شيء لا، إنما يدعو له بالتوفيق يدعو له بالهداية، ويشكره إذا أحسن إليه إذا أرشده إلى الخير، أو دله على خير، أو أمره بمعروف، أو نهاه عن منكر يقول: جزاك الله خيرًا، وما أشبه ذلك، أمره بالصلاة، أيقظه للصلاة قال: جزاك الله خيرًا، قال له: اجتهد في قراءة القرآن قال: جزاك الله خيرًا، أمره بمعروف نهاه عن منكر يقول: جزاك الله خيرًا. وأما كونه يراهم فالغالب أنه لا يراهم مثلما قال الله جل وعلا: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ[الأعراف:27]، الغالب أننا لا نراهم، وقد يتشكلون، ويراهم الإنسان في أشكال حيات، أو كلاب، أو سنور، أو حية .. أو ما أشبه ذلك قد يراهم في أشكال كما وقع قديمًا وحديثًا. وأما أنه يراه على صورته التي خلق عليها فقد لا يجزم بذلك، وقد لا يعرف ذلك؛ لأنهم أشكال لا نعرفها، أشكال وألوان كثيرة، لكن قد يتصورون في صور معروفة من الحيات، أو الكلاب، أو السنور أو غير ذلك كما هو واقع عرفه الناس، ونقله الناس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18363/حكم-مصادقة-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79808.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19222,"question":"أخت لنا من الجزائر تقول: (س. ب. م. ب) تقول: لقد ذكر السحر في كتاب الله، وهذا يؤكد كل التوكيد أن السحر شيء لا بد أن نؤمن بوجوده، وهذه هي مشكلتي، أنا أبلغ من العمر ثمان وعشرين سنة، ولم أتزوج بعد، وعندي شك بأنني مسحورة، ما هو الطريق الذي أسلكه حتى يبتعد عني ما أخافه؟ جزاكم الله خيرًا.","title":"حكم من تشك أنها مسحورة لأنها لم تتزوج وعلاج ذلك","answer":"الجواب: هذه يا بنتي أوهام، لا ينبغي لك أن تعتقديها، هذه أوهام وليست سحرًا، ولكنها الأوهام التي تخيف الناس، إذا تعطل شيء من شئونهم توهموا أشياء، فلا ينبغي لك أن تعتقدي هذا، نعم السحر موجود وله أسباب، لكن ليس تعطل الزواج أو تعطل بيع السلعة أو طول المرض يدل على السحر، بل قد يقع لأسباب أخرى. وإذا كنت قد شعرتي من أحد أنه فعل شيئًا أوجب لك ما يضرك تعالجه والحمد لله، العلاج موجود في كلام الله وكلام رسوله صلى الله عليه وسلم، فأحسن علاج وأولى علاج القرآن الكريم تلاوة الآيات والنفث بها على المسحور، فإن هذا من أسباب الشفاء، الله جعل كتابه شفاء من كل داء، وشفاء من كل سوء كما قال : قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، وقال : يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57]، وقال سبحانه: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ [الإسراء:82].  فالقرآن كله شفاء، ولا سيما إذا قرأ القارئ المؤمن المعروف بالاستقامة إذا قرأ على المريض ونفث عليه ودعا له، فلا شك أن هذا من أسباب الإجابة، وقد كان النبي ﷺ يرقى، قد كان يرقي بعض أصحابه عليه الصلاة والسلام، وقد رقاه جبرائيل، فالرقية أمر معروف، في الحديث: لا رقية إلا من عين أو حمة، يعني: لا رقية أولى وأشفى إلا من عين أو حمة، و(العين) من عين العائن، و(الحمة): سم ذوات السموم، فالسحر يزال، إذا ظنت المرأة أنها مسحورة أو الرجل بقرائن وأمارات فليستعمل ما شرع الله من الدعاء وسؤال الله العافية، ولا مانع أن يستعين ببعض أهل العلم المعروفين بالخير للقراءة عليه والنفث عليه، وذلك من أسباب الشفاء. ومن أسباب الشفاء أيضًا قراءة آيات السحر التي في سورة الأعراف ويونس وطه في إناء، ثم يقرأ معها آية الكرسي و قل هو الله أحد والمعوذتين، ثم يشرب منها ماء ثلاث غرفات .. ثلاث حسوات ثم يغتسل بالباقي، هذا مجرب في زوال السحر إذا كان موجود سحر، مجرب في زوال السحر، ومجرب في شفاء الرجل إذا حبس عن زوجته. وإن جعل في الماء سبع ورقات من السدر الأخضر، دقها وجعلها في الماء كان أيضًا من أسباب الشفاء، نبه على هذا كثير من أهل العلم، ونبه عليه الشيخ عبد الرحمن بن حسن في كتابه فتح المجيد في شرح باب ما جاء في النشرة. فالمقصود أن هذا بحمد الله له علاج مثل سائر الأمراض له علاج، فالعلاج من أعظم الأسباب التي يشفي الله بها العبد إذا صدق، وأخلص لله وحسنت نيته وضرع إلى الله وسأله العافية، فهو سبحانه قريب مجيب، وهو القائل: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، والله المستعان. نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/18420/حكم-من-تشك-انها-مسحورة-لانها-لم-تتزوج-وعلاج-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89008.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19321,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمعة هدى ، أختنا عرضنا جزءاً من أسئلتها في حلقتين مضتا وفي هذه الحلقة بقي لها مجموعة من الأسئلة نرجو أن نتمكن من عرض بعض منها.في سؤالها الأول تقول: كيف يؤثر السحر على الناس مع أنه لا يحصل شيء إلا بإذن الله تعالى، وهل يجوز أن أذهب إلى شيخ لأرى هل من أحد ضرني إذا كنت أشك في ذلك؟ أرجو الإفادة والتوضيح جزاكم الله خيراً؟","title":"السحر ومدى تأثيره وكيفية علاجه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دل كتاب الله  وسنة رسوله عليه الصلاة والسلام على أن السحر قد يقع بالنسبة إلى بعض الناس وقد يؤثر في المسحور بإذن الله  كما قال الله : وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102]. فبين سبحانه أنهم قد يضرون به لكن بإذن الله، يعني بقضاء الله وقدره، ثم قال بعدها: وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ [البقرة:102]، يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102]، يعني: باعوا أنفسهم لو كانوا يعلمون، وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:103]. فهذا يدل على خطر السحر، وأن صاحبه لا خلاق له عند الله، يعني: لاحظ له ولا نصيب، وأنه ضد الإيمان وضد التقوى وأنه كفر، كما قال عن الملكين أنهم يقولان لمن يتعلم: إنه كفر، فَلا تَكْفُرْ [البقرة:102]، وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا [البقرة:102]، يعني: للمتعلم: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102]. فدل ذلك على أن تعلم السحر وتعليمه والعمل به كفر -نسأل الله العافية- وما ذاك إلا لأنه عبادة للشياطين وتقرب إليهم بالذبائح والنذور والدعاء والاستغاثة ونحو ذلك، فلا يكون الساحر ساحرًا إلا بتقربه للشياطين والجن وعبادتهم من دون الله  فقد يقع تأثر في المسحور ببغضه لزوجته، أو بغضها لزوجها إذا كانت هي المسحورة؛ ولهذا قال سبحانه: فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102] بين المرء يعني: الرجل، وزوجه يعني: زوجته، وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102]، يعني: لا يضر السحرة أحداً إلا بإذن الله يعني بمشيئته  . فدل ذلك على أن ما يقع من الضرر بمشيئة الله ليس من قدرة الساحر، بل الساحر سبب، والله جل وعلا هو مقدر الأمور سبحانه وتعالى وهو الذي قضاها بحكمته وقدره السابق سبحانه وتعالى، وكل ما في الوجود فهو بمشيئة الله، ما شاء الله كان وما لم يشأ لم يكن، من كفر وسحر ومعاصي وطاعات كله بقدر الله  وله الحكمة البالغة جل وعلا، كما قال : مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا [الحديد:22]، قال تعالى: إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ [القمر:49]، فالأمور كلها بيده  ولا يقع منها شيء في هذه الدنيا إلا بمشيئته سبحانه وتعالى وقدره السابق، فالطاعات بقدره السابق والمعاصي بقدره السابق والعبد له اختيار وله مشيئة يفعل ويختار، ويعرف ما يضره وما ينفعه فهو مؤاخذ باختياره إذا اختار ما يضره، كما أنه مثاب إذا اختار ما ينفعه من طاعات الله ، ولكنه مع هذا تابع لمشيئة الله، كما قال سبحانه: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ [التكوير:28] وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:29]، قال سبحانه: فَمَنْ شَاءَ ذَكَرَهُ [المدثر:55] وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ هُوَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ [المدثر:56] . وقد يكون السحر تخييلًا وتزويرًا ليس له أثر في بدن الإنسان، كما قال جل وعلا في قصة موسى وفرعون: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، فهم أوجدوا حبالًا وعصيًا أمام الناس فظنها الناس حيات في الأرض، وإنما هي حبال وعصي، لكن خيل للناس أنها حيات لما فعلوا من التزوير والتضليل على عيونهم بأشياء عرفوها وأقدرهم الله عليها، حتى ظن العصي والحبال ظنها المشاهدون حيات وخافوا منها، والحقيقة أنها ليست حيات، ولكنها حبال وعصي؛ ولهذا يقول سبحانه: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، بخلاف يد موسى فإنها حقيقة، وبخلاف عصاه فإنها حقيقة، جعل الله العصا حية تسعى، ثم أعادها سبحانه سيرتها الأولى جل وعلا، وهكذا يده جعلها بيضاء ليس فيها مرض ولكنه آية، فعرفت بهذا أيها السائل وأيها المستمع أن السحر له حالان: إحداهما: حقيقية تؤثر في المسحور بمرض أو قتل أو بغضاء بينه وبين صاحبه أو بينه وبين زوجته.\nوالحال الثاني: تخييل وتزوير، وليس لها أثر في نفس الإنسان، ولكنه يخيل إليه أن زوجته غير زوجته، وأن أخاه غير أخاه، وأن صاحبه غير صاحبه وهكذا، فيخيل إليه أشياء تنفره من صاحبه، وتنفره من زوجته، أو تنفرها من زوجها بسبب ما وضعوا من الأشياء التي شوهت منظر الزوج أو الزوجة أو الصاحب؛ حتى صار غير حاله الأولى، فوقعت البغضاء والتغير والتكدر لما حصل من التزوير والتخييل من الساحر بين هذا وهذا، والله المستعان ولا حول ولا قوة إلا بالله. وله علاج والحمد لله، الله جعل له علاجًا من القرآن الكريم؛ فإن الله جعل في القرآن شفاء من كل داء، فالقراءة على المسحور من آيات الله التي نزلت في السحر وآية الكرسي، و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وسورة المعوذتين، هذه إذا قرئت على المسحور وعليه بها ودعي له بالعافية ينفعه الله بذلك، أو تقرأ في ماء ينفث في الماء آيات السحر التي في الأعراف، والتي في يونس، والتي في طه، ثم يقرأ معها آية الكرسي و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين، ثم يشرب منها المسحور أو المسحورة أو المحبوس عن زوجته ثلاث حسوات، ثم يغتسل بالباقي، هذا بإذن الله مجرب لزوال السحر وزوال الحبس الذي حبس عن زوجته، هذا مجرب وواقع والحمد لله، وهو من الدواء النافع المجدي الناجع بحمد الله. وقد يعرف المسحور من سحره في مسامير ينظم بعضها في بعض، أو في شعر عقد بعضه ببعض أو خرق أو أشباه ذلك قد يعرفها المسحور، فإذا عرفها وأزالها بطل السحر، والله المستعان، ولا حول ولا قوة إلا بالله، والآيات التي تقرأ من سورة الأعراف قوله تعالى: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف:119]، ومن سورة يونس: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ [يونس:79] فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ [يونس:80] فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ [يونس:81] وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:82]، وفي سورة طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:69]، فهذه الآيات وآية الكرسي و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] و قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1. كلها تقرأ في الماء أو على المسحور أو المحبوس عن زوجته، ويدعى له بالشفاء والعافية بالدعاء المشهور الذي علمه النبي أصحابه عليه الصلاة والسلام، اللهم رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاء لا يغادر سقمًا، وإذا كررها ثلاثًا كان أحسن؛ لأنه عليه الصلاة والسلام كان إذا دعا دعا ثلاثًا، وهكذا الدعاء المشهور الذي رقى به جبرائيل النبي عليه الصلاة والسلام باسم الله أرقيك، من كل شيءٍ يؤذيك، ومن شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، هذا أيضًا ينبغي أن يكرر ثلاثًا، كما فعل جبرائيل مع النبي ﷺ فإنه رقاه بهذه الرقية العظيمة، باسم الله أرقيك من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، وإذا دعا له معه بدعوات أخرى فلا بأس، من الدعوات الطيبة، كاللهم اشفه وعافه، اللهم أزل عنه السوء، اللهم أبرئه من مرضه، نحو هذه الدعوات لا بأس، كله طيب.  المقدم: بارك الله فيكم وجزاكم الله خيراً، شيخ عبد العزيز كون السحر يقع هل يخرج عن قدرة الله وإرادته؟ الشيخ: مثلما تقدم، كله بمشيئة الله، مثلما قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] .\nفالشيء كله بإذن الله وقضائه، إذا أراده سبحانه وقع، وإذا ما أراده لم يقع، ولو فعل الساحر ما فعل.  وهناك أشياء ينبغي التحرز منها ومن غير هؤلاء وهي: التعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساء ثلاث مرات، وقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات صباحًا ومساء، كل هذا من أسباب السلامة من السحر والعين وغير ذلك، كذلك قراءة آية الكرسي بعد كل صلاة وقراءتها عند النوم، كذلك قراءة قل هو الله أحد والمعوذتين بعد كل صلاة مرة، وبعد الفجر والمغرب ثلاث مرات، كل هذا من أسباب العافية من كل سوء بإذن الله عز وجل.  المقدم: جزاكم الله خيرًا، شيخ عبد العزيز سمعت من بعض طلبة العلم إنكاره للسحر حتى أنه قال: ائتوا بالسحرة ليسحروني إن كانوا صادقين، توجيهكم لو سمحتوا ولاسيما إذا كانت هذه العبارة من شخصٍ مشهور وله شعبية لا بأس بها؟ الشيخ: هذا جهل وغلط، هذه المقالة تصدر عن جهل، فقد سحر النبي ﷺ وهو أفضل الخلق، وقد صحت الأحاديث عن رسول الله ﷺ أنه سحر وعافاه الله من ذلك وشفاه الله سبحانه وتعالى، هذا شيء معروف، وقد أجمع المسلمون على أنه يقع بإذن الله سبحانه وتعالى، لكن بعضه يؤثر على المريض وبعضه بالتخييل كما تقدم. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18524/السحر-ومدى-تاثيره-وكيفية-علاجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_895/nour_89501.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19347,"question":"حدثت قصة سأرويها لكم، وأريد تفسيرا أو نصحا عن موضوعها، لنا جار له ابنة تبلغ من العمر الثامنة عشرة، مرضت بمرض نفسي وذهب بها إلى الأطباء ولم تستفد شيئا، ثم ذهب بها إلى الكهنة والمشعوذين، وقالوا: إن بها جنا ونحن سوف نخرجه، ولبثت البنت عندهم فترة وجيزة من يوم واحد، وعادت إلى البيت طبيعية ليس فيها شيء، وهي الآن تعيش حالة طبيعية مستقرة في بيت أبيها وجهونا لو تكرمتم جزاكم الله خيرًا؟","title":"حقيقة شفاء الكهان والمشعوذين للمرضى","answer":"الجواب: هذا قد يقع من الجن وشياطينهم، فقد يتعدون على امرأة أو على رجل بأسباب المرض، فيمرض، ثم إذا فزع إليهم وهرع إليهم ولي المرأة أو ولي الرجل وطلب منهم النجدة ساعدوا في ذلك وأزالوا ما فعلوا من الشر؛ حتى يغروا الناس ويخدعوهم، وحتى يدعوهم بهذا إلى الشرك، وإلى تعظيم الجن والشياطين، واللجوء إليهم ودعائهم والاستغاثة بهم ونحو ذلك، هذا من مكائد الشياطين ومن خبثهم وأعمالهم الخبيثة. فالواجب على المؤمن ألا يغتر بهذا، وألا يذهب إليهم، وألا يلتجئ إليهم وألا يسألهم، كما قال النبي ﷺ في الحديث الصحيح: من أتى عرافا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، «وقال ﷺ لما سئل عن الكهان، قال: لا تأتوهم، قال: ليسوا بشيء، وقال: من أتى كاهنًا فصدقه بما يقول، فقد كفر بما أنزل على محمد صلى الله عليه وسلم، وقال: ليس منا من سحر أو سحر له، أو تكهن أو تكهن له، أو تطير أو تطير له، ووجود هذا منهم وكيدهم للناس، وهذا العمل منهم ولعبهم لهم، هذا لا يسوغ الذهاب إليهم والمجيء إليهم بل يجب أن يحذروا، وأن يبتعد عنهم، وأن يعالج من أصيب بهذه الأمراض بالعلاج الشرعي بالقراءة التي شرعها الله، فإن القراءة دواء تداوي به المرضى من الجن وغيرهم، يقرأ عليه المؤمن طالب العلم بما تيسر من القرآن ويدعو له، ويزول الضرر بإذن الله، وهذا أمر مجرب، قد فعله الأئمة والعلماء من قديم الزمان وحديثه، ونفع الله بذلك، ولو قدر أنه مات بسبب ذلك، فإنه ما مات إلا بأجله، حيث قدر الله أن يموت بهذا المرض، وبهذا الشيء الذي يتوهمون أنه من عمل السحرة أو الجن، فلا ينبغي لعاقل أن يؤثر حظه العاجل بتوهم الصحة على أيديهم، أو العلاج على أيديهم بما يضره في دينه ويغضب الله عليه سبحانه وتعالى، فكونه يلتزم بالأمر الشرعي، والعلاج الشرعي، ولو فرض أنه مات، ما مات إلا بأجله، هذا هو الواجب عليه، وليس له أن يلجأ إلى السحرة أو الكهنة، بزعمه خوفًا من الموت كل هذا من أبطل الباطل، ومن أعظم الفساد في الأرض، وأيضا من أعظم المحادة لدين الله، والتعدي لما شرعه الله  والله المستعان.","link":"https://binbaz.org.sa/fatwas/18555/حقيقة-شفاء-الكهان-والمشعوذين-للمرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89904.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19349,"question":"يقول أخونا: يقول: بعض الناس: إن هناك شيطان قد أسلم وشيطان كفر، هل ما يقال صحيح؟","title":"وجود المسلم والكافر في الجن","answer":"الجواب:\n\nالجن فيهم المسلم وفيهم الكافر، والشيطان هو المتمرد، شياطين الجن متمردهم، وشياطين الإنس متمردهم، فذرية الشيطان من الشياطين هم على حالهم شياطين يصدون الناس عن الهدى، ومن هداه الله من الجن ما يسمى شيطان، الشيطان هو الذي يتمرد عن الحق والهدى ويتبع جده الشيطان في الباطل، ومن هداه الله منهم كان من جنسنا له فضله وله ما وعد الله من الجنة والخير، كما قال الله  في سورة الجن: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ كُنَّا طَرَائِقَ قِدَدًا [الجن:11]، فإذا أسلم من تشيطن منهم ورجع إلى الإسلام وتمسك بالإسلام فهو مثل الإنسي الذي كان كافرًا ثم رجع إلى الإسلام وهداه الله.\n\nفالجن والإنس فيهم الكافر وفيهم المسلم وفيهم المبتدع وفيهم العاصي وفيهم الجهمي وفيهم المرجي وفيهم الرافضي وفيهم غير ذلك، كما قال سبحانه: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ [الجن:11] ثم قال بعده: كُنَّا طَرَائِقَ قِدَدًا [الجن:11] يعني: أقسام متفرقة مطلقة متنوعة فيهم الطيب والخبيث، فيهم الصالح والطالح، فيهم صاحب السنة وصاحب البدعة، وقال في الآية وما بعدها: وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَ فَمَنْ أَسْلَمَ فَأُوْلَئِكَ تَحَرَّوْا رَشَدًا ۝ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا [الجن:14-15] القاسط: العادل عن الحق، يقال: قسط؛ إذا جار، أما أقسط فهو العادل، ومنه قوله جل وعلا: إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] أهل العدل والفضل والبصيرة، فالمقسط: صفة مدح وهو الذي التزم الحق واعتدل وأخذ بالعدالة، والقاسط: المائل عن الحق، الذي جار عن الحق وأبى اتباع الحق، ولهذا قال سبحانه: وَأَمَّا الْقَاسِطُونَ يعني: الجائرون المنحرفون عن الحق فَكَانُوا لِجَهَنَّمَ حَطَبًا.\n\nفهكذا يقال في الجن والإنس، فهم سواء: من ترك شركه وباطله، ودخل في الإسلام فله ما للمسلمين، من الجن والإنس، وعليه ما عليهم، ومن بقي في شيطنته وكفره وضلاله، فله ما لأصحابه من جن أو إنس، ومن استقر على الهدى ومضى على الهدى، وسار على الهدى، فله ما وعد الله به المهتدين، والله المستعان.\n\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18554/وجود-المسلم-والكافر-في-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89903.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19570,"question":"سماحة الشيخ! هذا سائل يقول: هل توجد آيات من القرآن الكريم معينة تقرأ على المسحور والذي به مس، ومن أصيب بالعين هل هم سواء؟","title":"الآيات التي يتداوى بها من السحر والعين والمس","answer":"الجواب: القرآن كله شفاء، ولكن من أنفع ذلك الفاتحة، كونه يقرأ الحمد سبع مرات يكررها، وآية الكرسي، وآيات السحر التي في الأعراف، ويونس، وطه، والشعراء آيات السحر، كل هذا من أنفع العلاج، مع قراءة قل هو الله أحد والمعوذتين ثلاث مرات، كل هذا من العلاج ..... وكل القرآن شفاء، كلما قرأ فهو من أسباب الشفاء والعافية؛ لكن هذه بوجه أخص من أعظم أسباب الشفاء، الفاتحة تكرارها سبع مرات، آية الكرسي، كذلك آيات السحر التي في طه وغيرها، في يونس وغيرها، في سورة يونس وغيرها وفي سورة طه، وفي سورة الشعراء كل هذه من أسباب الشفاء مع قراءة قل هو الله أحد والمعوذتين. نعم. المقدم: حفظكم الله سماحة الشيخ! المريض بمرض نفسي، وضيق الصدر، وأيضًا المريض المصاب بمرض عضوي هل يقرأ على نفسه من القرآن؟ الشيخ: نعم يرقي نفسه، كان النبي يرقي نفسه عليه الصلاة والسلام، فالإنسان يرقي نفسه كل ذلك مطلوب مشروع، ومن أهم الرقية أن يرقي نفسه بالفاتحة، وقل هو الله أحد والمعوذتين، وآية الكرسي هذا من أفضل الرقية، وإذا قرأ الفاتحة كررها سبعًا وقل هو الله أحد والمعوذتين كررها ثلاثًا كما كان النبي يفعل ﷺ، كان عند النوم يرقي نفسه بـقل هو الله أحد والمعوذتين في يديه ثلاث مرات، يمسح بهما على ما أقبل من جسده عليه الصلاة والسلام. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18826/الايات-التي-يتداوى-بها-من-السحر-والعين-والمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94716.mp3","categories":["الطب والتداوي","السحر والكهانة"]}]
